import type { ImportedContentSourceFile } from '../librarySources';

export const bigby_presents_glory_of_the_giants_source: ImportedContentSourceFile = JSON.parse("{\"schemaVersion\":\"ddbcc-v1\",\"sourceId\":\"bigbys\",\"label\":\"Bigby Presents: Glory of the Giants\",\"category\":\"supplement\",\"aliases\":[],\"description\":\"Imported from 5etools data (source BGG).\",\"content\":{\"species\":[],\"classes\":[],\"subclasses\":[{\"id\":\"bigbys-barbarian-path-of-the-giant\",\"classId\":\"barbarian\",\"name\":\"Path of the Giant\",\"description\":\"Path of the Giant subclass for the Barbarian.\",\"features\":[{\"id\":\"bigbys-path-of-the-giant-giant-power-0\",\"name\":\"Giant Power\",\"description\":\"3rd-Level Path of the Giant Feature When you choose this path, you learn to speak, read, and write Giant or one other language of your choice if you already know Giant. Additionally, you learn a cantrip of your choice: either druidcraft or thaumaturgy. Wisdom is your spellcasting ability for this spell.\",\"level\":3,\"source\":\"Bigby Presents: Glory of the Giants\"},{\"id\":\"bigbys-path-of-the-giant-giant-s-havoc-1\",\"name\":\"Giant's Havoc\",\"description\":\"3rd-Level Path of the Giant Feature Your rages pull strength from the primal might of giants, transforming you into a hulking force of destruction. While raging, you gain the following benefits: Crushing Throw: When you make a successful ranged attack with a thrown weapon using Strength, you can add your Rage Damage bonus to the attack's damage roll. Giant Stature: Your reach increases by 5 feet, and if you are smaller than Large, you become Large, along with anything you are wearing. If there isn't enough room for you to increase your size, your size doesn't change.\",\"level\":3,\"source\":\"Bigby Presents: Glory of the Giants\"},{\"id\":\"bigbys-path-of-the-giant-path-of-the-giant-2\",\"name\":\"Path of the Giant\",\"description\":\"Barbarians who walk the Path of the Giant draw strength from the same primal forces as giants. As they rage, these barbarians surge with elemental power and grow in size, taking on forms that evoke the glory of giants. Some barbarians look like oversized versions of themselves, perhaps with a hint of elemental energy flaring in their eyes and around their weapons. Others transform more dramatically, taking on the appearance of an actual giant or a form similar to an Elemental, wreathed in fire, frost, or lightning.\",\"level\":3,\"source\":\"Bigby Presents: Glory of the Giants\"},{\"id\":\"bigbys-path-of-the-giant-elemental-cleaver-3\",\"name\":\"Elemental Cleaver\",\"description\":\"6th-Level Path of the Giant Feature Your bond with the elemental might of giants grows, and you learn to infuse weapons with primordial energy. When you enter your rage, you can choose one weapon that you are holding and infuse it with one of the following damage types: acid, cold, fire, thunder, or lightning. While you wield the infused weapon during your rage, the weapon's damage type changes to the chosen type, it deals an extra 1d6 damage of the chosen type when it hits, and it gains the thrown property, with a normal range of 20 feet and a long range of 60 feet. If you throw the weapon, it reappears in your hand the instant after it hits or misses a target. The infused weapon's benefits are suppressed while a creature other than you wields it. While raging and holding the infused weapon, you can use a bonus action to change the infused weapon's current damage type to another one from the damage type options above.\",\"level\":6,\"source\":\"Bigby Presents: Glory of the Giants\"},{\"id\":\"bigbys-path-of-the-giant-mighty-impel-4\",\"name\":\"Mighty Impel\",\"description\":\"10th-Level Path of the Giant Feature Your connection to giant strength allows you to hurl both allies and enemies on the battlefield. As a bonus action while raging, you can choose one Medium or smaller creature within your reach and move it to an unoccupied space you can see within 30 feet of yourself. An unwilling creature must succeed on a Strength saving throw (DC equals 8 + your proficiency bonus + your Strength modifier) to avoid the effect. If, at the end of this movement, the thrown creature isn't on a surface or liquid that can support it, the creature falls, taking damage as normal and landing prone.\",\"level\":10,\"source\":\"Bigby Presents: Glory of the Giants\"},{\"id\":\"bigbys-path-of-the-giant-demiurgic-colossus-5\",\"name\":\"Demiurgic Colossus\",\"description\":\"14th-Level Path of the Giant Feature The primordial power of your rage intensifies. When you rage, your reach increases by 10 feet, your size can increase to Large or Huge (your choice), and you can use your Mighty Impel to move creatures that are Large or smaller. In addition, the extra damage dealt by your Elemental Cleaver feature increases to 2d6.\",\"level\":14,\"source\":\"Bigby Presents: Glory of the Giants\"}],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"}],\"backgrounds\":[{\"id\":\"bigbys-giant-foundling\",\"name\":\"Giant Foundling\",\"description\":\"Giant Foundling background.\",\"skillProficiencies\":[\"Intimidation\",\"Survival\"],\"languageCount\":1,\"grantedFeatNames\":[\"Strike Of The Giants\"],\"equipment\":[{\"name\":\"Backpack\",\"type\":\"gear\"},{\"name\":\"Traveler's Clothes\",\"type\":\"gear\"},{\"name\":\"Pouch\",\"type\":\"gear\"},{\"name\":\"Choose 1\",\"type\":\"gear\",\"alternatives\":[{\"name\":\"small stone that reminds you of home\",\"type\":\"gear\"},{\"name\":\"sprig that reminds you of home\",\"type\":\"gear\"}]}],\"feature\":{\"name\":\"Feature: Strike of the Giants\",\"description\":\"You gain the Strike of the Giants feat.\"},\"personalityTraits\":[\"What I lack in stature compared to giants, I make up for with sheer spite.\",\"I insist on being taken seriously as a full-grown adult. Nobody talks down to me!\",\"Crowded spaces make me uncomfortable. I'd much rather be in an open field than a bustling tavern.\",\"I embrace my shorter stature. It helps me stay unnoticed—and underestimated.\",\"Every avalanche begins as a single pebble.\",\"The world always feels too big, and I'm afraid I'll never find my place in it.\"],\"ideals\":[],\"bonds\":[],\"flaws\":[],\"suggestedCharacteristics\":[\"What I lack in stature compared to giants, I make up for with sheer spite.\",\"I insist on being taken seriously as a full-grown adult. Nobody talks down to me!\",\"Crowded spaces make me uncomfortable. I'd much rather be in an open field than a bustling tavern.\",\"I embrace my shorter stature. It helps me stay unnoticed—and underestimated.\",\"Every avalanche begins as a single pebble.\",\"The world always feels too big, and I'm afraid I'll never find my place in it.\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-rune-carver\",\"name\":\"Rune Carver\",\"description\":\"Rune Carver background.\",\"skillProficiencies\":[\"History\",\"Perception\"],\"toolProficiencies\":[\"One type of artisan's tools\"],\"grantedFeatNames\":[\"Rune Shaper\"],\"equipment\":[{\"name\":\"Any artisan's tools\",\"type\":\"tool\"},{\"name\":\"small knife\",\"type\":\"gear\"},{\"name\":\"Whetstone\",\"type\":\"gear\"},{\"name\":\"Common Clothes\",\"type\":\"gear\"},{\"name\":\"Pouch\",\"type\":\"gear\"}],\"feature\":{\"name\":\"Feature: Rune Shaper\",\"description\":\"You gain the Rune Shaper feat.\"},\"personalityTraits\":[\"Is it practical to learn an ancient language that is rarely spoken? No. But is it fun? Very.\",\"I learned one of my ancestors was a lauded rune carver whose story was lost to time. I seek to rekindle that legacy.\",\"The old, traditional markings of runecraft look so boring. Why not give my runes some flair?\",\"In my studies of runes, I strive to understand how great civilizations of the past fell, so I can prevent it from happening to societies of the present.\",\"Life may be a whirlwind of chaos, but whenever I create my runes, I feel at peace.\",\"My brain struggles to process words written in ink, but the feeling of carved runes makes my mind sing.\"],\"ideals\":[],\"bonds\":[],\"flaws\":[],\"suggestedCharacteristics\":[\"Is it practical to learn an ancient language that is rarely spoken? No. But is it fun? Very.\",\"I learned one of my ancestors was a lauded rune carver whose story was lost to time. I seek to rekindle that legacy.\",\"The old, traditional markings of runecraft look so boring. Why not give my runes some flair?\",\"In my studies of runes, I strive to understand how great civilizations of the past fell, so I can prevent it from happening to societies of the present.\",\"Life may be a whirlwind of chaos, but whenever I create my runes, I feel at peace.\",\"My brain struggles to process words written in ink, but the feeling of carved runes makes my mind sing.\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"}],\"spells\":[],\"equipment\":[{\"id\":\"bigbys-adze-of-annam\",\"name\":\"Adze of Annam\",\"type\":\"weapon\",\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":7,\"description\":\"This massive adze is said to have been wielded by All-Father Annam, not as a weapon but as the tool he used to shape the various worlds of the Material Plane eons ago. Random Properties. The adze has the following random properties, determined by rolling on the appropriate table in the Dungeon Master's Guide: 2 minor beneficial properties 1 major beneficial property 2 minor detrimental properties Magic Weapon. When a creature attunes to the adze, the artifact magically adjusts its size so that creature can wield it as a greataxe. The adze is a magic weapon that grants a +3 bonus to attack and damage rolls made with it. On a hit, the adze deals an additional 3d12 force damage. It also deals double damage to objects and structures. Divine Mattock. As an action, you can call upon the might of the All-Father and use the adze to cast move earth or fabricate. Once this property is used, it can't be used again until the next dawn.\",\"weaponCategory\":\"martial\",\"weaponType\":\"melee\",\"damage\":\"1d12\",\"damageType\":\"slashing\",\"properties\":[\"H\",\"2H\"]},{\"id\":\"bigbys-bigby-s-beneficent-bracelet\",\"name\":\"Bigby's Beneficent Bracelet\",\"type\":\"gear\",\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"This gorgeous jewelry piece, crafted by the wizard Bigby himself, consists of four gold rings attached via delicate chains to a wrist cuff studded with sapphires and diamonds. Random Properties. The bracelet has the following random properties, determined by rolling on the appropriate table in the Dungeon Master's Guide: 1 minor beneficial property 1 major beneficial property 1 minor detrimental property Dexterous Fingers. While wearing the bracelet, you can cast mage hand. Force Sculpture. By focusing and channeling the bracelet's magic for 1 minute, you can create a spectral copy of a Large or smaller nonmagical object. The copy appears in an unoccupied space within 10 feet of you, and it is made of tangible but translucent force that mimics the size, weight, and other properties of the object it's copying. The copy must appear on a surface or liquid that can support it. Creatures can touch and interact with the copy as if it were a nonmagical object. The copy is immune to all damage and can't be dispelled, but a disintegrate spell destroys it immediately. Otherwise, the copy disappears after 8 hours or when you dismiss it as an action. The bracelet can create up to three copies and regains all expended uses at dawn. Helpful Hand. As an action, you can use the bracelet to cast Bigby's hand as a 9th-level spell (spell attack bonus +13). When you cast the spell this way, the spell doesn't require concentration. Once this property is used, it can't be used again until the next dawn.\",\"properties\":[]},{\"id\":\"bigbys-crown-of-the-wrath-bringer\",\"name\":\"Crown of the Wrath Bringer\",\"type\":\"gear\",\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"This jagged iron circlet bears ornaments in the shape of the enemy rune. When worn, the crown glows with pale light as it draws upon the wearer's fury to strike opponents with vicious terror. When you make an attack roll against a creature and hit it while wearing this crown, you can spend and roll one of your unspent Hit Dice. The creature takes extra psychic damage equal to the number rolled. Invoking the Rune. As an action, you can invoke the crown's rune to cast the fear spell (save 15) with it; the spell has a duration of 1 minute and doesn't require concentration. Once the rune has been invoked, it can't be invoked again until the next dawn.\",\"properties\":[]},{\"id\":\"bigbys-delver-s-claws\",\"name\":\"Delver's Claws\",\"type\":\"gear\",\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"The back of this weatherworn leather glove is adorned with three large metal hooks shaped like a mole's claws. Stitched into the glove's palm is the mountain rune. The glove is considered a simple melee weapon with the finesse and light properties, and it deals 1d4 slashing damage on a hit. While attuned to the glove, you gain a burrowing speed equal to your walking speed and blindsight to 15 feet. Invoking the Rune. As an action, you can invoke the glove's rune to bolster yourself with the sturdiness of the earth. Spend and roll a number of your unspent Hit Dice up to a maximum equal to your proficiency bonus. You then regain a number of hit points equal to the total roll plus your Constitution modifier. Once the rune has been invoked, it can't be invoked again until the next dawn.\",\"properties\":[]},{\"versatileDamage\":\"1d8\",\"id\":\"bigbys-elven-thrower\",\"name\":\"Elven Thrower\",\"type\":\"weapon\",\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":3,\"description\":\"You gain a +3 bonus to attack and damage rolls made with this magic weapon. It has the thrown property with a normal range of 20 feet and a long range of 60 feet. When you hit with a ranged attack using this weapon, it deals an extra 1d8 damage or, if the target is a Giant, 2d8 damage. Immediately after the attack, the weapon flies back to your hand.\",\"weaponCategory\":\"simple\",\"weaponType\":\"melee\",\"damage\":\"1d6\",\"damageType\":\"piercing\",\"properties\":[\"T\",\"V\"],\"range\":{\"normal\":20,\"long\":60}},{\"id\":\"bigbys-giant-trinket\",\"name\":\"Giant Trinket\",\"type\":\"gear\",\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"While exploring your home, you discovered some trivial remnant of the ancient inhabitants, as determined by rolling on the Giant Trinkets table. The items in parentheses are the normal-sized objects most analogous to the described giant trinkets. Giant Trinkets: 1 — A giant's toothpick (a dagger); 2 — A giant's handkerchief (a blanket); 3 — A giant's marble (a crystal orb); 4 — A giant's match (a torch); 5 — A giant's letter opener (a longsword); 6 — A giant's thimble (an iron pot)\",\"properties\":[]},{\"id\":\"bigbys-glowrune-pigment\",\"name\":\"Glowrune Pigment\",\"type\":\"gear\",\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"This set of 1d4 + 2 small paint pots contains pigments mixed from crushed luminescent gemstones. This magical paint bestows temporary magical gifts on creatures with runes drawn on their skin with this paint. One paint pot contains enough pigment to paint one rune. A creature can spend 10 minutes to paint one of the following runes onto itself or another creature: Journey Rune. 3 doesn't cost the painted creature extra movement. Life Rune. The painted creature gains 10 temporary hit points and has advantage on death saving throws. Light Rune. The painted creature gains darkvision to a range of 30 feet. If the painted creature already has darkvision from another source, the range of its darkvision increases by 30 feet. Mountain Rune. The painted creature is immune to being knocked prone and has advantage on Strength and Constitution saving throws. Shield Rune. The painted creature has advantage on Dexterity saving throws against effects that deal damage. A creature can benefit from only one painted rune at a time, so a new rune painted on a creature has no effect unless the old one is removed first. The rune's benefits last for 8 hours or until the painted creature uses its action to wipe away the rune.\",\"properties\":[]},{\"id\":\"bigbys-goose-egg-trinket\",\"name\":\"Goose Egg Trinket\",\"type\":\"gear\",\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"Sometimes, an egg laid by a giant goose inexplicably contains some kind of small trinket or minor magic item. Once it lays a golden egg, a giant goose can't do so again for a year and a day. You can use the Goose Egg Trinket table to determine the contents of a golden egg. A giant goose's egg can be a great way to give characters an item that's important to the story of an adventure or your campaign. Goose Egg Trinket: 1 — The egg is empty, but the inside of the shell is inscribed with a poem or an intricate illustration.; 2 — The gold shell encloses a candy egg.; 3 — The egg holds a small toy goose that makes a loud honking noise when squeezed.; 4 — The egg contains a potion of giant strength (hill giant) with no container.; 5 — The egg holds a pearl of power.; 6 — The egg contains a brooch of shielding.; 7 — The egg contains a figurine of wondrous power (silver raven) that activates automatically as the egg is opened, releasing what appears to be a living bird.; 8–12 — The egg is empty.\",\"properties\":[]},{\"toolCategory\":\"Musical Instruments\",\"id\":\"bigbys-harp-of-gilded-plenty\",\"name\":\"Harp of Gilded Plenty\",\"type\":\"tool\",\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"This golden harp is sculpted in the image of the god Iallanis, depicted as a young cloud giant woman. When a creature comes within 5 feet of the harp, the instrument animates and is capable of speaking, singing, and playing by itself. Whenever you attempt to attune to the harp, you must first make either a 15 Charisma (Performance) check or a 20 Charisma (Persuasion) check to convince the harp that you are worthy, attuning to the harp on a success. If you fail, you can't attempt to attune to the harp again until the next dawn. Once you have successfully attuned to the harp, the harp resizes to suit you. Stalwart Song. Whenever you make a Charisma check while attuned to the harp, you can treat a roll of 9 or lower on the die as a 10. Feast of Plenty. If you spend 10 minutes playing the harp, you can cast the heroes' feast spell from it. Once this property is used, it can't be used again until 1d10 + 10 days have passed. Soothing Melody. As an action, you can use the harp to cast the calm emotions spell (save 19). When the spell is cast using the harp, its duration increases to 1 hour, provided you maintain concentration on the spell. This property can be used five times, and it regains all uses at dawn. Sentience. The harp is a sentient, chaotic good object with an Intelligence of 13, a Wisdom of 15, and a Charisma of 20. It has hearing and darkvision to a range of 120 feet. The harp can speak, read, and understand Common and Giant. It can also communicate telepathically with the creature attuned to it. The harp has a dramatic and pompous personality, taking extreme pride in the quality of music produced from its strings. If the harp is shorter than 6 feet tall, it bemoans its height.\",\"properties\":[]},{\"id\":\"bigbys-helm-of-perfect-potential\",\"name\":\"Helm of Perfect Potential\",\"type\":\"gear\",\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"This copper-hued helm contains a shard of the Elemental Chaos embedded in its forehead, surrounded by a motif of a rising sun. Legend says Annam fashioned this helm for his daughter Diancastra to hold the fragment of chaos she used to prove her worth to her father. Random Properties. The helm has the following random properties, determined by rolling on the appropriate table in the Dungeon Master's Guide: 2 minor beneficial properties 1 major beneficial property 1 minor detrimental property Master of Guile. While wearing the helm, you have advantage on Charisma (Deception) and Wisdom (Insight) checks. Arrow of Elemental Havoc. As a bonus action while wearing the helm, you can launch a bolt of searing elemental energy toward a creature you can see within 90 feet of yourself. The target must make a 20 Dexterity saving throw. On a failed save, the creature takes 4d6 acid, cold, fire, lightning, or thunder damage (your choice). On a successful save, the creature takes half as much damage. Spellcasting. The helm has 6 charges and regains 1d6 charges each dawn. As an action while wearing the helm, you can expend 1 or more of its charges to cast one of the following spells (save 20): elemental weapon (1 charge), call lightning (2 charges), wall of fire (3 charges), conjure elemental (4 charges), tsunami (5 charges).\",\"properties\":[]},{\"id\":\"bigbys-horizon-puzzle-cube\",\"name\":\"Horizon Puzzle Cube\",\"type\":\"gear\",\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"A Horizon puzzle cube is an 8-inch magical cube made of gold, iron, crystal, and copper, and it is worth 5,000 gp to a sage or collector. A functioning puzzle cube can be solved with 30 minutes of work and a successful 25 Intelligence (Investigation) check. When the cube is solved, a 30-foot-diameter portal appears before the creature who solved the cube, leading to the northeastern platform of Horizon's Edge. The portal is two-way and remains open for 10 minutes or until a creature uses an action to change the puzzle's configuration. Puzzle cubes don't function while on Horizon's Edge, but a device somewhere in the demiplane allows a cube to function in reverse while the cube is fitted into it.\",\"properties\":[]},{\"id\":\"bigbys-lash-of-immolation\",\"name\":\"Lash of Immolation\",\"type\":\"weapon\",\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":3,\"description\":\"The handle of this dark leather whip bears the fire rune, and embers dance around the whip's tail. You gain a +1 bonus to attack and damage rolls made with this weapon, and on a hit, the whip deals an extra 1d6 fire damage. When you score a critical hit with an attack using this whip, the target also has the restrained condition until the start of your next turn, as fiery bands lash around the target. Invoking the Rune. When you make an attack with the whip and hit, you can use your reaction to invoke the whip's rune. Doing so increases the extra fire damage dealt by the whip to 2d6. Once the rune has been invoked, it can't be invoked again until the next dawn.\",\"weaponCategory\":\"martial\",\"weaponType\":\"melee\",\"damage\":\"1d4\",\"damageType\":\"slashing\",\"properties\":[\"F\",\"R\"]},{\"id\":\"bigbys-longbow-of-the-healing-hearth\",\"name\":\"Longbow of the Healing Hearth\",\"type\":\"weapon\",\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":2,\"description\":\"This ivory longbow is inscribed with a prayer to the god Hiatea, the runes of which are entwined with gilded engravings of wheat stalks and deer antlers. You gain a +3 bonus to attack and damage rolls made with this weapon. If you load no ammunition in the weapon, it produces its own, automatically creating one magic arrow when you pull back the string. The arrow created by the bow vanishes the instant after it hits or misses a target. The bow has 8 charges for the following properties, which you can use while wielding the bow. The bow regains 1d4 + 1 charges daily at dawn. Curative Arrow. When you take the Attack action using the bow, you can expend 1 charge to replace one of your attacks with a blazing arrow of curative magic, which automatically hits one creature you can see within 150 feet of you. The target can then immediately spend and roll one of its unspent Hit Dice and regain a number of hit points equal to the roll plus your Wisdom modifier (minimum of +1). If the target has no unspent Hit Dice remaining, nothing happens. You can use a curative arrow only once per turn. Spellcasting. While holding the bow, you can use an action to expend 1 or more of its charges to cast one of the following spells from it (save 18): create food and water (1 charge), warding bond (2 charges), guardian of faith (3 charges).\",\"weaponCategory\":\"martial\",\"weaponType\":\"ranged\",\"damage\":\"1d8\",\"damageType\":\"piercing\",\"properties\":[\"A\",\"H\",\"2H\"],\"range\":{\"normal\":150,\"long\":600}},{\"id\":\"bigbys-lucent-destroyer\",\"name\":\"Lucent Destroyer\",\"type\":\"weapon\",\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":10,\"description\":\"This magic weapon is a triple-barreled bronze musket. You gain a +1 bonus to attack and damage rolls made with it. It requires no ammunition, its damage is radiant instead of piercing, and it doesn't have the loading property. The base of the weapon is emblazoned with the light rune. Additionally, while attuned to the weapon, you can cast dancing lights from the musket at will. Invoking the Rune. As an action, you can invoke the weapon's rune to cast the sunbeam spell (save 17) with it. Once the rune has been invoked, it can't be invoked again until the next dawn.\",\"weaponCategory\":\"martial\",\"weaponType\":\"ranged\",\"damage\":\"1d12\",\"damageType\":\"piercing\",\"properties\":[\"2H\"],\"range\":{\"normal\":40,\"long\":120}},{\"id\":\"bigbys-mistral-mantle\",\"name\":\"Mistral Mantle\",\"type\":\"gear\",\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"This thick, fur-lined cloak has the frost rune stitched on the hem in silvery blue thread. Frigid wind swirls around the cloak, regardless of the weather. While wearing this cloak, you have resistance to cold damage. Additionally, when you move within 5 feet of a creature, you can cause the cloak's cold wind to buffet the creature. The creature must succeed on a 14 Dexterity saving throw or take 1d6 cold damage and have the prone condition. A creature can be affected by the mantle only once during a turn. Invoking the Rune. As an action, you can invoke the mantle's rune to cast the sleet storm spell (save 14) with it. When you use the mantle to cast the spell, the area of the spell isn't 3 for you, and you can see through the storm, ignoring the normal penalties of a 2 area. Once the rune has been invoked, it can't be invoked again until the next dawn.\",\"properties\":[]},{\"id\":\"bigbys-nimbus-coronet\",\"name\":\"Nimbus Coronet\",\"type\":\"gear\",\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"The design of this bronze circlet resembles swirling clouds. At its center is set a deep-blue stone, upon which is inscribed the cloud rune. While wearing this circlet, you take no damage from falling. Additionally, as a bonus action, you and everything you are wearing or carrying can teleport to an unoccupied space you can see within 15 feet of yourself, reappearing in a puff of shimmering clouds. Invoking the Rune. As an action, you can invoke the circlet's rune to assume a cloudlike form. The form lasts for 1 minute, until you are incapacitated, or until you dismiss it (no action required). While in cloud form, you have a flying speed of 60 feet and resistance to bludgeoning, piercing, and slashing damage. Once the rune has been invoked, it can't be invoked again until the next dawn.\",\"properties\":[]},{\"id\":\"bigbys-orb-of-skoraeus\",\"name\":\"Orb of Skoraeus\",\"type\":\"gear\",\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":8,\"description\":\"Said to be infused with the wisdom and power of the god Skoraeus, this polished stone orb is veined with iridescent crystal that seems to glow from within. The orb is 8 inches in diameter and weighs 8 pounds, making it a palm-sized trinket for a stone giant but a more unwieldy item for a Medium creature to use. While holding this orb, you can use it as a spellcasting focus for your spells. You also gain the following benefits: Abundant Components. The orb has 3 charges and regains all expended charges at dawn. When you cast a spell while holding this orb, you can expend up to 3 charges to ignore the spell's material components with a gold piece cost, up to 300 gp per charge expended. Astute Mind. You gain a +2 bonus to any Constitution saving throw you make to maintain your concentration on a spell. Divine Sight. You can see normally in darkness, both magical and nonmagical, to a distance of 120 feet.\",\"properties\":[]},{\"id\":\"bigbys-prehistoric-figurine-of-wondrous-power-carnelian-triceratops\",\"name\":\"Prehistoric Figurine of Wondrous Power, Carnelian Triceratops\",\"type\":\"gear\",\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"Larger and more roughly hewn than typical figurines of wondrous power, these statuettes depict dinosaurs and related creatures from the earliest days of the world. As an action, you can throw a prehistoric figurine of wondrous power to a point on the ground within 60 feet of yourself while speaking a command word, whereupon the figurine magically transforms into a living creature. If the space where the creature would appear is occupied by other creatures or objects, or if there isn't enough space for the creature, the figurine doesn't become a creature. The creature is friendly to you and your companions. It understands your languages and obeys your spoken commands. If you issue no commands, the creature defends itself but takes no other actions. See the Monster Manual for the creature's statistics. The creature exists for a duration specific to each figurine. At the end of the duration, the creature reverts to its statuette form. It reverts to a figurine early if it drops to 0 hit points or if you use an action to speak the command word again while touching it. When the creature becomes a figurine again, its property can't be used again until a certain amount of time has passed, as specified in the figurine's description. Carnelian Triceratops. This figurine becomes a triceratops for up to 6 hours and can be ridden as a mount. Once it has been used, it can't be used again until 10 days have passed.\",\"properties\":[]},{\"id\":\"bigbys-prehistoric-figurine-of-wondrous-power-jasper-tyrannosaurus-rex\",\"name\":\"Prehistoric Figurine of Wondrous Power, Jasper Tyrannosaurus Rex\",\"type\":\"gear\",\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"Larger and more roughly hewn than typical figurines of wondrous power, these statuettes depict dinosaurs and related creatures from the earliest days of the world. As an action, you can throw a prehistoric figurine of wondrous power to a point on the ground within 60 feet of yourself while speaking a command word, whereupon the figurine magically transforms into a living creature. If the space where the creature would appear is occupied by other creatures or objects, or if there isn't enough space for the creature, the figurine doesn't become a creature. The creature is friendly to you and your companions. It understands your languages and obeys your spoken commands. If you issue no commands, the creature defends itself but takes no other actions. See the Monster Manual for the creature's statistics. The creature exists for a duration specific to each figurine. At the end of the duration, the creature reverts to its statuette form. It reverts to a figurine early if it drops to 0 hit points or if you use an action to speak the command word again while touching it. When the creature becomes a figurine again, its property can't be used again until a certain amount of time has passed, as specified in the figurine's description. Jasper Tyrannosaurus Rex. This figurine, crafted from rare green jasper, becomes a tyrannosaurus rex for up to 1 hour. Once it has been used, it can't be used again until 14 days have passed. Whenever you command the figurine while it's in tyrannosaurus rex form (including commanding it to revert to figurine form), you must roll a d20. On a 1, you lose control of the figurine, and it becomes hostile to you and your companions until it is reduced to 0 hit points, at which point it reverts to figurine form.\",\"properties\":[]},{\"id\":\"bigbys-prehistoric-figurine-of-wondrous-power-kyanite-pteranodon\",\"name\":\"Prehistoric Figurine of Wondrous Power, Kyanite Pteranodon\",\"type\":\"gear\",\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"Larger and more roughly hewn than typical figurines of wondrous power, these statuettes depict dinosaurs and related creatures from the earliest days of the world. As an action, you can throw a prehistoric figurine of wondrous power to a point on the ground within 60 feet of yourself while speaking a command word, whereupon the figurine magically transforms into a living creature. If the space where the creature would appear is occupied by other creatures or objects, or if there isn't enough space for the creature, the figurine doesn't become a creature. The creature is friendly to you and your companions. It understands your languages and obeys your spoken commands. If you issue no commands, the creature defends itself but takes no other actions. See the Monster Manual for the creature's statistics. The creature exists for a duration specific to each figurine. At the end of the duration, the creature reverts to its statuette form. It reverts to a figurine early if it drops to 0 hit points or if you use an action to speak the command word again while touching it. When the creature becomes a figurine again, its property can't be used again until a certain amount of time has passed, as specified in the figurine's description. Kyanite Pteranodon. This figurine becomes a pteranodon for up to 8 hours. If your size is Medium or smaller, you can ride the pteranodon as a mount. Once it has been used, it can't be used again until 7 days have passed.\",\"properties\":[]},{\"id\":\"bigbys-prehistoric-figurine-of-wondrous-power-pyrite-plesiosaurus\",\"name\":\"Prehistoric Figurine of Wondrous Power, Pyrite Plesiosaurus\",\"type\":\"gear\",\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"Larger and more roughly hewn than typical figurines of wondrous power, these statuettes depict dinosaurs and related creatures from the earliest days of the world. As an action, you can throw a prehistoric figurine of wondrous power to a point on the ground within 60 feet of yourself while speaking a command word, whereupon the figurine magically transforms into a living creature. If the space where the creature would appear is occupied by other creatures or objects, or if there isn't enough space for the creature, the figurine doesn't become a creature. The creature is friendly to you and your companions. It understands your languages and obeys your spoken commands. If you issue no commands, the creature defends itself but takes no other actions. See the Monster Manual for the creature's statistics. The creature exists for a duration specific to each figurine. At the end of the duration, the creature reverts to its statuette form. It reverts to a figurine early if it drops to 0 hit points or if you use an action to speak the command word again while touching it. When the creature becomes a figurine again, its property can't be used again until a certain amount of time has passed, as specified in the figurine's description. Pyrite Plesiosaurus. This figurine becomes a plesiosaurus for up to 12 hours and can be ridden as a mount. Once it has been used, it can't be used again until 4 days have passed. While you are riding the plesiosaurus, you can use it to cast water breathing at will.\",\"properties\":[]},{\"id\":\"bigbys-reaper-s-scream\",\"name\":\"Reaper's Scream\",\"type\":\"weapon\",\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":4,\"description\":\"The spikes of this iron morningstar glow with sickly, pale light. The death rune is inscribed on its shaft and inlaid with pearl. You gain a +2 bonus to attack and damage rolls made with this weapon, and attacks with this weapon deal necrotic damage instead of piercing damage. When you attack a creature with this weapon and roll a 20 on the attack roll, you gain 10 temporary hit points. Any creature that hits you with a melee attack while you have 1 or more of these temporary hit points takes 10 necrotic damage. Invoking the Rune. As a bonus action, you can invoke the weapon's rune, unleashing the screams of every creature slain by the weapon in one cacophonous burst. Each creature of your choice within 60 feet of you must succeed on a 15 Wisdom saving throw or have the stunned condition until the start of your next turn. Once the rune has been invoked, it can't be invoked again until the next dawn.\",\"weaponCategory\":\"martial\",\"weaponType\":\"melee\",\"damage\":\"1d8\",\"damageType\":\"piercing\",\"properties\":[]},{\"id\":\"bigbys-ring-of-amity\",\"name\":\"Ring of Amity\",\"type\":\"gear\",\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"This ring is carved from hematite and bears an engraving of the friend rune. When you first attune to this ring, you can touch one willing creature and form a magical bond between the two of you. While this bond lasts, whenever you are subjected to a spell or magical effect that restores hit points, the bonded creature also receives the benefits of the spell or effect. You can bond with a different creature whenever you finish a long rest, provided that you can touch the creature and the creature is willing. A creature can benefit from only one ring of amity's bond at a time. The bond ends if either you or the creature travels to a different plane of existence, if you bond with a different creature at the end of a long rest, or if you sever the bond as a bonus action. Invoking the Rune. When the bonded creature hits a target with an attack roll, you can use your reaction to invoke the ring's rune if you are within 60 feet of the bonded creature. The bonded creature's attack is then turned into a critical hit. Once the rune has been invoked, it can't be invoked again until the next dawn.\",\"properties\":[]},{\"id\":\"bigbys-sanctum-amulet\",\"name\":\"Sanctum Amulet\",\"type\":\"gear\",\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"A black opal pendant hangs at the base of this pearlescent chain. The sacred rune is inscribed on the back of the pendant. While wearing this item, you have resistance to necrotic damage. Additionally, you can cast the spare the dying cantrip using either an action or a bonus action. Invoking the Rune. When a creature you can see within 60 feet of you is reduced to 0 hit points as a result of taking damage, you can use your reaction to invoke the item's rune, causing the pendant to flash with pale light. The creature then instead drops to 1 hit point. Once the rune has been invoked, it can't be invoked again until the next dawn.\",\"properties\":[]},{\"id\":\"bigbys-shield-of-the-blazing-dreadnought\",\"name\":\"Shield of the Blazing Dreadnought\",\"type\":\"shield\",\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":6,\"description\":\"Modeled after the formidable spiked tower shields wielded by some fire giants, this iron shield emanates a constant warmth. You can use a bonus action to activate the shield, causing glowing lava to flow through the shield's grooves for 1 minute. While the shield is active, you gain the following benefits: Blazing Soul. You have immunity to fire damage. Cleansing Fire. As an action, you can cause the shield to flare with the cleansing fire of the god Surtur. Choose one creature you can see within 30 feet of yourself (you can choose yourself). One disease or condition of your choice affecting this creature ends immediately; the condition can be blinded, charmed, deafened, or poisoned. Shield Bash. When you take the Attack action on your turn, you can replace one of your attacks with a shield bash, targeting one creature you can see within 5 feet of yourself. The target must make a Strength saving throw (DC equals 8 + your proficiency bonus + your Strength modifier). On a failed save, the target takes 3d6 bludgeoning damage plus 3d6 fire damage and is knocked prone. On a successful save, the target takes half as much damage only. You can use Shield Bash only once per turn. Once the shield has been activated, it can't be activated again until the next dawn.\",\"properties\":[],\"armorCategory\":\"shield\",\"ac\":2},{\"versatileDamage\":\"1d8\",\"id\":\"bigbys-staff-of-the-rooted-hills\",\"name\":\"Staff of the Rooted Hills\",\"type\":\"weapon\",\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":4,\"description\":\"The hill rune is carved into this gnarled wooden staff. The staff magically resizes to match the height of any creature that attunes to it. The staff can be wielded as a magic quarterstaff that grants a +1 bonus to attack and damage rolls made with it. The first time you hit any creature with the staff on your turn, the creature must succeed on a 12 Strength saving throw or be restrained by spectral vines until the start of your next turn. Invoking the Rune. As an action, you can invoke the staff's rune to cast either hold person (save 12) or speak with plants with the staff. When you cast hold person using the staff, the target is wreathed in spectral vines. Once the rune has been invoked to cast either spell, it can't be invoked again until the next dawn.\",\"weaponCategory\":\"simple\",\"weaponType\":\"melee\",\"damage\":\"1d6\",\"damageType\":\"bludgeoning\",\"properties\":[\"V\"]},{\"id\":\"bigbys-stonebreaker-s-breastplate\",\"name\":\"Stonebreaker's Breastplate\",\"type\":\"armor\",\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":20,\"description\":\"This breastplate is made from marbled granite, though it feels no heavier than a typical metal breastplate. Its chest is emblazoned with the stone rune. While wearing this breastplate, you have resistance to bludgeoning, piercing, and slashing damage and are immune to being knocked prone. Invoking the Rune. As an action, you can invoke the breastplate's rune to cast the wall of stone spell (save 14) with it. When you cast the spell in this way, you have advantage on saving throws made to maintain concentration on the spell. Once the rune has been invoked, it can't be invoked again until the next dawn. This armor consists of a fitted metal chest piece worn with supple leather. Although it leaves the legs and arms relatively unprotected, this armor provides good protection for the wearer's vital organs while leaving the wearer relatively unencumbered.\",\"properties\":[],\"armorCategory\":\"medium\",\"ac\":14},{\"id\":\"bigbys-thunderbuss\",\"name\":\"Thunderbuss\",\"type\":\"weapon\",\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":3,\"description\":\"This magic ranged weapon is a flared pistol with the storm rune engraved along the barrel. You gain a +1 bonus to attack and damage rolls made with it. It requires no ammunition, its damage is thunder instead of piercing, and it doesn't have the loading property. Invoking the Rune. As a bonus action, you can invoke the weapon's rune to launch a ball of energy to a point you can see within 30 feet of yourself. The energy then detonates into a 10-foot-radius sphere of turbulent wind and thunder centered on that point, and each creature in that sphere must make a 14 Constitution saving throw. On a failed save, a creature takes 3d6 thunder damage, and it can't take reactions until the end of your next turn. On a successful save, a creature takes half as much damage only. Once the rune has been invoked, it can't be invoked again until the next dawn.\",\"weaponCategory\":\"martial\",\"weaponType\":\"ranged\",\"damage\":\"1d10\",\"damageType\":\"piercing\",\"properties\":[],\"range\":{\"normal\":30,\"long\":90}},{\"toolCategory\":\"Musical Instruments\",\"id\":\"bigbys-war-horn-of-valor\",\"name\":\"War Horn of Valor\",\"type\":\"tool\",\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"This brass war horn is engraved with the war rune, which glows purple when the horn is blown. You can blow the horn as a bonus action. When you do, if you have the frightened condition, you immediately end that condition on yourself. You also have advantage on saving throws against being frightened until the start of your next turn. Invoking the Rune. When you blow the horn, you can also invoke the rune, imbuing the horn's deep call with protective magic that affects creatures of your choice within 30 feet of yourself. You and all affected creatures gain a +1 bonus to AC until the start of your next turn. Once the rune has been invoked, it can't be invoked again until the next dawn.\",\"properties\":[]},{\"id\":\"bigbys-wayfarer-s-boots\",\"name\":\"Wayfarer's Boots\",\"type\":\"gear\",\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"This pair of boots is made of durable cloth, with the journey rune stitched in golden thread above each heel. While you are wearing this item, your walking speed increases by 10 feet, and you have advantage on Wisdom (Survival) checks. Invoking the Runes. As a bonus action, you can invoke the boots' runes to cast the expeditious retreat spell with them. Once the runes have been invoked, they can't be invoked again until the next dawn.\",\"properties\":[]},{\"id\":\"bigbys-wyrmreaver-gauntlets\",\"name\":\"Wyrmreaver Gauntlets\",\"type\":\"gear\",\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"Originally crafted for ground-bound giant brawlers to fight against dragons and other enormous predators of the sky, these studded gauntlets are engraved with the dragon rune. While you are wearing these gauntlets, your unarmed strike deals an additional 1d6 force damage on a hit. Additionally, whenever you finish a long rest, choose one of the following damage types: acid, cold, fire, lightning, or poison. You have resistance to the chosen damage type until you finish another long rest. Invoking the Runes. As a bonus action, you can invoke the gauntlets' runes and summon two enormous spectral fists that envelop the gauntlets and mimic your hand motions. The fists can also launch themselves to strike distant opponents, returning immediately to your space after they hit or miss. The fists last for 1 minute or until you are incapacitated. While the spectral fists are active, unarmed strikes you make on your turn have a reach of 30 feet, and when you hit a creature with an opportunity attack made with your unarmed strike, the creature must succeed on a Strength saving throw (DC equals 8 + your proficiency bonus + your Strength modifier) or have the prone condition. Once the runes have been invoked, they can't be invoked again until the next dawn.\",\"properties\":[]}],\"feats\":[{\"id\":\"bigbys-ember-of-the-fire-giant\",\"name\":\"Ember of the Fire Giant\",\"description\":\"You've manifested the fiery combat emblematic of fire giants, granting you the following benefits: Born of Flame: You have resistance to fire damage. Searing Ignition: When you take the Attack action on your turn, you can replace a single attack with a magical burst of flame. Each creature of your choice in a 15-foot-radius sphere centered on you must make a Dexterity saving throw (DC equals 8 + your proficiency bonus + the modifier of the ability increased by this feat). On a failed save, a creature takes fire damage equal to 1d8 + your proficiency bonus, and it has the blinded condition until the start of your next turn. On a successful save, the creature takes half as much damage only. You can use your Searing Ignition a number of times equal to your proficiency bonus (but no more than once per turn), and you regain all expended uses when you finish a long rest.\",\"prerequisites\":{\"level\":4,\"text\":\"Level 4\"},\"abilityScoreIncreases\":[{\"ability\":\"choose\",\"amount\":1,\"chooseCount\":1,\"chooseFrom\":[\"strength\",\"constitution\",\"wisdom\"]}],\"features\":[],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-fury-of-the-frost-giant\",\"name\":\"Fury of the Frost Giant\",\"description\":\"You've manifested the icy might emblematic of frost giants, granting you the following benefits: Born of Ice: You have resistance to cold damage. Frigid Retaliation: Immediately after a creature you can see within 30 feet of you hits you with an attack roll and deals damage, you can use your reaction to retaliate with a conjured blast of ice. The creature must make a Constitution saving throw (DC equals 8 + your proficiency bonus + the modifier of the ability increased by this feat). On a failed save, the creature takes cold damage equal to 1d8 + your proficiency bonus, and its speed is reduced to 0 until the end of its next turn. You can use this reaction a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.\",\"prerequisites\":{\"level\":4,\"text\":\"Level 4\"},\"abilityScoreIncreases\":[{\"ability\":\"choose\",\"amount\":1,\"chooseCount\":1,\"chooseFrom\":[\"strength\",\"constitution\",\"wisdom\"]}],\"features\":[],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-guile-of-the-cloud-giant\",\"name\":\"Guile of the Cloud Giant\",\"description\":\"You've manifested the confounding magic emblematic of cloud giants, granting you the following benefits: Cloudy Escape: When a creature you can see hits you with an attack roll, you can use your reaction to give yourself resistance to that attack's damage. You then teleport to an unoccupied space that you can see within 30 feet of yourself. You can use this reaction a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.\",\"prerequisites\":{\"level\":4,\"text\":\"Level 4\"},\"abilityScoreIncreases\":[{\"ability\":\"choose\",\"amount\":1,\"chooseCount\":1,\"chooseFrom\":[\"strength\",\"constitution\",\"charisma\"]}],\"features\":[],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-keenness-of-the-stone-giant\",\"name\":\"Keenness of the Stone Giant\",\"description\":\"You've manifested the physical talents emblematic of stone giants, granting you the following benefits: Cavernous Sight: You gain darkvision with a range of 60 feet. If you already have darkvision from another source, its range increases by 60 feet. Stone Throw: As a bonus action, you can take a rock and make a magical attack with it. The attack is a ranged spell attack with a range of 60 feet that uses the ability score you increased with this feat as the spellcasting ability. On a hit, the rock deals 1d10 force damage, and the target must succeed on a Strength saving throw (DC equals 8 + your proficiency bonus + the spellcasting ability modifier) or have the prone condition. You can use this bonus action a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.\",\"prerequisites\":{\"level\":4,\"text\":\"Level 4\"},\"abilityScoreIncreases\":[{\"ability\":\"choose\",\"amount\":1,\"chooseCount\":1,\"chooseFrom\":[\"strength\",\"constitution\",\"wisdom\"]}],\"features\":[],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-rune-shaper\",\"name\":\"Rune Shaper\",\"description\":\"You've studied the magic of Giant runes, granting you the following benefits: Comprehend Languages: You learn the comprehend languages spell. You can cast this spell without expending a spell slot, and you must finish a long rest before you can cast it in this way again. You can also cast this spell using any spell slots you have. Rune Magic: You know a number of runes equal to half your proficiency bonus (rounded down), chosen from the Rune Spells table. Whenever you finish a long rest, you can inscribe each rune you know onto one nonmagical weapon, armor, piece of clothing, or other object you touch. You temporarily learn the 1st-level spells that correspond to the runes you inscribed, as specified on the Rune Spells table, and you know those spells until you finish a long rest, when the runes fade. While you are wearing or carrying any rune-marked object, you can cast the spells associated with those runes using any spell slots you have. You can also invoke a rune inscribed on an object you are wearing or carrying and cast its associated spell without expending a spell slot or using material components. Once you cast the spell in this way, you can't do so again until you finish a long rest. Your spellcasting ability for this feat is Intelligence, Wisdom, or Charisma (choose when you select this feat). Each time you gain a level, you can replace one of the runes you know with another one from the Rune Spells table. Cloud — Fog cloud; Death — Inflict wounds; Dragon — Chromatic orb; Enemy — Disguise self; Fire — Burning hands; Friend — Speak with animals; Frost — Armor of Agathys; Hill — Goodberry; Journey — Longstrider; King — Command; Mountain — Entangle; Stone — Sanctuary; Storm — Thunderwave\",\"grantedSpells\":[\"Comprehend Languages\",\"Fog Cloud\",\"Inflict Wounds\",\"Chromatic Orb\",\"Disguise Self\",\"Burning Hands\",\"Speak With Animals\",\"Armor Of Agathys\",\"Goodberry\",\"Longstrider\",\"Command\",\"Entangle\",\"Sanctuary\",\"Thunderwave\"],\"features\":[],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-soul-of-the-storm-giant\",\"name\":\"Soul of the Storm Giant\",\"description\":\"You've manifested the tempest magic emblematic of storm giants, granting you the following benefits: Maelstrom Aura: As a bonus action, you surround yourself with an aura of magical wind and lightning that extends 10 feet from you in every direction but not through 3. The aura lasts until the start of your next turn or until you are incapacitated. While the aura is active, you have resistance to lightning and thunder damage. In addition, attack rolls against you have disadvantage, and whenever another creature starts its turn within the aura, you can force the creature to make a Strength saving throw (DC equals 8 + your proficiency bonus + the modifier of the ability increased by this feat). On a failed save, the creature's speed is halved until the start of its next turn. You can use this bonus action a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.\",\"prerequisites\":{\"level\":4,\"text\":\"Level 4\"},\"abilityScoreIncreases\":[{\"ability\":\"choose\",\"amount\":1,\"chooseCount\":1,\"chooseFrom\":[\"strength\",\"wisdom\",\"charisma\"]}],\"features\":[],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-strike-of-the-giants\",\"name\":\"Strike of the Giants\",\"description\":\"You have absorbed primeval magic that gives you an echo of the might of giants. When you take this feat, choose one of the benefits listed below. Once per turn, when you hit a target with a melee weapon attack or a ranged weapon attack using a thrown weapon, you can imbue the attack with an additional effect depending on the benefit you chose: Cloud Strike. The target takes an extra 1d4 thunder damage. If the target is a creature, it must succeed on a Wisdom saving throw, or you become invisible to it until the start of your next turn or until immediately after you make an attack roll or cast a spell. Fire Strike. The target takes an extra 1d10 fire damage. Frost Strike. The target takes an extra 1d6 cold damage. If the target is a creature, it must succeed on a Constitution saving throw, or its speed is reduced to 0 until the start of your next turn. Hill Strike. The target takes an extra 1d6 damage of the weapon's type. If the target is a creature, it must succeed on a Strength saving throw or have the prone condition. Stone Strike. The target takes an extra 1d6 force damage. If the target is a creature, it must succeed on a Strength saving throw or be pushed 10 feet from you in a straight line. Storm Strike. The target takes an extra 1d6 lightning damage. If the target is a creature, it must succeed on a Constitution saving throw, or it has disadvantage on attack rolls until the start of your next turn. The saving throw DC for these effects equals 8 + your proficiency bonus + your Strength or Constitution modifier. You can use this feat a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.\",\"features\":[{\"id\":\"bigbys-strike-of-the-giants-cloud-strike-0\",\"name\":\"Cloud Strike\",\"description\":\"The target takes an extra 1d4 thunder damage. If the target is a creature, it must succeed on a Wisdom saving throw, or you become invisible to it until the start of your next turn or until immediately after you make an attack roll or cast a spell.\",\"level\":1,\"source\":\"Bigby Presents: Glory of the Giants\"},{\"id\":\"bigbys-strike-of-the-giants-fire-strike-1\",\"name\":\"Fire Strike\",\"description\":\"The target takes an extra 1d10 fire damage.\",\"level\":1,\"source\":\"Bigby Presents: Glory of the Giants\"},{\"id\":\"bigbys-strike-of-the-giants-frost-strike-2\",\"name\":\"Frost Strike\",\"description\":\"The target takes an extra 1d6 cold damage. If the target is a creature, it must succeed on a Constitution saving throw, or its speed is reduced to 0 until the start of your next turn.\",\"level\":1,\"source\":\"Bigby Presents: Glory of the Giants\"},{\"id\":\"bigbys-strike-of-the-giants-hill-strike-3\",\"name\":\"Hill Strike\",\"description\":\"The target takes an extra 1d6 damage of the weapon's type. If the target is a creature, it must succeed on a Strength saving throw or have the prone condition.\",\"level\":1,\"source\":\"Bigby Presents: Glory of the Giants\"},{\"id\":\"bigbys-strike-of-the-giants-stone-strike-4\",\"name\":\"Stone Strike\",\"description\":\"The target takes an extra 1d6 force damage. If the target is a creature, it must succeed on a Strength saving throw or be pushed 10 feet from you in a straight line.\",\"level\":1,\"source\":\"Bigby Presents: Glory of the Giants\"},{\"id\":\"bigbys-strike-of-the-giants-storm-strike-5\",\"name\":\"Storm Strike\",\"description\":\"The target takes an extra 1d6 lightning damage. If the target is a creature, it must succeed on a Constitution saving throw, or it has disadvantage on attack rolls until the start of your next turn. The saving throw DC for these effects equals 8 + your proficiency bonus + your Strength or Constitution modifier. You can use this feat a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.\",\"level\":1,\"source\":\"Bigby Presents: Glory of the Giants\"}],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-strike-of-the-giants-cloud\",\"name\":\"Strike of the Giants; Cloud\",\"description\":\"You have absorbed primeval magic that gives you an echo of the might of giants. Once per turn, when you hit a target with a melee weapon attack or a ranged weapon attack using a thrown weapon, you can imbue the attack with an additional effect: Cloud Strike. The target takes an extra 1d4 thunder damage. If the target is a creature, it must succeed on a Wisdom saving throw, or you become invisible to it until the start of your next turn or until immediately after you make an attack roll or cast a spell.\",\"features\":[{\"id\":\"bigbys-strike-of-the-giants-cloud-cloud-strike-0\",\"name\":\"Cloud Strike\",\"description\":\"The target takes an extra 1d4 thunder damage. If the target is a creature, it must succeed on a Wisdom saving throw, or you become invisible to it until the start of your next turn or until immediately after you make an attack roll or cast a spell.\",\"level\":1,\"source\":\"Bigby Presents: Glory of the Giants\"}],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-strike-of-the-giants-fire\",\"name\":\"Strike of the Giants; Fire\",\"description\":\"You have absorbed primeval magic that gives you an echo of the might of giants. Once per turn, when you hit a target with a melee weapon attack or a ranged weapon attack using a thrown weapon, you can imbue the attack with an additional effect: Fire Strike. The target takes an extra 1d10 fire damage.\",\"features\":[{\"id\":\"bigbys-strike-of-the-giants-fire-fire-strike-0\",\"name\":\"Fire Strike\",\"description\":\"The target takes an extra 1d10 fire damage.\",\"level\":1,\"source\":\"Bigby Presents: Glory of the Giants\"}],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-strike-of-the-giants-frost\",\"name\":\"Strike of the Giants; Frost\",\"description\":\"You have absorbed primeval magic that gives you an echo of the might of giants. Once per turn, when you hit a target with a melee weapon attack or a ranged weapon attack using a thrown weapon, you can imbue the attack with an additional effect: Frost Strike. The target takes an extra 1d6 cold damage. If the target is a creature, it must succeed on a Constitution saving throw, or its speed is reduced to 0 until the start of your next turn.\",\"features\":[{\"id\":\"bigbys-strike-of-the-giants-frost-frost-strike-0\",\"name\":\"Frost Strike\",\"description\":\"The target takes an extra 1d6 cold damage. If the target is a creature, it must succeed on a Constitution saving throw, or its speed is reduced to 0 until the start of your next turn.\",\"level\":1,\"source\":\"Bigby Presents: Glory of the Giants\"}],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-strike-of-the-giants-hill\",\"name\":\"Strike of the Giants; Hill\",\"description\":\"You have absorbed primeval magic that gives you an echo of the might of giants. Once per turn, when you hit a target with a melee weapon attack or a ranged weapon attack using a thrown weapon, you can imbue the attack with an additional effect: Hill Strike. The target takes an extra 1d6 damage of the weapon's type. If the target is a creature, it must succeed on a Strength saving throw or have the prone condition.\",\"features\":[{\"id\":\"bigbys-strike-of-the-giants-hill-hill-strike-0\",\"name\":\"Hill Strike\",\"description\":\"The target takes an extra 1d6 damage of the weapon's type. If the target is a creature, it must succeed on a Strength saving throw or have the prone condition.\",\"level\":1,\"source\":\"Bigby Presents: Glory of the Giants\"}],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-strike-of-the-giants-stone\",\"name\":\"Strike of the Giants; Stone\",\"description\":\"You have absorbed primeval magic that gives you an echo of the might of giants. Once per turn, when you hit a target with a melee weapon attack or a ranged weapon attack using a thrown weapon, you can imbue the attack with an additional effect: Stone Strike. The target takes an extra 1d6 force damage. If the target is a creature, it must succeed on a Strength saving throw or be pushed 10 feet from you in a straight line.\",\"features\":[{\"id\":\"bigbys-strike-of-the-giants-stone-stone-strike-0\",\"name\":\"Stone Strike\",\"description\":\"The target takes an extra 1d6 force damage. If the target is a creature, it must succeed on a Strength saving throw or be pushed 10 feet from you in a straight line.\",\"level\":1,\"source\":\"Bigby Presents: Glory of the Giants\"}],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-strike-of-the-giants-storm\",\"name\":\"Strike of the Giants; Storm\",\"description\":\"You have absorbed primeval magic that gives you an echo of the might of giants. Once per turn, when you hit a target with a melee weapon attack or a ranged weapon attack using a thrown weapon, you can imbue the attack with an additional effect: Storm Strike. The target takes an extra 1d6 lightning damage. If the target is a creature, it must succeed on a Constitution saving throw, or it has disadvantage on attack rolls until the start of your next turn. The saving throw DC for these effects equals 8 + your proficiency bonus + your Strength or Constitution modifier. You can use this feat a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.\",\"features\":[{\"id\":\"bigbys-strike-of-the-giants-storm-storm-strike-0\",\"name\":\"Storm Strike\",\"description\":\"The target takes an extra 1d6 lightning damage. If the target is a creature, it must succeed on a Constitution saving throw, or it has disadvantage on attack rolls until the start of your next turn. The saving throw DC for these effects equals 8 + your proficiency bonus + your Strength or Constitution modifier. You can use this feat a number of times equal to your proficiency bonus, and you regain all expended uses when you finish a long rest.\",\"level\":1,\"source\":\"Bigby Presents: Glory of the Giants\"}],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-vigor-of-the-hill-giant\",\"name\":\"Vigor of the Hill Giant\",\"description\":\"You've manifested the resilience emblematic of hill giants, granting you the following benefits: Bulwark: When you are subjected to an effect that would move you at least 5 feet or give you the prone condition, you can use your reaction to steady yourself. You aren't moved and don't have the prone condition. Iron Stomach: Whenever you eat food as part of a short rest and spend one or more Hit Dice to regain hit points, you regain additional hit points equal to your Constitution modifier + your proficiency bonus.\",\"prerequisites\":{\"level\":4,\"text\":\"Level 4\"},\"abilityScoreIncreases\":[{\"ability\":\"choose\",\"amount\":1,\"chooseCount\":1,\"chooseFrom\":[\"strength\",\"constitution\",\"wisdom\"]}],\"features\":[],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"}],\"monsters\":[{\"id\":\"bigbys-aerosaur\",\"name\":\"Aerosaur\",\"description\":\"Aerosaur from Bigby Presents: Glory of the Giants.\",\"size\":\"Gargantuan\",\"type\":\"monstrosity\",\"alignment\":\"U\",\"ac\":14,\"hp\":{\"average\":155,\"formula\":\"10d20 + 50\"},\"speed\":\"20 ft., fly 120 ft.\",\"abilityScores\":{\"strength\":26,\"dexterity\":10,\"constitution\":21,\"intelligence\":3,\"wisdom\":10,\"charisma\":5},\"challengeRating\":\"10\",\"skills\":[\"Perception +4\"],\"senses\":[\"passive Perception 14\"],\"traits\":[{\"id\":\"bigbys-aerosaur-trait-0\",\"name\":\"Magic Resistance\",\"description\":\"The aerosaur has advantage on saving throws against spells and other magical effects.\"}],\"actions\":[{\"id\":\"bigbys-aerosaur-action-0\",\"name\":\"Multiattack\",\"description\":\"The aerosaur makes one Bite attack and one Talons attack.\"},{\"id\":\"bigbys-aerosaur-action-1\",\"name\":\"Bite\",\"description\":\"mw 12 to hit, reach 10 ft., one target. {@h}27 (3d12 + 8) piercing damage. If the target is a Huge or smaller creature, it has the grappled condition (escape 18). Until this grapple ends, the target has the restrained condition, and the aerosaur can't Bite another target.\"},{\"id\":\"bigbys-aerosaur-action-2\",\"name\":\"Talons\",\"description\":\"mw 12 to hit, reach 10 ft., one target. {@h}24 (3d10 + 8) slashing damage.\"},{\"id\":\"bigbys-aerosaur-action-3\",\"name\":\"Wing Gusts 5\",\"description\":\"The aerosaur beats its wings, creating bursts of thunderous force. Each creature within 10 feet of the aerosaur must make a 20 Strength saving throw. On a failed save, a creature takes 38 (7d10) thunder damage, is pushed up to 30 feet horizontally from the aerosaur, and has the prone condition. On a successful save, a creature takes half as much damage and is pushed up to 15 feet horizontally from the aerosaur.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-altisaur\",\"name\":\"Altisaur\",\"description\":\"Altisaur from Bigby Presents: Glory of the Giants.\",\"size\":\"Gargantuan\",\"type\":\"monstrosity\",\"alignment\":\"U\",\"ac\":15,\"hp\":{\"average\":198,\"formula\":\"12d20 + 72\"},\"speed\":\"40 ft.\",\"abilityScores\":{\"strength\":28,\"dexterity\":6,\"constitution\":23,\"intelligence\":3,\"wisdom\":12,\"charisma\":7},\"challengeRating\":\"13\",\"skills\":[\"Perception +11\"],\"senses\":[\"passive Perception 21\"],\"traits\":[{\"id\":\"bigbys-altisaur-trait-0\",\"name\":\"Magic Resistance\",\"description\":\"The altisaur has advantage on saving throws against spells and other magical effects.\"}],\"actions\":[{\"id\":\"bigbys-altisaur-action-0\",\"name\":\"Multiattack\",\"description\":\"The altisaur makes one Stomp attack and one Tail attack. The altisaur can't make both attacks against the same target.\"},{\"id\":\"bigbys-altisaur-action-1\",\"name\":\"Stomp\",\"description\":\"mw 14 to hit, reach 10 ft., one target. {@h}33 (7d6 + 9) bludgeoning damage. If the target is a Huge or smaller creature, it must succeed on a 22 Strength saving throw or have the prone condition.\"},{\"id\":\"bigbys-altisaur-action-2\",\"name\":\"Tail\",\"description\":\"mw 14 to hit, reach 20 ft., one target. {@h}45 (8d8 + 9) bludgeoning damage, and the target is pushed up to 20 feet horizontally from the altisaur.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-bag-jelly\",\"name\":\"Bag Jelly\",\"description\":\"Bag Jelly from Bigby Presents: Glory of the Giants.\",\"size\":\"Medium\",\"type\":\"ooze\",\"alignment\":\"U\",\"ac\":8,\"hp\":{\"average\":42,\"formula\":\"5d8 + 20\"},\"speed\":\"10 ft., climb 10 ft.\",\"abilityScores\":{\"strength\":13,\"dexterity\":6,\"constitution\":19,\"intelligence\":2,\"wisdom\":7,\"charisma\":2},\"challengeRating\":\"1\",\"damageResistances\":[\"acid\",\"bludgeoning\"],\"conditionImmunities\":[\"exhaustion\"],\"senses\":[\"blindsight 60 ft. (can't see beyond this radius), passive Perception 8\"],\"traits\":[{\"id\":\"bigbys-bag-jelly-trait-0\",\"name\":\"Amorphous\",\"description\":\"The bag jelly can move through a space as narrow as 1 inch without squeezing.\"}],\"actions\":[{\"id\":\"bigbys-bag-jelly-action-0\",\"name\":\"Multiattack\",\"description\":\"The bag jelly makes two Pseudopod attacks.\"},{\"id\":\"bigbys-bag-jelly-action-1\",\"name\":\"Pseudopod\",\"description\":\"mw 3 to hit, reach 5 ft., one target. {@h}8 (2d6 + 1) acid damage. If the target is a Medium or smaller creature, it has the grappled condition (escape 11). Ability checks made to escape this grapple have disadvantage.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-barrowghast\",\"name\":\"Barrowghast\",\"description\":\"Barrowghast from Bigby Presents: Glory of the Giants.\",\"size\":\"Huge\",\"type\":\"undead\",\"alignment\":\"C E\",\"ac\":12,\"hp\":{\"average\":138,\"formula\":\"12d12 + 60\"},\"speed\":\"40 ft.\",\"abilityScores\":{\"strength\":21,\"dexterity\":8,\"constitution\":20,\"intelligence\":5,\"wisdom\":9,\"charisma\":6},\"challengeRating\":\"7\",\"damageResistances\":[\"necrotic\",\"poison\"],\"conditionImmunities\":[\"exhaustion\",\"poisoned\"],\"senses\":[\"darkvision 60 ft., passive Perception 9\"],\"traits\":[{\"id\":\"bigbys-barrowghast-trait-0\",\"name\":\"Stench\",\"description\":\"Any creature that starts its turn within 10 feet of the barrowghast must make a 16 Constitution saving throw. On a failed save, the creature has the poisoned condition for 1 minute. While poisoned this way, the creature can't regain hit points. On a successful save, the creature is immune to the Stench of all barrowghasts for 24 hours.\"}],\"actions\":[{\"id\":\"bigbys-barrowghast-action-0\",\"name\":\"Multiattack\",\"description\":\"The barrowghast makes two Slam attacks. It can replace one Slam attack with a Life Drain attack.\"},{\"id\":\"bigbys-barrowghast-action-1\",\"name\":\"Slam\",\"description\":\"mw 8 to hit, reach 10 ft., one target. {@h}18 (2d12 + 5) bludgeoning damage.\"},{\"id\":\"bigbys-barrowghast-action-2\",\"name\":\"Life Drain\",\"description\":\"mw 8 to hit, reach 10 ft., one creature. {@h}9 (1d8 + 5) necrotic damage, and the target must succeed on a 16 Constitution saving throw or its hit point maximum is reduced by an amount equal to the damage taken. This reduction lasts until the target finishes a long rest. The target dies if this effect reduces its hit point maximum to 0. A Humanoid slain by this attack immediately rises as a zombie (see the Monster Manual). The zombie acts as an ally of the barrowghast but isn't under its control.\"}],\"bonusActions\":[],\"reactions\":[{\"id\":\"bigbys-barrowghast-reaction-0\",\"name\":\"Noxious Wound\",\"description\":\"Immediately after the barrowghast takes piercing or slashing damage, poisonous ichor sprays from the wound. Each creature within 5 feet of the barrowghast must make a 16 Dexterity saving throw, taking 10 (3d6) poison damage on a failed save, or half as much damage on a successful one.\"}],\"legendaryActions\":[],\"languages\":[\"Giant\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-cairnwight\",\"name\":\"Cairnwight\",\"description\":\"Cairnwight from Bigby Presents: Glory of the Giants.\",\"size\":\"Huge\",\"type\":\"undead\",\"alignment\":\"N\",\"ac\":19,\"hp\":{\"average\":138,\"formula\":\"12d12 + 60\"},\"speed\":\"40 ft.\",\"abilityScores\":{\"strength\":23,\"dexterity\":10,\"constitution\":21,\"intelligence\":10,\"wisdom\":12,\"charisma\":9},\"challengeRating\":\"9\",\"savingThrows\":[\"Con +9\",\"Wis +5\"],\"skills\":[\"Athletics +10\",\"Perception +5\",\"Stealth +8\"],\"conditionImmunities\":[\"charmed\",\"exhaustion\",\"frightened\",\"petrified\"],\"senses\":[\"darkvision 60 ft., passive Perception 15\"],\"traits\":[],\"actions\":[{\"id\":\"bigbys-cairnwight-action-0\",\"name\":\"Multiattack\",\"description\":\"The cairnwight makes two Slam attacks or two Rock attacks, and it uses its Petrifying Touch if available.\"},{\"id\":\"bigbys-cairnwight-action-1\",\"name\":\"Slam\",\"description\":\"mw 10 to hit, reach 10 ft., one target. {@h}22 (3d10 + 6) bludgeoning damage.\"},{\"id\":\"bigbys-cairnwight-action-2\",\"name\":\"Rock\",\"description\":\"rw 10 to hit, range 60/240 ft., one target. {@h}19 (3d8 + 6) bludgeoning damage, and the target must succeed on a 17 Strength saving throw or have the prone condition.\"},{\"id\":\"bigbys-cairnwight-action-3\",\"name\":\"Petrifying Touch 5\",\"description\":\"The cairnwight touches one creature it can see within 10 feet of itself. The target must succeed on a 17 Constitution saving throw or take 26 (4d12) force damage and have the restrained condition as it begins to turn to stone. The affected target must repeat the saving throw at the end of its next turn. On a successful save, the effect ends on the target. On a failed save, the target has the petrified condition instead of the restrained condition.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Giant\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-ceratops\",\"name\":\"Ceratops\",\"description\":\"Ceratops from Bigby Presents: Glory of the Giants.\",\"size\":\"Gargantuan\",\"type\":\"monstrosity\",\"alignment\":\"U\",\"ac\":16,\"hp\":{\"average\":139,\"formula\":\"9d20 + 45\"},\"speed\":\"50 ft.\",\"abilityScores\":{\"strength\":24,\"dexterity\":8,\"constitution\":21,\"intelligence\":4,\"wisdom\":10,\"charisma\":7},\"challengeRating\":\"9\",\"senses\":[\"passive Perception 10\"],\"traits\":[{\"id\":\"bigbys-ceratops-trait-0\",\"name\":\"Magic Resistance\",\"description\":\"The ceratops has advantage on saving throws against spells and other magical effects.\"}],\"actions\":[{\"id\":\"bigbys-ceratops-action-0\",\"name\":\"Multiattack\",\"description\":\"The ceratops makes one Gore attack and one Stomp attack.\"},{\"id\":\"bigbys-ceratops-action-1\",\"name\":\"Gore\",\"description\":\"mw 11 to hit, reach 10 ft., one target. {@h}29 (4d10 + 7) piercing damage. If the ceratops moved at least 20 feet in a straight line toward the target immediately before the hit, the target takes an extra 11 (2d10) piercing damage; if the target is a creature, it also must succeed on a 19 Strength saving throw or be pushed up to 20 feet from the ceratops and have the prone condition.\"},{\"id\":\"bigbys-ceratops-action-2\",\"name\":\"Stomp\",\"description\":\"mw 11 to hit, reach 5 ft., one target. {@h}29 (4d10 + 7) bludgeoning damage.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-cinder-hulk\",\"name\":\"Cinder Hulk\",\"description\":\"Cinder Hulk from Bigby Presents: Glory of the Giants.\",\"size\":\"Large\",\"type\":\"elemental\",\"alignment\":\"C E\",\"ac\":16,\"hp\":{\"average\":84,\"formula\":\"8d10 + 40\"},\"speed\":\"40 ft.\",\"abilityScores\":{\"strength\":20,\"dexterity\":12,\"constitution\":20,\"intelligence\":9,\"wisdom\":14,\"charisma\":10},\"challengeRating\":\"7\",\"savingThrows\":[\"Dex +4\",\"Con +8\",\"Wis +5\"],\"skills\":[\"Perception +5\"],\"damageImmunities\":[\"fire\",\"poison\"],\"conditionImmunities\":[\"exhaustion\",\"poisoned\"],\"senses\":[\"passive Perception 15\"],\"traits\":[{\"id\":\"bigbys-cinder-hulk-trait-0\",\"name\":\"Death Burst\",\"description\":\"When the cinder hulk dies, it leaves behind a cloud of cinders and smoke that fills a 10-foot-radius sphere centered on its space. The sphere is 2. Any creature that moves into the area for the first time on a turn or starts its turn there must succeed on a 16 Constitution saving throw or take 10 (3d6) fire damage. The cloud lasts for 1 minute or until it is dispersed by strong wind.\"}],\"actions\":[{\"id\":\"bigbys-cinder-hulk-action-0\",\"name\":\"Multiattack\",\"description\":\"The cinder hulk makes two Slam attacks.\"},{\"id\":\"bigbys-cinder-hulk-action-1\",\"name\":\"Slam\",\"description\":\"mw 8 to hit, reach 5 ft., one target. {@h}16 (2d10 + 5) bludgeoning damage plus 10 (3d6) fire damage.\"},{\"id\":\"bigbys-cinder-hulk-action-2\",\"name\":\"Wave of Cinders 5\",\"description\":\"The cinder hulk emits a wave of smoldering ash from its face, hands, or chest in a 30-foot cone. Each creature in that area must make a 16 Dexterity saving throw. On a failed save, a creature takes 31 (7d8) fire damage and has the blinded condition until the end of its next turn. On a successful save, a creature takes half as much damage only.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Giant\",\"Ignan\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-cloud-giant-destiny-gambler\",\"name\":\"Cloud Giant Destiny Gambler\",\"description\":\"Cloud Giant Destiny Gambler from Bigby Presents: Glory of the Giants.\",\"size\":\"Huge\",\"type\":\"giant\",\"alignment\":\"A\",\"ac\":15,\"hp\":{\"average\":337,\"formula\":\"27d12 + 162\"},\"speed\":\"40 ft., fly 40 ft.\",\"abilityScores\":{\"strength\":27,\"dexterity\":12,\"constitution\":22,\"intelligence\":19,\"wisdom\":16,\"charisma\":22},\"challengeRating\":\"19\",\"savingThrows\":[\"Con +12\",\"Int +10\",\"Wis +9\",\"Cha +12\"],\"skills\":[\"Deception +18\",\"Insight +9\",\"Perception +9\"],\"damageImmunities\":[\"thunder\"],\"senses\":[\"truesight 30 ft. (requires cloud rune), passive Perception 19\"],\"traits\":[{\"id\":\"bigbys-cloud-giant-destiny-gambler-trait-0\",\"name\":\"Cloud Rune\",\"description\":\"The giant has a cloud rune inscribed on a mask in its possession. While holding or wearing the mask bearing the rune, the giant has truesight within a range of 30 feet and can use its Thunderous Clap action and Negate Spell reaction. The mask bearing the cloud rune has AC 15; 45 hit points; and immunity to necrotic, poison, and psychic damage. The mask regains all its hit points at the end of every turn, but it turns to dust if reduced to 0 hit points or when the giant dies. If the rune is destroyed, the giant can inscribe a cloud rune on a mask in its possession when it finishes a short or long rest.\"}],\"actions\":[{\"id\":\"bigbys-cloud-giant-destiny-gambler-action-0\",\"name\":\"Multiattack\",\"description\":\"The giant makes three Flying Staff attacks.\"},{\"id\":\"bigbys-cloud-giant-destiny-gambler-action-1\",\"name\":\"Flying Staff\",\"description\":\"mw,rw 14 to hit, reach 10 ft. or range 30/90 ft., one target. {@h}18 (3d6 + 8) bludgeoning damage plus 16 (3d10) thunder damage. {@hom}The staff magically returns to the giant's hand immediately after a ranged attack.\"},{\"id\":\"bigbys-cloud-giant-destiny-gambler-action-2\",\"name\":\"Thunderous Clap (Requires Cloud Rune)\",\"description\":\"The giant magically summons a thundercloud that fills a 30-foot-radius sphere centered on a point the giant can see within 60 feet of itself. The cloud spreads around corners. Each creature in that area must make a 20 Constitution saving throw as the cloud emits a thunderous boom. On a failed save, a creature takes 52 (8d12) thunder damage and has the prone condition. On a successful save, a creature takes half as much damage only. The thunderclap is audible within 300 feet of the cloud's center point. The cloud's area is 2. The cloud lingers until the start of the giant's next turn or until a strong wind disperses it.\"}],\"bonusActions\":[],\"reactions\":[{\"id\":\"bigbys-cloud-giant-destiny-gambler-reaction-0\",\"name\":\"Negate Spell (Requires Cloud Rune)\",\"description\":\"When the giant sees a creature within 60 feet of itself casting a spell, the giant tries to interrupt it. If the creature is casting a spell using a spell slot of 3rd level or lower, the spell fails and has no effect. If the creature is casting a spell of 4th level or higher, it must succeed on a 18 Intelligence saving throw, or the spell fails and has no effect.\"}],\"legendaryActions\":[],\"languages\":[\"Common\",\"Giant\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-cloud-giant-of-evil-air\",\"name\":\"Cloud Giant of Evil Air\",\"description\":\"Cloud Giant of Evil Air from Bigby Presents: Glory of the Giants.\",\"size\":\"Huge\",\"type\":\"giant\",\"alignment\":\"N E\",\"ac\":14,\"hp\":{\"average\":200,\"formula\":\"16d12 + 96\"},\"speed\":\"40 ft., fly 40 ft.\",\"abilityScores\":{\"strength\":27,\"dexterity\":10,\"constitution\":22,\"intelligence\":12,\"wisdom\":16,\"charisma\":19},\"challengeRating\":\"12\",\"savingThrows\":[\"Con +10\",\"Wis +7\",\"Cha +8\"],\"skills\":[\"Insight +7\",\"Perception +7\",\"Stealth +4\"],\"senses\":[\"passive Perception 17\"],\"traits\":[{\"id\":\"bigbys-cloud-giant-of-evil-air-trait-0\",\"name\":\"Flyby\",\"description\":\"The giant doesn't provoke an opportunity attack when it flies out of an enemy's reach.\"}],\"actions\":[{\"id\":\"bigbys-cloud-giant-of-evil-air-action-0\",\"name\":\"Multiattack\",\"description\":\"The giant makes two Scimitar attacks and one Storm Boomerang attack.\"},{\"id\":\"bigbys-cloud-giant-of-evil-air-action-1\",\"name\":\"Scimitar\",\"description\":\"mw 12 to hit, reach 10 ft., one target. {@h}18 (3d6 + 8) slashing damage.\"},{\"id\":\"bigbys-cloud-giant-of-evil-air-action-2\",\"name\":\"Storm Boomerang\",\"description\":\"rw 12 to hit, range 60/240 ft., one target. {@h}15 (3d4 + 8) bludgeoning damage plus 7 (2d6) thunder damage, and the target must succeed on a 16 Constitution saving throw or have the stunned condition until the end of its next turn. {@hom}The boomerang magically returns to the giant's hand immediately after the attack.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Auran\",\"Common\",\"Giant\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-cradle-of-the-cloud-scion\",\"name\":\"Cradle of the Cloud Scion\",\"description\":\"Cradle of the Cloud Scion from Bigby Presents: Glory of the Giants.\",\"size\":\"Gargantuan\",\"type\":\"elemental\",\"alignment\":\"C N\",\"ac\":19,\"hp\":{\"average\":624,\"formula\":\"32d20 + 288\"},\"speed\":\"0 ft., fly 90 ft.\",\"abilityScores\":{\"strength\":29,\"dexterity\":21,\"constitution\":28,\"intelligence\":14,\"wisdom\":22,\"charisma\":19},\"challengeRating\":\"26\",\"savingThrows\":[\"Int +10\",\"Cha +12\"],\"damageResistances\":[\"cold\",\"fire\",\"lightning\",\"bludgeoning\",\"piercing\",\"slashing\",\"from nonmagical attacks\"],\"damageImmunities\":[\"poison\",\"thunder\"],\"conditionImmunities\":[\"exhaustion\",\"grappled\",\"paralyzed\",\"petrified\",\"poisoned\",\"prone\",\"restrained\",\"stunned\"],\"senses\":[\"passive Perception 16\"],\"traits\":[{\"id\":\"bigbys-cradle-of-the-cloud-scion-trait-0\",\"name\":\"Awakening of the Scion\",\"description\":\"The cradle is a container for the scion of Memnor. When the cradle drops to 0 hit points, its body dissipates into cloud wisps. The scion instantly appears in the space the cradle occupied and uses the cradle's initiative count.\"},{\"id\":\"bigbys-cradle-of-the-cloud-scion-trait-1\",\"name\":\"Flyby\",\"description\":\"The cradle doesn't provoke opportunity attacks when it flies out of an enemy's reach.\"},{\"id\":\"bigbys-cradle-of-the-cloud-scion-trait-2\",\"name\":\"Legendary Resistance (5/Day)\",\"description\":\"If the cradle fails a saving throw, it can choose to succeed instead.\"},{\"id\":\"bigbys-cradle-of-the-cloud-scion-trait-3\",\"name\":\"Magic Resistance\",\"description\":\"The cradle has advantage on saving throws against spells and other magical effects.\"},{\"id\":\"bigbys-cradle-of-the-cloud-scion-trait-4\",\"name\":\"Siege Monster\",\"description\":\"The cradle deals double damage to objects and structures.\"}],\"actions\":[{\"id\":\"bigbys-cradle-of-the-cloud-scion-action-0\",\"name\":\"Multiattack\",\"description\":\"The cradle makes three Slam or Wind Javelin attacks in any combination.\"},{\"id\":\"bigbys-cradle-of-the-cloud-scion-action-1\",\"name\":\"Slam\",\"description\":\"mw 17 to hit, reach 20 ft., one target. {@h}31 (4d10 + 9) bludgeoning damage plus 19 (3d12) thunder damage.\"},{\"id\":\"bigbys-cradle-of-the-cloud-scion-action-2\",\"name\":\"Wind Javelin\",\"description\":\"rw 17 to hit, range 120 ft., one target. {@h}27 (4d8 + 9) bludgeoning damage plus 10 (3d6) thunder damage, and the target must succeed on a 25 Strength saving throw or have the prone condition.\"},{\"id\":\"bigbys-cradle-of-the-cloud-scion-action-3\",\"name\":\"Vortex 5\",\"description\":\"The cradle conjures a vortex of wind at a point it can see within 90 feet of itself. The wind vortex is a 30-foot-radius, 100-foot-high cylinder centered on that point. Each creature other than the cradle in that area must make a 25 Dexterity saving throw. On a failed save, a creature takes 71 (11d12) bludgeoning damage and has the restrained condition within the vortex. On a successful save, a creature takes half as much damage and is pushed to the nearest unoccupied space outside the cylinder. The vortex lasts until the start of the cradle's next turn. A creature with the restrained condition falls prone when the vortex ends. A creature with the restrained condition can use its action to try to escape the vortex. The creature makes a 19 Strength (Athletics) or Dexterity (Acrobatics) check. On a successful check, the creature escapes and moves 3d6 × 10 feet away from the vortex in a random direction.\"}],\"bonusActions\":[],\"reactions\":[{\"id\":\"bigbys-cradle-of-the-cloud-scion-reaction-0\",\"name\":\"Thunderclap\",\"description\":\"Immediately after taking damage, the cradle unleashes a thunderclap in a 30-foot-radius sphere centered on itself. All other creatures in that area must succeed on a 25 Constitution saving throw or take 18 (4d8) thunder damage and have the deafened condition for 1 minute.\"}],\"legendaryActions\":[],\"languages\":[\"Giant\",\"Primordial\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-cradle-of-the-fire-scion\",\"name\":\"Cradle of the Fire Scion\",\"description\":\"Cradle of the Fire Scion from Bigby Presents: Glory of the Giants.\",\"size\":\"Gargantuan\",\"type\":\"elemental\",\"alignment\":\"L E\",\"ac\":20,\"hp\":{\"average\":555,\"formula\":\"30d20 + 240\"},\"speed\":\"40 ft.\",\"abilityScores\":{\"strength\":28,\"dexterity\":12,\"constitution\":27,\"intelligence\":12,\"wisdom\":20,\"charisma\":17},\"challengeRating\":\"25\",\"damageResistances\":[\"cold\",\"lightning\",\"bludgeoning\",\"piercing\",\"slashing\",\"from nonmagical attacks\"],\"damageImmunities\":[\"fire\",\"poison\"],\"conditionImmunities\":[\"exhaustion\",\"petrified\",\"poisoned\"],\"senses\":[\"darkvision 120 ft., passive Perception 15\"],\"traits\":[{\"id\":\"bigbys-cradle-of-the-fire-scion-trait-0\",\"name\":\"Awakening of the Scion\",\"description\":\"The cradle is a container for the scion of Surtur. When the cradle drops to 0 hit points, its body hardens and crumbles to ash. The scion instantly appears in the space the cradle occupied and uses the cradle's initiative count.\"},{\"id\":\"bigbys-cradle-of-the-fire-scion-trait-1\",\"name\":\"Legendary Resistance (5/Day)\",\"description\":\"If the cradle fails a saving throw, it can choose to succeed instead.\"},{\"id\":\"bigbys-cradle-of-the-fire-scion-trait-2\",\"name\":\"Magic Resistance\",\"description\":\"The cradle has advantage on saving throws against spells and other magical effects.\"},{\"id\":\"bigbys-cradle-of-the-fire-scion-trait-3\",\"name\":\"Siege Monster\",\"description\":\"The cradle deals double damage to objects and structures.\"}],\"actions\":[{\"id\":\"bigbys-cradle-of-the-fire-scion-action-0\",\"name\":\"Multiattack\",\"description\":\"The cradle makes three Slam or Hurl Lava attacks in any combination.\"},{\"id\":\"bigbys-cradle-of-the-fire-scion-action-1\",\"name\":\"Slam\",\"description\":\"mw 17 to hit, reach 20 ft., one target. {@h}31 (4d10 + 9) bludgeoning damage plus 14 (4d6) fire damage.\"},{\"id\":\"bigbys-cradle-of-the-fire-scion-action-2\",\"name\":\"Hurl Lava\",\"description\":\"rw 17 to hit, range 120 ft., one target. {@h}27 (4d8 + 9) fire damage. If the target is a creature or a flammable object, it ignites. Until a creature within 5 feet of the fire takes an action to douse the fire, the target takes 10 (3d6) fire damage at the start of each of its turns.\"},{\"id\":\"bigbys-cradle-of-the-fire-scion-action-3\",\"name\":\"Erupting Breath 5\",\"description\":\"The cradle exhales flames and volcanic gases in a 90-foot cone. Each creature in that area must make a 24 Dexterity saving throw. On a failed save, a creature takes 55 (10d10) fire damage and has the poisoned condition for 1 minute. On a successful save, a creature takes half as much damage only. A creature poisoned in this way can make a 24 Constitution saving throw at the end of each of its turns, ending the effect on itself on a success.\"}],\"bonusActions\":[{\"id\":\"bigbys-cradle-of-the-fire-scion-bonus-0\",\"name\":\"Lava Geyser\",\"description\":\"The cradle causes lava to erupt from a point on the ground it can see within 120 feet of itself. Each creature in a 20-foot-radius, 50-foot-high cylinder centered on that point must succeed on a 21 Dexterity saving throw or take 14 (4d6) fire damage.\"}],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Giant\",\"Primordial\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-cradle-of-the-frost-scion\",\"name\":\"Cradle of the Frost Scion\",\"description\":\"Cradle of the Frost Scion from Bigby Presents: Glory of the Giants.\",\"size\":\"Gargantuan\",\"type\":\"elemental\",\"alignment\":\"N E\",\"ac\":20,\"hp\":{\"average\":499,\"formula\":\"27d20 + 216\"},\"speed\":\"40 ft., swim 40 ft.\",\"abilityScores\":{\"strength\":27,\"dexterity\":14,\"constitution\":26,\"intelligence\":11,\"wisdom\":19,\"charisma\":16},\"challengeRating\":\"24\",\"savingThrows\":[\"Wis +11\",\"Cha +10\"],\"damageResistances\":[\"fire\",\"lightning\",\"bludgeoning\",\"piercing\",\"slashing\",\"from nonmagical attacks\"],\"damageImmunities\":[\"cold\",\"poison\"],\"conditionImmunities\":[\"charmed\",\"exhaustion\",\"frightened\",\"paralyzed\",\"petrified\",\"poisoned\"],\"senses\":[\"darkvision 120 ft., passive Perception 14\"],\"traits\":[{\"id\":\"bigbys-cradle-of-the-frost-scion-trait-0\",\"name\":\"Awakening of the Scion\",\"description\":\"The cradle is a container for the scion of Thrym. When the cradle drops to 0 hit points, its body shatters into shards of ice. The scion instantly appears in the space the cradle occupied and uses the cradle's initiative count.\"},{\"id\":\"bigbys-cradle-of-the-frost-scion-trait-1\",\"name\":\"Legendary Resistance (5/Day)\",\"description\":\"If the cradle fails a saving throw, it can choose to succeed instead.\"},{\"id\":\"bigbys-cradle-of-the-frost-scion-trait-2\",\"name\":\"Magic Resistance\",\"description\":\"The cradle has advantage on saving throws against spells and other magical effects.\"},{\"id\":\"bigbys-cradle-of-the-frost-scion-trait-3\",\"name\":\"Siege Monster\",\"description\":\"The cradle deals double damage to objects and structures.\"}],\"actions\":[{\"id\":\"bigbys-cradle-of-the-frost-scion-action-0\",\"name\":\"Multiattack\",\"description\":\"The cradle makes two Slam or Hurl Icicle attacks.\"},{\"id\":\"bigbys-cradle-of-the-frost-scion-action-1\",\"name\":\"Slam\",\"description\":\"mw 15 to hit, reach 20 ft., one target. {@h}30 (4d10 + 8) bludgeoning damage plus 11 (2d10) cold damage.\"},{\"id\":\"bigbys-cradle-of-the-frost-scion-action-2\",\"name\":\"Hurl Icicle\",\"description\":\"rw 15 to hit, range 120 ft., one target. {@h}26 (4d8 + 8) piercing damage plus 9 (2d8) cold damage, and the target must succeed on a 23 Strength saving throw or have the prone condition.\"},{\"id\":\"bigbys-cradle-of-the-frost-scion-action-3\",\"name\":\"Freezing Breath 5\",\"description\":\"The cradle exhales a blast of frost in a 90-foot cone. Each creature in that area must make a 23 Constitution saving throw. On a failed save, a creature takes 52 (8d12) cold damage, and its speed is reduced to 0 until the end of its next turn. On a successful save, a creature takes half as much damage only. If this damage would reduce the target to 0 hit points, the target drops to 1 hit point instead and has the petrified condition, turning into a frozen statue. If the statue takes bludgeoning damage, it shatters, killing the frozen creature. If the statue would take fire damage, it instead takes no damage and thaws, ending the petrification.\"}],\"bonusActions\":[{\"id\":\"bigbys-cradle-of-the-frost-scion-bonus-0\",\"name\":\"Chilling Mist\",\"description\":\"The cradle magically conjures a cloud of chilling mist that fills a 30-foot-radius sphere centered on a point it can see within 90 feet of itself. The mist spreads around corners. Each creature in that area must succeed on a 19 Constitution saving throw or take 28 (8d6) cold damage and be unable to use reactions until the start of its next turn. The mist vanishes at the end of the cradle's turn.\"}],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Giant\",\"Primordial\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-cradle-of-the-hill-scion\",\"name\":\"Cradle of the Hill Scion\",\"description\":\"Cradle of the Hill Scion from Bigby Presents: Glory of the Giants.\",\"size\":\"Gargantuan\",\"type\":\"elemental\",\"alignment\":\"C E\",\"ac\":19,\"hp\":{\"average\":402,\"formula\":\"23d20 + 161\"},\"speed\":\"40 ft.\",\"abilityScores\":{\"strength\":25,\"dexterity\":10,\"constitution\":24,\"intelligence\":9,\"wisdom\":16,\"charisma\":10},\"challengeRating\":\"22\",\"savingThrows\":[\"Wis +10\",\"Cha +7\"],\"damageResistances\":[\"cold\",\"fire\",\"lightning\",\"bludgeoning\",\"piercing\",\"slashing\",\"from nonmagical attacks\"],\"damageImmunities\":[\"poison\"],\"conditionImmunities\":[\"exhaustion\",\"paralyzed\",\"petrified\",\"poisoned\",\"prone\"],\"senses\":[\"passive Perception 13\"],\"traits\":[{\"id\":\"bigbys-cradle-of-the-hill-scion-trait-0\",\"name\":\"Awakening of the Scion\",\"description\":\"The cradle is a container for the scion of Grolantor. When the cradle drops to 0 hit points, its body crumbles to dirt and moss. The scion instantly appears in the space the cradle occupied and uses the cradle's initiative count.\"},{\"id\":\"bigbys-cradle-of-the-hill-scion-trait-1\",\"name\":\"Legendary Resistance (5/Day)\",\"description\":\"If the cradle fails a saving throw, it can choose to succeed instead.\"},{\"id\":\"bigbys-cradle-of-the-hill-scion-trait-2\",\"name\":\"Magic Resistance\",\"description\":\"The cradle has advantage on saving throws against spells and other magical effects.\"},{\"id\":\"bigbys-cradle-of-the-hill-scion-trait-3\",\"name\":\"Siege Monster\",\"description\":\"The cradle deals double damage to objects and structures.\"}],\"actions\":[{\"id\":\"bigbys-cradle-of-the-hill-scion-action-0\",\"name\":\"Multiattack\",\"description\":\"The cradle makes three Slam or Spit Rock attacks in any combination and one Grasping Root attack.\"},{\"id\":\"bigbys-cradle-of-the-hill-scion-action-1\",\"name\":\"Slam\",\"description\":\"mw 14 to hit, reach 20 ft., one target. {@h}33 (4d12 + 7) bludgeoning damage.\"},{\"id\":\"bigbys-cradle-of-the-hill-scion-action-2\",\"name\":\"Spit Rock\",\"description\":\"rw 14 to hit, range 120 ft., one target. {@h}25 (4d8 + 7) bludgeoning damage, and the target must succeed on a 22 Strength saving throw or have the prone condition.\"},{\"id\":\"bigbys-cradle-of-the-hill-scion-action-3\",\"name\":\"Grasping Root\",\"description\":\"mw 14 to hit, reach 30 ft., one creature not grappled by the cradle. {@h}the target has the grappled condition (escape 17). Until the grapple ends, the target takes 29 (4d10 + 7) bludgeoning damage at the start of each of its turns. The root has AC 19 and can be severed by dealing 15 or more slashing damage to it on one attack. Cutting the root doesn't hurt the cradle but ends the grapple.\"},{\"id\":\"bigbys-cradle-of-the-hill-scion-action-4\",\"name\":\"Rolling Hills {@recharge}\",\"description\":\"The cradle magically creates a wave of dirt that extends from a point on the ground within 120 feet of itself. The wave is up to 30 feet long, up to 30 feet tall, and up to 30 feet wide. Each creature in the wave must make a 22 Strength saving throw. On a failed save, a creature takes 58 (9d12) bludgeoning damage, has the prone condition, and is buried under dirt. On a successful save, a creature takes half as much damage only. A buried creature has the restrained condition, has 3, and can't breathe. As an action, a creature buried in this way, or another creature within 5 feet of it that isn't buried, can make a 17 Strength (Athletics) check. On a successful check, the buried creature no longer has the prone or restrained conditions.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Giant\",\"Primordial\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-cradle-of-the-stone-scion\",\"name\":\"Cradle of the Stone Scion\",\"description\":\"Cradle of the Stone Scion from Bigby Presents: Glory of the Giants.\",\"size\":\"Gargantuan\",\"type\":\"elemental\",\"alignment\":\"N\",\"ac\":20,\"hp\":{\"average\":455,\"formula\":\"26d20 + 182\"},\"speed\":\"40 ft.\",\"abilityScores\":{\"strength\":26,\"dexterity\":15,\"constitution\":24,\"intelligence\":11,\"wisdom\":18,\"charisma\":10},\"challengeRating\":\"23\",\"savingThrows\":[\"Wis +11\",\"Cha +7\"],\"damageResistances\":[\"cold\",\"fire\",\"lightning\",\"bludgeoning\",\"piercing\",\"slashing\",\"from nonmagical attacks\"],\"damageImmunities\":[\"acid\",\"poison\"],\"conditionImmunities\":[\"charmed\",\"exhaustion\",\"frightened\",\"paralyzed\",\"petrified\",\"poisoned\",\"prone\"],\"senses\":[\"tremorsense 120 ft., passive Perception 14\"],\"traits\":[{\"id\":\"bigbys-cradle-of-the-stone-scion-trait-0\",\"name\":\"Awakening of the Scion\",\"description\":\"The cradle is a container for the scion of Skoraeus. When the cradle drops to 0 hit points, its body crumbles to dust. The scion instantly appears in the space the cradle occupied and uses the cradle's initiative count.\"},{\"id\":\"bigbys-cradle-of-the-stone-scion-trait-1\",\"name\":\"Legendary Resistance (5/Day)\",\"description\":\"If the cradle fails a saving throw, it can choose to succeed instead.\"},{\"id\":\"bigbys-cradle-of-the-stone-scion-trait-2\",\"name\":\"Magic Resistance\",\"description\":\"The cradle has advantage on saving throws against spells and other magical effects.\"},{\"id\":\"bigbys-cradle-of-the-stone-scion-trait-3\",\"name\":\"Siege Monster\",\"description\":\"The cradle deals double damage to objects and structures.\"}],\"actions\":[{\"id\":\"bigbys-cradle-of-the-stone-scion-action-0\",\"name\":\"Multiattack\",\"description\":\"The cradle makes two Slam or Spit Rock attacks.\"},{\"id\":\"bigbys-cradle-of-the-stone-scion-action-1\",\"name\":\"Slam\",\"description\":\"mw 15 to hit, reach 20 ft., one target. {@h}30 (4d10 + 8) bludgeoning damage.\"},{\"id\":\"bigbys-cradle-of-the-stone-scion-action-2\",\"name\":\"Spit Rock\",\"description\":\"rw 15 to hit, range 120 ft., one target. {@h}24 (3d10 + 8) bludgeoning damage, and the target must succeed on a 23 Strength saving throw or have the prone condition.\"},{\"id\":\"bigbys-cradle-of-the-stone-scion-action-3\",\"name\":\"Shattering Roar 5\",\"description\":\"The cradle lets out a painfully loud roar. Each creature within 60 feet of the cradle must make a 23 Constitution saving throw. On a failed save, a creature takes 33 (6d10) thunder damage and has the incapacitated condition until the end of its next turn.\"}],\"bonusActions\":[{\"id\":\"bigbys-cradle-of-the-stone-scion-bonus-0\",\"name\":\"Crystal Flare\",\"description\":\"The cradle causes the crystals on its body to flare with light. Each creature within 30 feet of the cradle must succeed on a 22 Constitution saving throw or take 21 (6d6) radiant damage and have the blinded condition until the end of the cradle's next turn.\"},{\"id\":\"bigbys-cradle-of-the-stone-scion-bonus-1\",\"name\":\"Stone Spikes\",\"description\":\"The cradle causes the ground in a 20-foot square within 90 feet of itself to sprout crystal spikes until the start of its next turn. The area becomes difficult terrain for the duration. A creature takes 10 (3d6) piercing damage for each 5 feet it moves on this terrain.\"}],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Giant\",\"Primordial\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-cradle-of-the-storm-scion\",\"name\":\"Cradle of the Storm Scion\",\"description\":\"Cradle of the Storm Scion from Bigby Presents: Glory of the Giants.\",\"size\":\"Gargantuan\",\"type\":\"elemental\",\"alignment\":\"C G\",\"ac\":19,\"hp\":{\"average\":682,\"formula\":\"35d20 + 315\"},\"speed\":\"40 ft., fly 60 ft., swim 60 ft.\",\"abilityScores\":{\"strength\":30,\"dexterity\":14,\"constitution\":29,\"intelligence\":16,\"wisdom\":23,\"charisma\":18},\"challengeRating\":\"27\",\"damageResistances\":[\"cold\",\"fire\",\"thunder\",\"bludgeoning\",\"piercing\",\"slashing\",\"from nonmagical attacks\"],\"damageImmunities\":[\"lightning\",\"poison\"],\"conditionImmunities\":[\"exhaustion\",\"grappled\",\"paralyzed\",\"petrified\",\"poisoned\",\"prone\",\"restrained\",\"stunned\"],\"senses\":[\"passive Perception 16\"],\"traits\":[{\"id\":\"bigbys-cradle-of-the-storm-scion-trait-0\",\"name\":\"Awakening of the Scion\",\"description\":\"The cradle is a container for the scion of Stronmaus. When the cradle drops to 0 hit points, its body bursts into light. The scion instantly appears in the space the cradle occupied and uses the cradle's initiative count.\"},{\"id\":\"bigbys-cradle-of-the-storm-scion-trait-1\",\"name\":\"Legendary Resistance (5/Day)\",\"description\":\"If the cradle fails a saving throw, it can choose to succeed instead.\"},{\"id\":\"bigbys-cradle-of-the-storm-scion-trait-2\",\"name\":\"Magic Resistance\",\"description\":\"The cradle has advantage on saving throws against spells and other magical effects.\"},{\"id\":\"bigbys-cradle-of-the-storm-scion-trait-3\",\"name\":\"Siege Monster\",\"description\":\"The cradle deals double damage to objects and structures.\"}],\"actions\":[{\"id\":\"bigbys-cradle-of-the-storm-scion-action-0\",\"name\":\"Multiattack\",\"description\":\"The cradle makes three Slam or Spit Hailstone attacks in any combination.\"},{\"id\":\"bigbys-cradle-of-the-storm-scion-action-1\",\"name\":\"Slam\",\"description\":\"mw 18 to hit, reach 20 ft., one target. {@h}36 (4d12 + 10) bludgeoning damage plus 19 (3d12) lightning damage.\"},{\"id\":\"bigbys-cradle-of-the-storm-scion-action-2\",\"name\":\"Spit Hailstone\",\"description\":\"rw 18 to hit, range 120 ft., one target. {@h}32 (4d10 + 10) bludgeoning damage plus 14 (4d6) cold damage, and the target must succeed on a 26 Strength saving throw or have the prone condition.\"},{\"id\":\"bigbys-cradle-of-the-storm-scion-action-3\",\"name\":\"Lightning Barrage 5\",\"description\":\"The cradle hurls multiple magical lightning bolts at up to two creatures it can see within 500 feet of itself. Each target must make a 22 Dexterity saving throw. On a failed save, the target takes 71 (11d12) lightning damage and has the stunned condition until the end of its next turn. On a successful save, the target takes half as much damage only.\"}],\"bonusActions\":[],\"reactions\":[{\"id\":\"bigbys-cradle-of-the-storm-scion-reaction-0\",\"name\":\"Booming Step\",\"description\":\"Immediately after taking damage, the cradle cracks with thunder and then magically teleports up to 60 feet to an unoccupied space it can see. Each creature within 10 feet of the space the cradle left must make a 22 Constitution saving throw, taking 14 (4d6) thunder damage on a failed save, or half as much damage on a successful one.\"}],\"legendaryActions\":[],\"languages\":[\"Giant\",\"Primordial\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-death-giant-reaper\",\"name\":\"Death Giant Reaper\",\"description\":\"Death Giant Reaper from Bigby Presents: Glory of the Giants.\",\"size\":\"Huge\",\"type\":\"giant\",\"alignment\":\"A\",\"ac\":18,\"hp\":{\"average\":172,\"formula\":\"15d12 + 75\"},\"speed\":\"40 ft.\",\"abilityScores\":{\"strength\":27,\"dexterity\":14,\"constitution\":20,\"intelligence\":18,\"wisdom\":16,\"charisma\":16},\"challengeRating\":\"12\",\"savingThrows\":[\"Con +9\",\"Int +8\",\"Wis +7\",\"Cha +7\"],\"skills\":[\"Arcana +8\",\"History +8\",\"Perception +7\",\"Stealth +6\"],\"damageImmunities\":[\"necrotic\"],\"conditionImmunities\":[\"frightened\"],\"senses\":[\"darkvision 120 ft., passive Perception 17\"],\"traits\":[],\"actions\":[{\"id\":\"bigbys-death-giant-reaper-action-0\",\"name\":\"Multiattack\",\"description\":\"The giant makes two Scythe or Soul Bolt attacks.\"},{\"id\":\"bigbys-death-giant-reaper-action-1\",\"name\":\"Scythe\",\"description\":\"mw 12 to hit, reach 15 ft., one target. {@h}21 (3d8 + 8) slashing damage plus 11 (2d10) necrotic damage.\"},{\"id\":\"bigbys-death-giant-reaper-action-2\",\"name\":\"Soul Bolt\",\"description\":\"rs 8 to hit, range 120 ft., one creature. {@h}26 (4d10 + 4) necrotic damage. If the target has the frightened condition, the giant gains temporary hit points equal to the damage dealt.\"}],\"bonusActions\":[{\"id\":\"bigbys-death-giant-reaper-bonus-0\",\"name\":\"Frightening Teleport 4\",\"description\":\"The giant magically teleports, along with any equipment it is wearing or carrying, up to 40 feet to an unoccupied space it can see. Each creature within 10 feet of the location the giant left must succeed on a 16 Wisdom saving throw or have the frightened condition until the end of that creature's next turn.\"}],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Giant\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-death-giant-shrouded-one\",\"name\":\"Death Giant Shrouded One\",\"description\":\"Death Giant Shrouded One from Bigby Presents: Glory of the Giants.\",\"size\":\"Huge\",\"type\":\"giant\",\"alignment\":\"A\",\"ac\":12,\"hp\":{\"average\":195,\"formula\":\"17d12 + 85\"},\"speed\":\"40 ft.\",\"abilityScores\":{\"strength\":27,\"dexterity\":14,\"constitution\":20,\"intelligence\":23,\"wisdom\":16,\"charisma\":16},\"challengeRating\":\"15\",\"savingThrows\":[\"Con +10\",\"Int +11\",\"Wis +8\",\"Cha +8\"],\"skills\":[\"Arcana +11\",\"Perception +8\",\"Stealth +7\"],\"damageImmunities\":[\"necrotic\"],\"conditionImmunities\":[\"frightened\"],\"senses\":[\"darkvision 120 ft., passive Perception 18\"],\"traits\":[{\"id\":\"bigbys-death-giant-shrouded-one-trait-0\",\"name\":\"Death Rune\",\"description\":\"The giant has a death rune inscribed on a giant's skull in its possession. While holding or wearing the skull bearing the rune, the giant can use its Reaping Scythe action and Shroud of Souls bonus action. The skull bearing the death rune has AC 18; 35 hit points; and immunity to necrotic, poison, and psychic damage. The skull regains all its hit points at the end of every turn, but it turns to dust if reduced to 0 hit points or when the giant dies. If the rune is destroyed, the giant can inscribe a death rune on another skull in its possession when it finishes a short or long rest.\"}],\"actions\":[{\"id\":\"bigbys-death-giant-shrouded-one-action-0\",\"name\":\"Multiattack\",\"description\":\"The giant makes three Soul Burst attacks. Alternatively, if the giant has its death rune, it can make three Reaping Scythe attacks.\"},{\"id\":\"bigbys-death-giant-shrouded-one-action-1\",\"name\":\"Soul Burst\",\"description\":\"ms,rs 11 to hit, reach 10 ft. or range 120 ft., one target. {@h}28 (4d10 + 6) necrotic damage. If the target has the frightened condition, the giant gains temporary hit points equal to the damage dealt.\"},{\"id\":\"bigbys-death-giant-shrouded-one-action-2\",\"name\":\"Reaping Scythe (Requires Death Rune)\",\"description\":\"ms 11 to hit, reach 15 ft., one creature. {@h}38 (7d10) necrotic damage, and the target can't regain hit points until the end of its next turn. The target dies if it is reduced to 0 hit points by this attack.\"}],\"bonusActions\":[{\"id\":\"bigbys-death-giant-shrouded-one-bonus-0\",\"name\":\"Frightening Teleport 4\",\"description\":\"The giant magically teleports, along with any equipment it is wearing or carrying, up to 40 feet to an unoccupied space it can see. Each creature within 10 feet of the location the giant left must succeed on a 19 Wisdom saving throw or have the frightened condition until the end of that creature's next turn.\"},{\"id\":\"bigbys-death-giant-shrouded-one-bonus-1\",\"name\":\"Shroud of Souls (Requires Death Rune)\",\"description\":\"The giant shrouds itself in a torrent of souls. While the giant is shrouded, each creature that starts its turn within 5 feet of the giant must succeed on a 19 Wisdom saving throw or have disadvantage on saving throws until the end of that creature's next turn. The shroud disappears after 1 minute, when the giant dies, when the giant uses this bonus action again, or when the giant's death rune is destroyed.\"}],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Common\",\"Giant\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-dust-hulk\",\"name\":\"Dust Hulk\",\"description\":\"Dust Hulk from Bigby Presents: Glory of the Giants.\",\"size\":\"Large\",\"type\":\"elemental\",\"alignment\":\"C N\",\"ac\":16,\"hp\":{\"average\":68,\"formula\":\"8d10 + 24\"},\"speed\":\"0 ft., fly 30 ft.\",\"abilityScores\":{\"strength\":15,\"dexterity\":19,\"constitution\":16,\"intelligence\":10,\"wisdom\":12,\"charisma\":8},\"challengeRating\":\"5\",\"damageImmunities\":[\"poison\"],\"conditionImmunities\":[\"exhaustion\",\"grappled\",\"paralyzed\",\"petrified\",\"poisoned\",\"restrained\"],\"senses\":[\"darkvision 60 ft., passive Perception 11\"],\"traits\":[{\"id\":\"bigbys-dust-hulk-trait-0\",\"name\":\"Air Form\",\"description\":\"The dust hulk can enter a hostile creature's space and stop there. It can move through a space as narrow as 1 inch without squeezing.\"},{\"id\":\"bigbys-dust-hulk-trait-1\",\"name\":\"Death Burst\",\"description\":\"When the dust hulk dies, it explodes in a burst of dust that fills a 10-foot-radius sphere centered on itself. Each creature in that area must succeed on a 14 Constitution saving throw or have the blinded condition for 1 minute. An affected creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.\"}],\"actions\":[{\"id\":\"bigbys-dust-hulk-action-0\",\"name\":\"Multiattack\",\"description\":\"The dust hulk makes three Slam attacks. It can replace one of these attacks with Stinging Dust.\"},{\"id\":\"bigbys-dust-hulk-action-1\",\"name\":\"Slam\",\"description\":\"mw 7 to hit, reach 10 ft., one target. {@h}13 (2d8 + 4) bludgeoning damage.\"},{\"id\":\"bigbys-dust-hulk-action-2\",\"name\":\"Stinging Dust\",\"description\":\"One creature of the dust hulk's choice inside its space must make a 14 Constitution saving throw. On a failed save, the creature takes 10 (3d6) bludgeoning damage and has the blinded condition until the end of its next turn. On a successful save, the creature takes half as much damage only.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Giant\",\"Terran\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-echo-of-demogorgon\",\"name\":\"Echo of Demogorgon\",\"description\":\"Echo of Demogorgon from Bigby Presents: Glory of the Giants.\",\"size\":\"Large\",\"type\":\"fiend\",\"alignment\":\"C E\",\"ac\":14,\"hp\":{\"average\":85,\"formula\":\"10d10 + 30\"},\"speed\":\"40 ft.\",\"abilityScores\":{\"strength\":22,\"dexterity\":10,\"constitution\":17,\"intelligence\":10,\"wisdom\":12,\"charisma\":14},\"challengeRating\":\"6\",\"savingThrows\":[\"Str +9\",\"Cha +5\"],\"skills\":[\"Perception +7\"],\"damageResistances\":[\"cold\",\"fire\",\"lightning\"],\"conditionImmunities\":[\"charmed\",\"frightened\"],\"senses\":[\"darkvision 60 ft., passive Perception 17\"],\"traits\":[{\"id\":\"bigbys-echo-of-demogorgon-trait-0\",\"name\":\"Magic Resistance\",\"description\":\"The echo has advantage on saving throws against spells and other magical effects.\"},{\"id\":\"bigbys-echo-of-demogorgon-trait-1\",\"name\":\"Wakeful\",\"description\":\"When one of the echo's heads is asleep, its other head is awake.\"}],\"actions\":[{\"id\":\"bigbys-echo-of-demogorgon-action-0\",\"name\":\"Multiattack\",\"description\":\"The echo makes two Tentacle attacks.\"},{\"id\":\"bigbys-echo-of-demogorgon-action-1\",\"name\":\"Tentacle\",\"description\":\"mw 9 to hit, reach 10 ft., one target. {@h}13 (2d6 + 6) bludgeoning damage plus 9 (2d8) necrotic damage.\"}],\"bonusActions\":[{\"id\":\"bigbys-echo-of-demogorgon-bonus-0\",\"name\":\"Discordant Screams\",\"description\":\"The echo directs its frenzied howls at one creature it can see within 60 feet of itself. The target must succeed on a 13 Wisdom saving throw or suffer one of the following effects of the echo's choice: Confused Reaction: The target must use its reaction to make a melee attack against another creature of the echo's choice that the echo can see. Psychic Torment: The target takes 13 (2d12) psychic damage.\"}],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Abyssal\",\"Giant\",\"Orc\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-ettin-ceremorph\",\"name\":\"Ettin Ceremorph\",\"description\":\"Ettin Ceremorph from Bigby Presents: Glory of the Giants.\",\"size\":\"Large\",\"type\":\"aberration\",\"alignment\":\"L E\",\"ac\":15,\"hp\":{\"average\":104,\"formula\":\"11d10 + 44\"},\"speed\":\"40 ft.\",\"abilityScores\":{\"strength\":18,\"dexterity\":14,\"constitution\":18,\"intelligence\":18,\"wisdom\":15,\"charisma\":14},\"challengeRating\":\"8\",\"savingThrows\":[\"Int +7\",\"Wis +5\"],\"skills\":[\"Perception +8\"],\"damageResistances\":[\"psychic\"],\"conditionImmunities\":[\"charmed\",\"frightened\",\"stunned\",\"unconscious\"],\"senses\":[\"darkvision 120 ft., passive Perception 18\"],\"traits\":[{\"id\":\"bigbys-ettin-ceremorph-trait-0\",\"name\":\"Magic Resistance\",\"description\":\"The ceremorph has advantage on saving throws against spells and other magical effects.\"}],\"actions\":[{\"id\":\"bigbys-ettin-ceremorph-action-0\",\"name\":\"Multiattack\",\"description\":\"The ceremorph makes one Slam attack and one Tentacles attack. The ceremorph can replace one of the attacks with a Mind Bolt attack, if available.\"},{\"id\":\"bigbys-ettin-ceremorph-action-1\",\"name\":\"Slam\",\"description\":\"mw 7 to hit, reach 10 ft., one target. {@h}22 (4d8 + 4) bludgeoning damage.\"},{\"id\":\"bigbys-ettin-ceremorph-action-2\",\"name\":\"Tentacles\",\"description\":\"mw 7 to hit, reach 10 ft., one creature. {@h}15 (2d10 + 4) psychic damage. If the target is Large or smaller, it has the grappled condition (escape 14) and must succeed on a 15 Intelligence saving throw or have the stunned condition until this grapple ends.\"},{\"id\":\"bigbys-ettin-ceremorph-action-3\",\"name\":\"Extract Brain\",\"description\":\"mw 7 to hit, reach 5 ft., one incapacitated Humanoid grappled by the ceremorph. {@h}55 (10d10) piercing damage. If this damage reduces the target to 0 hit points, the ceremorph kills the target by extracting and devouring its brain.\"},{\"id\":\"bigbys-ettin-ceremorph-action-4\",\"name\":\"Mind Bolt (3/Day)\",\"description\":\"rs 7 to hit, range 120 ft., one creature. {@h}17 (2d12 + 4) psychic damage, and the target must succeed on a 15 Intelligence saving throw or have the stunned condition until the end of its next turn.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Deep Speech\",\"Giant\",\"telepathy 60 ft.\",\"Undercommon\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-fensir-devourer\",\"name\":\"Fensir Devourer\",\"description\":\"Fensir Devourer from Bigby Presents: Glory of the Giants.\",\"size\":\"Huge\",\"type\":\"celestial\",\"alignment\":\"C N\",\"ac\":17,\"hp\":{\"average\":138,\"formula\":\"12d12 + 60\"},\"speed\":\"40 ft.\",\"abilityScores\":{\"strength\":20,\"dexterity\":10,\"constitution\":21,\"intelligence\":10,\"wisdom\":14,\"charisma\":11},\"challengeRating\":\"8\",\"skills\":[\"Perception +8\",\"Survival +8\"],\"senses\":[\"darkvision 60 ft., passive Perception 18\"],\"traits\":[{\"id\":\"bigbys-fensir-devourer-trait-0\",\"name\":\"Death Curse\",\"description\":\"When the fensir starts its turn with 0 hit points and doesn't regenerate, it releases a curse on those around it. Each creature within 30 feet of the fensir when it dies must succeed on a 13 Charisma saving throw or be cursed for the next 24 hours. While cursed in this way, an affected creature gains no benefit from finishing a short or long rest. At the end of every hour, the creature must succeed on a 13 Charisma saving throw or take 11 (2d10) psychic damage.\"},{\"id\":\"bigbys-fensir-devourer-trait-1\",\"name\":\"Regeneration\",\"description\":\"The fensir regains 10 hit points at the start of its turn if it isn't in sunlight. If the fensir takes acid or fire damage, this trait doesn't function at the start of the fensir's next turn. The fensir dies only if it starts its turn with 0 hit points and doesn't regenerate.\"},{\"id\":\"bigbys-fensir-devourer-trait-2\",\"name\":\"Sunlight Hypersensitivity\",\"description\":\"When the fensir starts its turn in sunlight, it must succeed on a 15 Constitution saving throw or have the petrified condition until the fensir is no longer in sunlight.\"}],\"actions\":[{\"id\":\"bigbys-fensir-devourer-action-0\",\"name\":\"Multiattack\",\"description\":\"The fensir makes two attacks, using Rend, Boulder, or a combination of them.\"},{\"id\":\"bigbys-fensir-devourer-action-1\",\"name\":\"Rend\",\"description\":\"mw 8 to hit, reach 10 ft., one target. {@h}21 (3d10 + 5) slashing damage.\"},{\"id\":\"bigbys-fensir-devourer-action-2\",\"name\":\"Boulder\",\"description\":\"rw 8 to hit, range 60/240 ft., one target. {@h}18 (2d12 + 5) bludgeoning damage. If the target is a Large or smaller creature, it must succeed on a 16 Strength saving throw or have the prone condition. After the fensir throws the boulder, roll a d6; on a roll of 4 or lower, the fensir has no more boulders to throw.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Common\",\"Giant\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-fensir-skirmisher\",\"name\":\"Fensir Skirmisher\",\"description\":\"Fensir Skirmisher from Bigby Presents: Glory of the Giants.\",\"size\":\"Large\",\"type\":\"giant\",\"alignment\":\"A\",\"ac\":15,\"hp\":{\"average\":94,\"formula\":\"9d10 + 45\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":18,\"dexterity\":15,\"constitution\":20,\"intelligence\":14,\"wisdom\":11,\"charisma\":12},\"challengeRating\":\"6\",\"savingThrows\":[\"Int +5\",\"Wis +3\"],\"skills\":[\"Perception +6\"],\"senses\":[\"darkvision 60 ft., passive Perception 16\"],\"traits\":[{\"id\":\"bigbys-fensir-skirmisher-trait-0\",\"name\":\"Regeneration\",\"description\":\"The fensir regains 10 hit points at the start of its turn if it isn't in sunlight. If the fensir takes acid or fire damage, this trait doesn't function at the start of the fensir's next turn. The fensir dies only if it starts its turn with 0 hit points and doesn't regenerate.\"},{\"id\":\"bigbys-fensir-skirmisher-trait-1\",\"name\":\"Sunlight Hypersensitivity\",\"description\":\"When the fensir starts its turn in sunlight, it must succeed on a 15 Constitution saving throw or have the petrified condition until the fensir is no longer in sunlight.\"}],\"actions\":[{\"id\":\"bigbys-fensir-skirmisher-action-0\",\"name\":\"Multiattack\",\"description\":\"The fensir makes three Battleaxe attacks or two Magic Stone attacks.\"},{\"id\":\"bigbys-fensir-skirmisher-action-1\",\"name\":\"Battleaxe\",\"description\":\"mw 7 to hit, reach 5 ft., one target. {@h}13 (2d8 + 4) slashing damage, or 15 (2d10 + 4) slashing damage if used with two hands.\"},{\"id\":\"bigbys-fensir-skirmisher-action-2\",\"name\":\"Magic Stone\",\"description\":\"rs 5 to hit, range 60 ft., one target. {@h}15 (2d12 + 2) bludgeoning damage. If the target is a Large or smaller creature, it must succeed on a 13 Strength saving throw or have the prone condition.\"},{\"id\":\"bigbys-fensir-skirmisher-action-3\",\"name\":\"Mud to Stone {@recharge}\",\"description\":\"The fensir lobs a magical mass of mud that splashes all creatures in a 30-foot-radius sphere centered on a point the fensir can see within 60 feet of itself. Each non-fensir creature in that area must succeed on a 13 Dexterity saving throw or take 13 (3d8) bludgeoning damage and have the restrained condition as the mud begins to turn to stone. An affected creature must repeat the saving throw at the end of its next turn. On a successful save, the effect ends on the creature. On a failed save, the creature has the petrified condition for 24 hours.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Common\",\"Giant\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-firbolg-primeval-warden\",\"name\":\"Firbolg Primeval Warden\",\"description\":\"Firbolg Primeval Warden from Bigby Presents: Glory of the Giants.\",\"size\":\"Medium\",\"type\":\"humanoid\",\"alignment\":\"A\",\"ac\":16,\"hp\":{\"average\":65,\"formula\":\"10d8 + 20\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":16,\"dexterity\":14,\"constitution\":14,\"intelligence\":12,\"wisdom\":16,\"charisma\":11},\"challengeRating\":\"4\",\"savingThrows\":[\"Int +3\",\"Wis +5\"],\"skills\":[\"Medicine +5\",\"Nature +3\",\"Perception +7\"],\"senses\":[\"passive Perception 17\"],\"traits\":[],\"actions\":[{\"id\":\"bigbys-firbolg-primeval-warden-action-0\",\"name\":\"Multiattack\",\"description\":\"The firbolg makes two Spear or Fire Lance attacks.\"},{\"id\":\"bigbys-firbolg-primeval-warden-action-1\",\"name\":\"Spear\",\"description\":\"mw,rw 5 to hit, reach 5 ft. or range 20/60 ft., one target. {@h}6 (1d6 + 3) piercing damage plus 9 (2d8) fire damage.\"},{\"id\":\"bigbys-firbolg-primeval-warden-action-2\",\"name\":\"Fire Lance\",\"description\":\"rs 5 to hit, range 120 ft., one target. {@h}14 (2d10 + 3) fire damage.\"}],\"bonusActions\":[{\"id\":\"bigbys-firbolg-primeval-warden-bonus-0\",\"name\":\"Hidden Step (2/Day)\",\"description\":\"The firbolg magically turns invisible until the start of its next turn, until it makes an attack roll, or until it forces someone to make a saving throw.\"}],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Common\",\"Druidic\",\"Giant\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-firbolg-wanderer\",\"name\":\"Firbolg Wanderer\",\"description\":\"Firbolg Wanderer from Bigby Presents: Glory of the Giants.\",\"size\":\"Medium\",\"type\":\"humanoid\",\"alignment\":\"A\",\"ac\":16,\"hp\":{\"average\":90,\"formula\":\"12d8 + 36\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":16,\"dexterity\":14,\"constitution\":16,\"intelligence\":14,\"wisdom\":17,\"charisma\":16},\"challengeRating\":\"5\",\"savingThrows\":[\"Dex +5\",\"Cha +6\"],\"skills\":[\"Perception +6\",\"Persuasion +6\",\"Stealth +5\"],\"senses\":[\"passive Perception 16\"],\"traits\":[],\"actions\":[{\"id\":\"bigbys-firbolg-wanderer-action-0\",\"name\":\"Multiattack\",\"description\":\"The firbolg makes two attacks using Longsword, Bewitching Bolt, or a combination of them.\"},{\"id\":\"bigbys-firbolg-wanderer-action-1\",\"name\":\"Longsword\",\"description\":\"mw 6 to hit, reach 5 ft., one target. {@h}7 (1d8 + 3) slashing damage, or 8 (1d10 + 3) slashing damage if used with two hands, plus 9 (2d8) psychic damage.\"},{\"id\":\"bigbys-firbolg-wanderer-action-2\",\"name\":\"Bewitching Bolt\",\"description\":\"rs 6 to hit, range 60 ft., one creature. {@h}10 (2d6 + 3) psychic damage, and the target must succeed on a 14 Charisma saving throw or have the charmed condition until the start of the target's next turn.\"}],\"bonusActions\":[{\"id\":\"bigbys-firbolg-wanderer-bonus-0\",\"name\":\"Duplicitous Movement (1/Day)\",\"description\":\"The firbolg projects an illusory duplicate of itself in an unoccupied space it can see within 30 feet of itself. The firbolg can then swap places with the illusion. The illusion vanishes after 1 minute, if the firbolg is incapacitated, or if the illusion is more than 120 feet from the firbolg. As a bonus action on later turns, the firbolg can move the illusion up to 30 feet and can then swap places with it.\"}],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Common\",\"Giant\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-fire-giant-forgecaller\",\"name\":\"Fire Giant Forgecaller\",\"description\":\"Fire Giant Forgecaller from Bigby Presents: Glory of the Giants.\",\"size\":\"Huge\",\"type\":\"giant\",\"alignment\":\"A\",\"ac\":18,\"hp\":{\"average\":312,\"formula\":\"25d12 + 150\"},\"speed\":\"30 ft., fly 30 ft.\",\"abilityScores\":{\"strength\":25,\"dexterity\":11,\"constitution\":23,\"intelligence\":16,\"wisdom\":21,\"charisma\":18},\"challengeRating\":\"18\",\"savingThrows\":[\"Dex +6\",\"Int +9\",\"Wis +11\"],\"skills\":[\"Athletics +13\",\"Perception +11\"],\"damageImmunities\":[\"fire\"],\"senses\":[\"passive Perception 21\"],\"traits\":[{\"id\":\"bigbys-fire-giant-forgecaller-trait-0\",\"name\":\"Legendary Resistance (3/Day)\",\"description\":\"If the giant fails a saving throw, it can choose to succeed instead.\"},{\"id\":\"bigbys-fire-giant-forgecaller-trait-1\",\"name\":\"Fire Rune\",\"description\":\"The giant has a fire rune inscribed on a medallion or some other object in its possession. While holding or wearing the object bearing the rune, the giant can use its Magma Wave action and Furnace Armor bonus action. The object bearing the rune has AC 15; 40 hit points; and immunity to necrotic, poison, and psychic damage. The object regains all its hit points at the end of every turn, but it turns to dust if reduced to 0 hit points or when the giant dies. If the rune is destroyed, the giant can inscribe a fire rune on an object in its possession when it finishes a short or long rest.\"}],\"actions\":[{\"id\":\"bigbys-fire-giant-forgecaller-action-0\",\"name\":\"Multiattack\",\"description\":\"The giant makes three Forge Hammer attacks or two Heated Rock attacks.\"},{\"id\":\"bigbys-fire-giant-forgecaller-action-1\",\"name\":\"Forge Hammer\",\"description\":\"mw 13 to hit, reach 10 ft., one target. {@h}24 (5d6 + 7) bludgeoning damage. {@hom}The giant can cause the hammer to emit a burst of heat in a 30-foot-radius sphere centered on the target. Metal objects in that area glow red-hot until the start of the giant's next turn. Any creature in physical contact with a heated object at the start of its turn must make a 19 Constitution saving throw. On a failed save, the creature takes 10 (3d6) fire damage and has disadvantage on attack rolls until the start of its next turn unless it has immunity to fire damage. The hammer can emit heat in this way only once per turn.\"},{\"id\":\"bigbys-fire-giant-forgecaller-action-2\",\"name\":\"Heated Rock\",\"description\":\"rw 13 to hit, range 60/240 ft., one target. {@h}23 (3d10 + 7) bludgeoning damage plus 19 (3d12) fire damage. If the target is a Large or smaller creature, it must succeed on a 21 Strength saving throw or have the prone condition. After the giant throws the rock, roll a d6; on a roll of 3 or lower, the giant has no more rocks to throw.\"},{\"id\":\"bigbys-fire-giant-forgecaller-action-3\",\"name\":\"Magma Wave (Requires Fire Rune)\",\"description\":\"The giant emits a wave of magma from its fire rune in a 30-foot cone. Each creature in that area must make a 19 Dexterity saving throw. On a failed save, a creature takes 36 (8d8) fire damage and has the restrained condition. As an action, a creature can make a 19 Strength (Athletics) check, freeing itself or a creature within its reach from the rock on a success. The rock restraining each creature has AC 17; 20 hit points; and immunity to fire, poison, and psychic damage. On a successful save, a creature takes half as much damage only.\"}],\"bonusActions\":[{\"id\":\"bigbys-fire-giant-forgecaller-bonus-0\",\"name\":\"Furnace Armor (Requires Fire Rune)\",\"description\":\"The giant causes smoke and cinders to billow from its armor, filling a 30-foot-radius sphere centered on the giant. While the armor is billowing smoke, the giant has 3. The armor stops billowing smoke after 1 minute, when the giant dies, when the giant uses a bonus action to end the effect, or when the giant's fire rune is destroyed.\"}],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Common\",\"Giant\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-fire-giant-of-evil-fire\",\"name\":\"Fire Giant of Evil Fire\",\"description\":\"Fire Giant of Evil Fire from Bigby Presents: Glory of the Giants.\",\"size\":\"Huge\",\"type\":\"giant\",\"alignment\":\"L E\",\"ac\":18,\"hp\":{\"average\":150,\"formula\":\"12d12 + 72\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":25,\"dexterity\":9,\"constitution\":23,\"intelligence\":10,\"wisdom\":19,\"charisma\":14},\"challengeRating\":\"10\",\"savingThrows\":[\"Con +10\",\"Wis +8\",\"Cha +6\"],\"skills\":[\"Athletics +11\",\"Perception +8\"],\"damageImmunities\":[\"fire\"],\"senses\":[\"passive Perception 18\"],\"traits\":[{\"id\":\"bigbys-fire-giant-of-evil-fire-trait-0\",\"name\":\"Shrapnel Explosion\",\"description\":\"When the giant drops to 0 hit points, its armor explodes, destroying the giant's body and scattering the armor as shrapnel. Creatures within 10 feet of the giant when its armor explodes must make a 18 Dexterity saving throw, taking 21 (6d6) piercing damage on a failed save, or half as much damage on a successful one.\"}],\"actions\":[{\"id\":\"bigbys-fire-giant-of-evil-fire-action-0\",\"name\":\"Multiattack\",\"description\":\"The giant makes two Searing Scepter attacks or two Bolt of Imix attacks.\"},{\"id\":\"bigbys-fire-giant-of-evil-fire-action-1\",\"name\":\"Searing Scepter\",\"description\":\"mw 11 to hit, reach 10 ft., one target. {@h}17 (3d6 + 7) bludgeoning damage plus 9 (2d8) fire damage, and the target is magically branded. While branded in this way, the target becomes visible if it's invisible, can't become invisible, and sheds dim light in a 5-foot radius. The brand disappears after 24 hours, or it can be removed from a creature or an object by any spell that ends a curse.\"},{\"id\":\"bigbys-fire-giant-of-evil-fire-action-2\",\"name\":\"Bolt of Imix\",\"description\":\"rs 8 to hit, range 120 ft., one target. {@h}20 (3d10 + 4) fire damage, and the target must succeed on a 16 Wisdom saving throw or have the frightened condition until the end of the target's next turn.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Common\",\"Giant\",\"Ignan\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-fire-hellion\",\"name\":\"Fire Hellion\",\"description\":\"Fire Hellion from Bigby Presents: Glory of the Giants.\",\"size\":\"Huge\",\"type\":\"fiend\",\"alignment\":\"L E\",\"ac\":18,\"hp\":{\"average\":175,\"formula\":\"14d12 + 84\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":25,\"dexterity\":10,\"constitution\":23,\"intelligence\":16,\"wisdom\":14,\"charisma\":21},\"challengeRating\":\"11\",\"savingThrows\":[\"Wis +6\",\"Cha +9\"],\"skills\":[\"Arcana +7\",\"Athletics +11\",\"Perception +6\"],\"damageImmunities\":[\"fire\"],\"conditionImmunities\":[\"charmed\",\"frightened\"],\"senses\":[\"darkvision 120 ft., passive Perception 16\"],\"traits\":[{\"id\":\"bigbys-fire-hellion-trait-0\",\"name\":\"Magic Resistance\",\"description\":\"The hellion has advantage on saving throws against spells and other magical effects.\"},{\"id\":\"bigbys-fire-hellion-trait-1\",\"name\":\"Soul Taker\",\"description\":\"A Giant or a Humanoid that is reduced to 0 hit points by the hellion dies, and its soul rises as a lemure (see the Monster Manual) on Avernus, one of the Nine Hells, in 1d4 hours. If the creature isn't revived before then, it can be restored to life only by a wish spell or by killing the lemure and casting true resurrection on the creature's original body.\"}],\"actions\":[{\"id\":\"bigbys-fire-hellion-action-0\",\"name\":\"Multiattack\",\"description\":\"The hellion makes two Morningstar attacks.\"},{\"id\":\"bigbys-fire-hellion-action-1\",\"name\":\"Morningstar\",\"description\":\"mw 11 to hit, reach 10 ft., one target. {@h}20 (3d8 + 7) piercing damage plus 11 (2d10) fire damage. If the target is a creature, it can't regain hit points until the start of the hellion's next turn.\"},{\"id\":\"bigbys-fire-hellion-action-2\",\"name\":\"Infernal Orb\",\"description\":\"The hellion hurls a magical ball of fire that explodes in a 20-foot-radius sphere centered on a point the hellion can see within 120 feet of itself. The sphere spreads around corners. Each creature in that area must make a 17 Dexterity saving throw. A creature takes 18 (4d8) fire damage and 18 (4d8) necrotic damage on a failed save, or half as much damage on a successful one.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Common\",\"Giant\",\"Infernal\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-firegaunt\",\"name\":\"Firegaunt\",\"description\":\"Firegaunt from Bigby Presents: Glory of the Giants.\",\"size\":\"Huge\",\"type\":\"undead\",\"alignment\":\"L E\",\"ac\":15,\"hp\":{\"average\":175,\"formula\":\"14d12 + 84\"},\"speed\":\"40 ft.\",\"abilityScores\":{\"strength\":25,\"dexterity\":7,\"constitution\":23,\"intelligence\":10,\"wisdom\":14,\"charisma\":13},\"challengeRating\":\"11\",\"savingThrows\":[\"Dex +2\",\"Con +10\",\"Cha +5\"],\"skills\":[\"Athletics +11\",\"Perception +6\"],\"damageResistances\":[\"necrotic\"],\"damageImmunities\":[\"fire\",\"poison\"],\"conditionImmunities\":[\"exhaustion\",\"petrified\",\"poisoned\"],\"senses\":[\"passive Perception 16\"],\"traits\":[{\"id\":\"bigbys-firegaunt-trait-0\",\"name\":\"Fire Blood\",\"description\":\"Whenever a creature within 5 feet of the firegaunt hits the firegaunt with a melee attack that deals piercing or slashing damage, that creature takes 5 (1d10) fire damage.\"}],\"actions\":[{\"id\":\"bigbys-firegaunt-action-0\",\"name\":\"Multiattack\",\"description\":\"The firegaunt makes two Heated Maul attacks.\"},{\"id\":\"bigbys-firegaunt-action-1\",\"name\":\"Heated Maul\",\"description\":\"mw 11 to hit, reach 10 ft., one target. {@h}23 (3d10 + 7) bludgeoning damage. The firegaunt can cause the maul to erupt with crimson flames, and the target must succeed on a 18 Dexterity saving throw or take 10 (3d6) fire damage and 10 (3d6) necrotic damage. The maul can erupt with flames in this way only once per turn.\"},{\"id\":\"bigbys-firegaunt-action-2\",\"name\":\"Crimson Rays 5\",\"description\":\"The firegaunt emits beams of fire from its eyes, mouth, and wounds in a 30-foot cone. Each creature in that area must make a 18 Dexterity saving throw, taking 31 (7d8) fire damage on a failed save, or half as much damage on a successful one. On a success or failure, that creature catches fire. Until the burning creature or another creature that can reach it takes an action to extinguish the fire, the burning creature can't regain hit points and takes 5 (1d10) fire damage at the start of each of its turns.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Giant\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-flesh-colossus\",\"name\":\"Flesh Colossus\",\"description\":\"Flesh Colossus from Bigby Presents: Glory of the Giants.\",\"size\":\"Gargantuan\",\"type\":\"construct\",\"alignment\":\"U\",\"ac\":14,\"hp\":{\"average\":280,\"formula\":\"16d20 + 112\"},\"speed\":\"60 ft.\",\"abilityScores\":{\"strength\":24,\"dexterity\":9,\"constitution\":24,\"intelligence\":6,\"wisdom\":10,\"charisma\":5},\"challengeRating\":\"20\",\"damageImmunities\":[\"lightning\",\"poison\",\"psychic\",\"bludgeoning\",\"piercing\",\"slashing\",\"from nonmagical attacks\"],\"conditionImmunities\":[\"charmed\",\"exhaustion\",\"frightened\",\"paralyzed\",\"petrified\",\"poisoned\"],\"senses\":[\"darkvision 120 ft., passive Perception 10\"],\"traits\":[{\"id\":\"bigbys-flesh-colossus-trait-0\",\"name\":\"Berserk\",\"description\":\"If the core inside the colossus is destroyed, the colossus goes berserk. On each of its turns while berserk, the colossus attacks the nearest creature it can see. If no creature is near enough to move to and attack, the colossus attacks an object. Once the colossus goes berserk, it remains berserk until it is destroyed.\"},{\"id\":\"bigbys-flesh-colossus-trait-1\",\"name\":\"Immutable Form\",\"description\":\"The colossus is immune to any spell or effect that would alter its form.\"},{\"id\":\"bigbys-flesh-colossus-trait-2\",\"name\":\"Magic Resistance\",\"description\":\"The colossus has advantage on saving throws against spells and other magical effects.\"},{\"id\":\"bigbys-flesh-colossus-trait-3\",\"name\":\"Siege Monster\",\"description\":\"The colossus deals double damage to objects and structures.\"}],\"actions\":[{\"id\":\"bigbys-flesh-colossus-action-0\",\"name\":\"Multiattack\",\"description\":\"The colossus makes two Fist attacks.\"},{\"id\":\"bigbys-flesh-colossus-action-1\",\"name\":\"Fist\",\"description\":\"mw 13 to hit (with advantage if the colossus is berserk), reach 20 ft., one target. {@h}17 (3d6 + 7) bludgeoning damage. If the target is a Large or smaller creature, it is pulled up to 15 feet toward the colossus, it has the grappled condition (escape 17), and it has the restrained condition until this grapple ends. The colossus can have up to two creatures grappled this way at a time.\"},{\"id\":\"bigbys-flesh-colossus-action-2\",\"name\":\"Elemental Breath 5\",\"description\":\"The colossus exhales a cloud swirling with elemental energy in a 90-foot cone. Each creature in that area must make a 21 Dexterity saving throw. On a failed save, a creature takes 40 (9d8) damage of a type of the colossus's choosing: acid, cold, fire, or lightning. On a successful save, a creature takes half as much damage. At the same time as the colossus releases this exhalation, creatures inside the colossus's chest cavity take 40 (9d8) force damage from churning elemental energy.\"}],\"bonusActions\":[{\"id\":\"bigbys-flesh-colossus-bonus-0\",\"name\":\"Bite\",\"description\":\"mw 13 to hit, reach 5 ft., one Large or smaller creature grappled by the colossus. {@h}20 (3d8 + 7) bludgeoning damage, and the creature is swallowed. A swallowed creature has the restrained condition, has 3 against attacks and other effects outside the colossus, and takes 10 (3d6) force damage at the start of each of the colossus's turns. The colossus's chest cavity can hold up to two creatures at a time. Inside its chest cavity is its core, which is a Large object with AC 16 that is immune to lightning, poison, and psychic damage. It has 140 hit points and sheds dim light in a 10-foot radius. If the core is destroyed, the colossus regurgitates all swallowed creatures, each of which falls in a space within 10 feet of the colossus and has the prone condition, and the colossus can no longer swallow a creature. If the colossus dies, any swallowed creature no longer has the restrained condition and can escape from the corpse using 10 feet of movement, exiting with the prone condition.\"}],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"understands Giant but can't speak\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-fomorian-deep-crawler\",\"name\":\"Fomorian Deep Crawler\",\"description\":\"Fomorian Deep Crawler from Bigby Presents: Glory of the Giants.\",\"size\":\"Huge\",\"type\":\"giant\",\"alignment\":\"A\",\"ac\":14,\"hp\":{\"average\":184,\"formula\":\"16d12 + 80\"},\"speed\":\"30 ft., climb 30 ft.\",\"abilityScores\":{\"strength\":23,\"dexterity\":15,\"constitution\":20,\"intelligence\":9,\"wisdom\":17,\"charisma\":6},\"challengeRating\":\"10\",\"skills\":[\"Perception +7\",\"Stealth +6\"],\"senses\":[\"darkvision 120 ft., passive Perception 17\"],\"traits\":[{\"id\":\"bigbys-fomorian-deep-crawler-trait-0\",\"name\":\"Contortionist\",\"description\":\"The fomorian can enter a space large enough for a Large creature without squeezing.\"},{\"id\":\"bigbys-fomorian-deep-crawler-trait-1\",\"name\":\"Crawling Stance\",\"description\":\"While the fomorian has the prone condition, crawling does not cost it extra movement. In addition, the prone condition does not grant advantage on attack rolls against the fomorian.\"},{\"id\":\"bigbys-fomorian-deep-crawler-trait-2\",\"name\":\"Spider Climb\",\"description\":\"The fomorian can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check.\"}],\"actions\":[{\"id\":\"bigbys-fomorian-deep-crawler-action-0\",\"name\":\"Multiattack\",\"description\":\"The fomorian makes two Slam attacks and uses Crawling Hex if it is available.\"},{\"id\":\"bigbys-fomorian-deep-crawler-action-1\",\"name\":\"Slam\",\"description\":\"mw 10 to hit, reach 10 ft., one target. {@h}22 (3d10 + 6) bludgeoning damage.\"},{\"id\":\"bigbys-fomorian-deep-crawler-action-2\",\"name\":\"Crawling Hex 4\",\"description\":\"The fomorian targets one creature it can see within 60 feet of itself. The target must succeed on a 15 Wisdom saving throw or take 31 (7d8) psychic damage, have the prone condition, and become cursed for 1 hour. While cursed this way, the target can't stand up and end the prone condition on itself.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Giant\",\"Undercommon\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-fomorian-noble\",\"name\":\"Fomorian Noble\",\"description\":\"Fomorian Noble from Bigby Presents: Glory of the Giants.\",\"size\":\"Huge\",\"type\":\"giant\",\"alignment\":\"C E\",\"ac\":14,\"hp\":{\"average\":253,\"formula\":\"22d12 + 110\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":23,\"dexterity\":18,\"constitution\":20,\"intelligence\":19,\"wisdom\":14,\"charisma\":16},\"challengeRating\":\"15\",\"savingThrows\":[\"Int +9\",\"Wis +7\",\"Cha +8\"],\"skills\":[\"Arcana +14\",\"Perception +7\",\"Stealth +9\"],\"conditionImmunities\":[\"charmed\"],\"senses\":[\"passive Perception 17\"],\"traits\":[],\"actions\":[{\"id\":\"bigbys-fomorian-noble-action-0\",\"name\":\"Multiattack\",\"description\":\"The fomorian makes three Rod attacks.\"},{\"id\":\"bigbys-fomorian-noble-action-1\",\"name\":\"Rod\",\"description\":\"mw 11 to hit, reach 10 ft., one target. {@h}16 (3d6 + 6) bludgeoning damage plus 11 (2d10) force damage.\"}],\"bonusActions\":[{\"id\":\"bigbys-fomorian-noble-bonus-0\",\"name\":\"Beguiling Presence\",\"description\":\"The fomorian targets a creature it can see within 60 feet of itself. The target must succeed on a 17 Wisdom saving throw or have the charmed condition for 1 minute. An affected target can repeat the saving throw at the end of each of its turns and whenever it takes damage, ending the effect on itself on a success. If a target's saving throw is successful or the effect ends for it, the target becomes immune to all fomorians' Beguiling Presence for the next 24 hours.\"}],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Giant plus any three languages\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-fomorian-warlock-of-the-dark\",\"name\":\"Fomorian Warlock of the Dark\",\"description\":\"Fomorian Warlock of the Dark from Bigby Presents: Glory of the Giants.\",\"size\":\"Huge\",\"type\":\"giant\",\"alignment\":\"A\",\"ac\":15,\"hp\":{\"average\":207,\"formula\":\"18d12 + 90\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":23,\"dexterity\":13,\"constitution\":20,\"intelligence\":9,\"wisdom\":14,\"charisma\":18},\"challengeRating\":\"12\",\"savingThrows\":[\"Wis +6\",\"Cha +8\"],\"skills\":[\"Arcana +3\",\"Perception +6\",\"Stealth +5\"],\"senses\":[\"darkvision 120 ft., passive Perception 16\"],\"traits\":[{\"id\":\"bigbys-fomorian-warlock-of-the-dark-trait-0\",\"name\":\"Blood Rune\",\"description\":\"The fomorian has a blood rune inscribed on an effigy or some other object in its possession. While holding or wearing the object bearing the rune, the giant can use its Corrupting Hex action and Poisoning Rebuke reaction. The object bearing the blood rune has AC 15; 30 hit points; and immunity to necrotic, poison, and psychic damage. The object regains all its hit points at the end of every turn, but it turns to dust if reduced to 0 hit points or when the fomorian dies. If the rune is destroyed, the fomorian can inscribe a blood rune on an object in its possession when it finishes a short or long rest.\"},{\"id\":\"bigbys-fomorian-warlock-of-the-dark-trait-1\",\"name\":\"Devil's Sight\",\"description\":\"Magical darkness doesn't impede the fomorian's darkvision.\"},{\"id\":\"bigbys-fomorian-warlock-of-the-dark-trait-2\",\"name\":\"Legendary Resistance (3/Day)\",\"description\":\"If the fomorian fails a saving throw, it can choose to succeed instead.\"}],\"actions\":[{\"id\":\"bigbys-fomorian-warlock-of-the-dark-action-0\",\"name\":\"Multiattack\",\"description\":\"The fomorian makes three Greatclub attacks. If the fomorian has its blood rune, it can replace one of these attacks with a use of Corrupting Hex.\"},{\"id\":\"bigbys-fomorian-warlock-of-the-dark-action-1\",\"name\":\"Greatclub\",\"description\":\"mw 10 to hit, reach 15 ft., one target. {@h}19 (3d8 + 6) bludgeoning damage plus 7 (2d6) necrotic damage.\"},{\"id\":\"bigbys-fomorian-warlock-of-the-dark-action-2\",\"name\":\"Corrupting Hex (Requires Blood Rune)\",\"description\":\"The fomorian targets one creature it can see within 60 feet of itself. The target must succeed on a 16 Charisma saving throw or take 27 (6d8) necrotic damage and become cursed for 24 hours. While cursed this way, the target's speed is reduced by half, and if it tries to cast a spell, it must first succeed on a 16 Intelligence check or the spell fails and is wasted.\"},{\"id\":\"bigbys-fomorian-warlock-of-the-dark-action-3\",\"name\":\"Eldritch Burst\",\"description\":\"Magical energy explodes in a 20-foot-radius sphere centered on a point the fomorian can see within 120 feet of itself. Each creature in that area must make a 16 Dexterity saving throw. On a failed save, a creature takes 32 (5d12) force damage and has the prone condition. On a successful save, a creature takes half as much damage only.\"}],\"bonusActions\":[{\"id\":\"bigbys-fomorian-warlock-of-the-dark-bonus-0\",\"name\":\"Creeping Gloom {@recharge}\",\"description\":\"The fomorian momentarily conjures grasping darkness in a 30-foot-radius sphere centered on a point it can see within 120 feet of itself. Each creature in that area must succeed on a 16 Constitution saving throw or take 11 (2d10) necrotic damage and have the blinded condition until the end of its next turn.\"}],\"reactions\":[{\"id\":\"bigbys-fomorian-warlock-of-the-dark-reaction-0\",\"name\":\"Poisoning Rebuke (Requires Blood Rune)\",\"description\":\"In response to being damaged by a creature the fomorian can see within 60 feet of itself, the fomorian forces that creature to make a 16 Constitution saving throw; on a failed save, the creature has the poisoned condition until the end of its next turn.\"}],\"legendaryActions\":[],\"languages\":[\"Giant\",\"Undercommon\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-frost-giant-ice-shaper\",\"name\":\"Frost Giant Ice Shaper\",\"description\":\"Frost Giant Ice Shaper from Bigby Presents: Glory of the Giants.\",\"size\":\"Huge\",\"type\":\"giant\",\"alignment\":\"A\",\"ac\":16,\"hp\":{\"average\":310,\"formula\":\"27d12 + 135\"},\"speed\":\"40 ft.\",\"abilityScores\":{\"strength\":23,\"dexterity\":10,\"constitution\":21,\"intelligence\":11,\"wisdom\":19,\"charisma\":16},\"challengeRating\":\"17\",\"savingThrows\":[\"Str +12\",\"Con +11\",\"Wis +10\",\"Cha +9\"],\"skills\":[\"Athletics +12\",\"Perception +10\"],\"damageImmunities\":[\"cold\"],\"senses\":[\"passive Perception 20\"],\"traits\":[{\"id\":\"bigbys-frost-giant-ice-shaper-trait-0\",\"name\":\"Frost Rune\",\"description\":\"The giant has a frost rune inscribed on a chunk of ice or some other object in its possession. While holding or wearing the object bearing the rune, the giant can use its Ice Wolves action and Ice Armor reaction. The object bearing the rune has AC 16; 40 hit points; and immunity to necrotic, poison, and psychic damage. The object regains all its hit points at the end of every turn, but it turns to dust if reduced to 0 hit points or when the giant dies. If the rune is destroyed, the giant can inscribe a frost rune on an object in its possession when it finishes a short or long rest.\"},{\"id\":\"bigbys-frost-giant-ice-shaper-trait-1\",\"name\":\"Legendary Resistance (3/Day)\",\"description\":\"If the giant fails a saving throw, it can choose to succeed instead.\"}],\"actions\":[{\"id\":\"bigbys-frost-giant-ice-shaper-action-0\",\"name\":\"Multiattack\",\"description\":\"The giant makes three attacks using Greataxe, Freezing Ray, or a combination of them.\"},{\"id\":\"bigbys-frost-giant-ice-shaper-action-1\",\"name\":\"Greataxe\",\"description\":\"mw 12 to hit, reach 10 ft., one target. {@h}22 (3d10 + 6) slashing damage plus 9 (2d8) cold damage.\"},{\"id\":\"bigbys-frost-giant-ice-shaper-action-2\",\"name\":\"Freezing Ray\",\"description\":\"rs 10 to hit, range 120 ft., one target. {@h}17 (3d8 + 4) cold damage, and the target must make a 18 Constitution saving throw. On a failed save, the target has the restrained condition until the end of its next turn. On a successful save, the target's speed is reduced by 10 feet until the end of its next turn.\"},{\"id\":\"bigbys-frost-giant-ice-shaper-action-3\",\"name\":\"Ice Wolves (Requires Frost Rune)\",\"description\":\"The giant magically summons 1d4 wolves made of ice (use the winter wolf stat block in the Monster Manual to represent them, but they are Elementals instead of Monstrosities). The wolves appear in unoccupied spaces the giant can see within 30 feet of itself. The wolves take their turn immediately after the giant on the same initiative count, and they obey the giant's commands. The wolves gain a +6 bonus to their attack and damage rolls while they are within 30 feet of the giant. The wolves disappear after 1 minute, when the giant dies, or when the giant uses this action again.\"}],\"bonusActions\":[],\"reactions\":[{\"id\":\"bigbys-frost-giant-ice-shaper-reaction-0\",\"name\":\"Ice Armor (Requires Frost Rune)\",\"description\":\"When a creature the giant can see makes an attack roll against it, the giant can form a coat of ice around itself, granting it a +6 bonus to its AC against that attack. After the attack hits or misses, the ice shatters, and each creature within 5 feet of the giant must succeed on a 18 Dexterity saving throw or take 13 (3d8) cold damage.\"}],\"legendaryActions\":[],\"languages\":[\"Common\",\"Giant\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-frost-giant-of-evil-water\",\"name\":\"Frost Giant of Evil Water\",\"description\":\"Frost Giant of Evil Water from Bigby Presents: Glory of the Giants.\",\"size\":\"Huge\",\"type\":\"giant\",\"alignment\":\"N E\",\"ac\":16,\"hp\":{\"average\":172,\"formula\":\"15d12 + 75\"},\"speed\":\"40 ft., swim 40 ft.\",\"abilityScores\":{\"strength\":23,\"dexterity\":16,\"constitution\":21,\"intelligence\":9,\"wisdom\":14,\"charisma\":12},\"challengeRating\":\"11\",\"savingThrows\":[\"Dex +7\",\"Con +9\",\"Wis +6\"],\"skills\":[\"Athletics +10\",\"Perception +6\"],\"damageImmunities\":[\"cold\"],\"senses\":[\"passive Perception 16\"],\"traits\":[{\"id\":\"bigbys-frost-giant-of-evil-water-trait-0\",\"name\":\"Amphibious\",\"description\":\"The giant can breathe air and water.\"}],\"actions\":[{\"id\":\"bigbys-frost-giant-of-evil-water-action-0\",\"name\":\"Multiattack\",\"description\":\"The giant makes two Battleaxe attacks and one Harpoon attack.\"},{\"id\":\"bigbys-frost-giant-of-evil-water-action-1\",\"name\":\"Battleaxe\",\"description\":\"mw 10 to hit, reach 10 ft., one target. {@h}19 (3d8 + 6) slashing damage, or 22 (3d10 + 6) slashing damage if used with two hands, plus 7 (2d6) cold damage.\"},{\"id\":\"bigbys-frost-giant-of-evil-water-action-2\",\"name\":\"Harpoon\",\"description\":\"rw 7 to hit, range 50/200 ft., one creature. {@h}14 (2d10 + 3) piercing damage, and the target has the grappled condition (escape 16). While the target is grappled this way, its speed isn't reduced, but it can't move farther from the giant. The target takes 5 (1d10) slashing damage if it escapes from the grapple or if it tries and fails. The giant can grapple only one target at a time with its harpoon.\"}],\"bonusActions\":[{\"id\":\"bigbys-frost-giant-of-evil-water-bonus-0\",\"name\":\"Reel In\",\"description\":\"The giant pulls the target grappled by its Harpoon up to 20 feet toward itself.\"}],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Aquan\",\"Common\",\"Giant\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-frostmourn\",\"name\":\"Frostmourn\",\"description\":\"Frostmourn from Bigby Presents: Glory of the Giants.\",\"size\":\"Huge\",\"type\":\"undead\",\"alignment\":\"N E\",\"ac\":13,\"hp\":{\"average\":195,\"formula\":\"17d12 + 85\"},\"speed\":\"40 ft.\",\"abilityScores\":{\"strength\":23,\"dexterity\":9,\"constitution\":21,\"intelligence\":9,\"wisdom\":11,\"charisma\":18},\"challengeRating\":\"10\",\"savingThrows\":[\"Con +9\",\"Wis +4\"],\"skills\":[\"Athletics +10\",\"Perception +4\"],\"damageVulnerabilities\":[\"fire\"],\"damageImmunities\":[\"cold\",\"poison\"],\"conditionImmunities\":[\"charmed\",\"exhaustion\",\"frightened\",\"grappled\",\"paralyzed\",\"petrified\",\"poisoned\",\"prone\",\"restrained\"],\"senses\":[\"passive Perception 14\"],\"traits\":[],\"actions\":[{\"id\":\"bigbys-frostmourn-action-0\",\"name\":\"Multiattack\",\"description\":\"The frostmourn makes one Freezing Touch attack and one Icy Axe attack. It can replace one of these attacks with a Polar Ray attack.\"},{\"id\":\"bigbys-frostmourn-action-1\",\"name\":\"Freezing Touch\",\"description\":\"mw 10 to hit, reach 5 ft., one creature. {@h}18 (4d8) cold damage plus 18 (4d8) necrotic damage. If this damage would reduce the target to 0 hit points, the target drops to 1 hit point instead and has the petrified condition, turning into a frozen statue. If the statue takes bludgeoning damage, it shatters, killing the frozen creature. If the statue would take fire damage, it instead takes no damage and thaws, ending the petrification.\"},{\"id\":\"bigbys-frostmourn-action-2\",\"name\":\"Icy Axe\",\"description\":\"mw 10 to hit, reach 10 ft., one target. {@h}19 (3d8 + 6) slashing damage plus 7 (2d6) cold damage.\"},{\"id\":\"bigbys-frostmourn-action-3\",\"name\":\"Polar Ray\",\"description\":\"rs 8 to hit, range 120 ft., one target. {@h}31 (5d10 + 4) cold damage, and the target's speed is reduced by 10 feet until the end of its next turn.\"}],\"bonusActions\":[],\"reactions\":[{\"id\":\"bigbys-frostmourn-reaction-0\",\"name\":\"Blizzard Escape\",\"description\":\"Immediately after a creature the frostmourn can see hits it with an attack roll, the frostmourn momentarily dissolves into a blizzard, reducing the damage to itself by half. The frostmourn can then magically teleport to an unoccupied space it can see within 30 feet of itself.\"}],\"legendaryActions\":[],\"languages\":[\"Giant\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-fury-of-kostchtchie\",\"name\":\"Fury of Kostchtchie\",\"description\":\"Fury of Kostchtchie from Bigby Presents: Glory of the Giants.\",\"size\":\"Huge\",\"type\":\"fiend\",\"alignment\":\"C E\",\"ac\":16,\"hp\":{\"average\":216,\"formula\":\"16d12 + 112\"},\"speed\":\"40 ft.\",\"abilityScores\":{\"strength\":26,\"dexterity\":10,\"constitution\":25,\"intelligence\":10,\"wisdom\":12,\"charisma\":11},\"challengeRating\":\"14\",\"savingThrows\":[\"Con +12\",\"Wis +6\"],\"skills\":[\"Athletics +13\",\"Perception +6\"],\"damageResistances\":[\"fire\",\"lightning\",\"poison\"],\"damageImmunities\":[\"cold\"],\"conditionImmunities\":[\"charmed\",\"frightened\",\"poisoned\"],\"senses\":[\"darkvision 120 ft., passive Perception 16\"],\"traits\":[{\"id\":\"bigbys-fury-of-kostchtchie-trait-0\",\"name\":\"Chilling Aura\",\"description\":\"A creature that starts its turn within 10 feet of the fury must succeed on a 20 Constitution saving throw or take 11 (2d10) cold damage.\"},{\"id\":\"bigbys-fury-of-kostchtchie-trait-1\",\"name\":\"Magic Resistance\",\"description\":\"The fury has advantage on saving throws against spells and other magical effects.\"}],\"actions\":[{\"id\":\"bigbys-fury-of-kostchtchie-action-0\",\"name\":\"Multiattack\",\"description\":\"The fury makes two Fist or Rock attacks.\"},{\"id\":\"bigbys-fury-of-kostchtchie-action-1\",\"name\":\"Fist\",\"description\":\"mw 13 to hit, reach 10 ft., one target. {@h}17 (2d8 + 8) bludgeoning damage plus 10 (3d6) cold damage, or 17 (5d6) cold damage if the target took damage from the fury's Chilling Aura since the end of the fury's last turn.\"},{\"id\":\"bigbys-fury-of-kostchtchie-action-2\",\"name\":\"Rock\",\"description\":\"rw 13 to hit, range 60/240 ft., one target. {@h}30 (4d10 + 8) bludgeoning damage.\"}],\"bonusActions\":[{\"id\":\"bigbys-fury-of-kostchtchie-bonus-0\",\"name\":\"Charge\",\"description\":\"The fury can move up to its speed toward an enemy it can see.\"}],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Abyssal\",\"Giant\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-gargantua\",\"name\":\"Gargantua\",\"description\":\"Gargantua from Bigby Presents: Glory of the Giants.\",\"size\":\"Gargantuan\",\"type\":\"aberration\",\"alignment\":\"C N\",\"ac\":17,\"hp\":{\"average\":388,\"formula\":\"21d20 + 168\"},\"speed\":\"60 ft.\",\"abilityScores\":{\"strength\":27,\"dexterity\":10,\"constitution\":26,\"intelligence\":9,\"wisdom\":16,\"charisma\":18},\"challengeRating\":\"21\",\"savingThrows\":[\"Dex +7\",\"Int +6\",\"Wis +10\"],\"damageResistances\":[\"force\",\"psychic\"],\"conditionImmunities\":[\"frightened\"],\"senses\":[\"darkvision 120 ft., passive Perception 13\"],\"traits\":[{\"id\":\"bigbys-gargantua-trait-0\",\"name\":\"Weird Aura\",\"description\":\"At the start of each of the gargantua's turns, each creature of the gargantua's choice within 30 feet of it must make a 19 Wisdom saving throw. On a failed save, a target sees the gargantua as a manifestation of the target's worst fears; it takes 17 (5d6) psychic damage and has the frightened condition until the start of the target's next turn. On a successful save, a target is immune to this gargantua's Weird Aura for 24 hours.\"}],\"actions\":[{\"id\":\"bigbys-gargantua-action-0\",\"name\":\"Multiattack\",\"description\":\"The gargantua makes two Slam or Rock attacks.\"},{\"id\":\"bigbys-gargantua-action-1\",\"name\":\"Slam\",\"description\":\"mw 15 to hit, reach 20 ft., one target. {@h}27 (3d12 + 8) bludgeoning damage.\"},{\"id\":\"bigbys-gargantua-action-2\",\"name\":\"Rock\",\"description\":\"rw 15 to hit, range 120/480 ft., one target. {@h}24 (3d10 + 8) bludgeoning damage.\"}],\"bonusActions\":[{\"id\":\"bigbys-gargantua-bonus-0\",\"name\":\"Baleful Hex\",\"description\":\"The gargantua curses one creature it can see within 120 feet of itself. The target must succeed on a 19 Wisdom saving throw or have the incapacitated condition until the end of its next turn.\"},{\"id\":\"bigbys-gargantua-bonus-1\",\"name\":\"Teleport\",\"description\":\"The gargantua teleports, along with any equipment it is wearing or carrying, to an unoccupied space that it can see within 120 feet of itself.\"}],\"reactions\":[{\"id\":\"bigbys-gargantua-reaction-0\",\"name\":\"Flick\",\"description\":\"Immediately after the gargantua takes damage from a Large or smaller creature it can see within 20 feet of itself, it attempts to flick the creature away. The target must succeed on a 23 Strength saving throw, or the target takes 18 (3d6 + 8) bludgeoning damage, is pushed horizontally up to 100 feet away from the gargantua, and has the prone condition.\"},{\"id\":\"bigbys-gargantua-reaction-1\",\"name\":\"Spell Mimicry (1/Day)\",\"description\":\"Immediately after a creature the gargantua can see casts a spell of 5th level or lower, the gargantua tries to copy the spell. That creature must succeed on a 19 Charisma saving throw, or the gargantua immediately casts the same spell at the same level (11 to hit with spell attacks, spell save 19), requiring no material components and choosing the spell's targets.\"}],\"legendaryActions\":[],\"languages\":[\"Giant\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-giant-child\",\"name\":\"Giant Child\",\"description\":\"Giant Child from Bigby Presents: Glory of the Giants.\",\"size\":\"Medium\",\"type\":\"giant\",\"alignment\":\"A\",\"ac\":10,\"hp\":{\"average\":4,\"formula\":\"1d8\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":14,\"dexterity\":10,\"constitution\":10,\"intelligence\":10,\"wisdom\":10,\"charisma\":10},\"challengeRating\":\"0\",\"senses\":[\"passive Perception 10\"],\"traits\":[],\"actions\":[{\"id\":\"bigbys-giant-child-action-0\",\"name\":\"Club\",\"description\":\"mw 4 to hit, reach 5 ft., one target. {@h}4 (1d4 + 2) bludgeoning damage.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Giant\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-giant-goose\",\"name\":\"Giant Goose\",\"description\":\"Giant Goose from Bigby Presents: Glory of the Giants.\",\"size\":\"Large\",\"type\":\"fey\",\"alignment\":\"N\",\"ac\":13,\"hp\":{\"average\":60,\"formula\":\"8d10 + 16\"},\"speed\":\"30 ft., fly 30 ft.\",\"abilityScores\":{\"strength\":14,\"dexterity\":16,\"constitution\":15,\"intelligence\":6,\"wisdom\":14,\"charisma\":11},\"challengeRating\":\"3\",\"skills\":[\"Perception +6\"],\"senses\":[\"darkvision 60 ft., passive Perception 16\"],\"traits\":[],\"actions\":[{\"id\":\"bigbys-giant-goose-action-0\",\"name\":\"Multiattack\",\"description\":\"The goose makes one Beak attack and two Wing attacks.\"},{\"id\":\"bigbys-giant-goose-action-1\",\"name\":\"Beak\",\"description\":\"mw 4 to hit, reach 10 ft., one target. {@h}9 (2d6 + 2) bludgeoning damage.\"},{\"id\":\"bigbys-giant-goose-action-2\",\"name\":\"Wing\",\"description\":\"mw 4 to hit, reach 5 ft., one target. {@h}7 (1d10 + 2) bludgeoning damage, and the target must succeed on a 12 Strength saving throw or have the prone condition.\"},{\"id\":\"bigbys-giant-goose-action-3\",\"name\":\"Thunderous Honk 5\",\"description\":\"The goose honks with ear-splitting volume. Each other creature within 30 feet of the goose must make a 12 Constitution saving throw. On a failed save, a creature takes 16 (3d10) thunder damage and has the deafened condition until the start of the goose's next turn. On a successful save, a creature takes half as much damage only. The honk can be heard within 300 feet.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"understands Giant and Sylvan but can't speak\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-giant-lynx\",\"name\":\"Giant Lynx\",\"description\":\"Giant Lynx from Bigby Presents: Glory of the Giants.\",\"size\":\"Medium\",\"type\":\"fey\",\"alignment\":\"N\",\"ac\":14,\"hp\":{\"average\":22,\"formula\":\"4d8 + 4\"},\"speed\":\"30 ft., climb 30 ft.\",\"abilityScores\":{\"strength\":14,\"dexterity\":18,\"constitution\":13,\"intelligence\":12,\"wisdom\":14,\"charisma\":10},\"challengeRating\":\"1/2\",\"skills\":[\"Perception +6\",\"Stealth +6\"],\"damageResistances\":[\"cold\"],\"senses\":[\"truesight 60 ft., passive Perception 16\"],\"traits\":[{\"id\":\"bigbys-giant-lynx-trait-0\",\"name\":\"Lynx's Sight (1/Day)\",\"description\":\"The lynx can cast clairvoyance, requiring no spell components and using Wisdom as the spellcasting ability.\"},{\"id\":\"bigbys-giant-lynx-trait-1\",\"name\":\"Woodland Camouflage\",\"description\":\"The lynx has advantage on Dexterity (Stealth) checks made to hide in undergrowth or snowy terrain.\"}],\"actions\":[{\"id\":\"bigbys-giant-lynx-action-0\",\"name\":\"Claws\",\"description\":\"mw 6 to hit, reach 5 ft., one target. {@h}8 (1d8 + 4) slashing damage. If the lynx moved at least 20 feet straight toward the target immediately before the hit, the target must succeed on a 12 Strength saving throw or have the prone condition. If the target has the prone condition, the lynx can make another Claws attack against it as a bonus action.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Giant\",\"Sylvan\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-giant-ox\",\"name\":\"Giant Ox\",\"description\":\"Giant Ox from Bigby Presents: Glory of the Giants.\",\"size\":\"Huge\",\"type\":\"fey\",\"alignment\":\"U\",\"ac\":12,\"hp\":{\"average\":105,\"formula\":\"10d12 + 40\"},\"speed\":\"40 ft.\",\"abilityScores\":{\"strength\":22,\"dexterity\":10,\"constitution\":19,\"intelligence\":4,\"wisdom\":11,\"charisma\":9},\"challengeRating\":\"3\",\"senses\":[\"passive Perception 10\"],\"traits\":[{\"id\":\"bigbys-giant-ox-trait-0\",\"name\":\"Beast of Burden\",\"description\":\"The ox is considered to be one size larger for the purpose of determining its carrying capacity.\"}],\"actions\":[{\"id\":\"bigbys-giant-ox-action-0\",\"name\":\"Gore\",\"description\":\"mw 8 to hit, reach 10 ft., one target. {@h}13 (2d6 + 6) piercing damage. If the ox moved at least 20 feet straight toward the target immediately before the hit, the target takes an extra 7 (2d6) piercing damage, and it must succeed on a 16 Strength saving throw or have the prone condition.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"understands Giant and Sylvan but can't speak\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-giant-ram\",\"name\":\"Giant Ram\",\"description\":\"Giant Ram from Bigby Presents: Glory of the Giants.\",\"size\":\"Large\",\"type\":\"fey\",\"alignment\":\"U\",\"ac\":13,\"hp\":{\"average\":28,\"formula\":\"3d10 + 12\"},\"speed\":\"50 ft.\",\"abilityScores\":{\"strength\":19,\"dexterity\":12,\"constitution\":18,\"intelligence\":3,\"wisdom\":14,\"charisma\":10},\"challengeRating\":\"1\",\"damageResistances\":[\"cold\",\"fire\",\"lightning\"],\"senses\":[\"passive Perception 12\"],\"traits\":[{\"id\":\"bigbys-giant-ram-trait-0\",\"name\":\"Magic Resistance\",\"description\":\"The ram has advantage on saving throws against spells and other magical effects.\"}],\"actions\":[{\"id\":\"bigbys-giant-ram-action-0\",\"name\":\"Ram\",\"description\":\"mw 6 to hit, reach 5 ft., one target. {@h}9 (2d4 + 4) bludgeoning damage plus 3 (1d6) force damage. If the ram moved at least 20 feet straight toward the target immediately before the hit, the target must succeed on a 14 Strength saving throw or have the prone condition.\"},{\"id\":\"bigbys-giant-ram-action-1\",\"name\":\"Force Bolt\",\"description\":\"rs 4 to hit, range 30 ft., one target. {@h}7 (2d6) force damage.\"}],\"bonusActions\":[],\"reactions\":[{\"id\":\"bigbys-giant-ram-reaction-0\",\"name\":\"Absorbent Fleece {@recharge}\",\"description\":\"Immediately after the ram succeeds on a saving throw against a spell or a spell's attack misses it, the ram can make one Force Bolt attack.\"}],\"legendaryActions\":[],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-giant-tick\",\"name\":\"Giant Tick\",\"description\":\"Giant Tick from Bigby Presents: Glory of the Giants.\",\"size\":\"Medium\",\"type\":\"monstrosity\",\"alignment\":\"U\",\"ac\":14,\"hp\":{\"average\":52,\"formula\":\"7d8 + 21\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":16,\"dexterity\":10,\"constitution\":16,\"intelligence\":2,\"wisdom\":10,\"charisma\":2},\"challengeRating\":\"2\",\"senses\":[\"passive Perception 10\"],\"traits\":[],\"actions\":[{\"id\":\"bigbys-giant-tick-action-0\",\"name\":\"Proboscis\",\"description\":\"mw 5 to hit, reach 5 ft., one creature. {@h}10 (2d6 + 3) piercing damage, and the tick attaches to the target. While attached, the tick can't make Proboscis attacks. The tick can detach itself by spending 5 feet of its movement. As an action, a creature within reach of the tick can try to detach the tick, doing so with a successful 13 Strength check.\"},{\"id\":\"bigbys-giant-tick-action-1\",\"name\":\"Blood Drain\",\"description\":\"The tick deals 10 (2d6 + 3) necrotic damage to one creature it is physically attached to, provided that creature isn't a Construct or an Undead, or 17 (4d6 + 3) necrotic damage if the creature is a Giant. The tick regains hit points equal to the damage dealt.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-gigant\",\"name\":\"Gigant\",\"description\":\"Gigant from Bigby Presents: Glory of the Giants.\",\"size\":\"Gargantuan\",\"type\":\"monstrosity\",\"alignment\":\"U\",\"ac\":17,\"hp\":{\"average\":325,\"formula\":\"21d20 + 105\"},\"speed\":\"50 ft., burrow 50 ft., fly 80 ft.\",\"abilityScores\":{\"strength\":24,\"dexterity\":14,\"constitution\":21,\"intelligence\":3,\"wisdom\":14,\"charisma\":11},\"challengeRating\":\"20\",\"savingThrows\":[\"Dex +8\",\"Wis +8\"],\"skills\":[\"Perception +8\"],\"senses\":[\"darkvision 120 ft., passive Perception 18\"],\"traits\":[{\"id\":\"bigbys-gigant-trait-0\",\"name\":\"Spell-Resistant Carapace\",\"description\":\"The gigant has advantage on saving throws against spells, and any creature that makes a spell attack against the gigant has disadvantage on the attack roll.\"}],\"actions\":[{\"id\":\"bigbys-gigant-action-0\",\"name\":\"Multiattack\",\"description\":\"The gigant makes one Mandibles attack and two Talons attacks.\"},{\"id\":\"bigbys-gigant-action-1\",\"name\":\"Mandibles\",\"description\":\"mw 13 to hit, reach 10 ft., one creature. {@h}21 (4d6 + 7) slashing damage, and the target has the grappled condition (escape 17). Until the grapple ends, the target takes 21 (4d6 + 7) slashing damage at the start of each of the gigant's turns. While the gigant is grappling a target, it can't use Mandibles against other targets.\"},{\"id\":\"bigbys-gigant-action-2\",\"name\":\"Talons\",\"description\":\"mw 13 to hit, reach 20 ft., one target. {@h}17 (3d6 + 7) slashing damage, and the target is pulled 10 feet straight toward the gigant.\"},{\"id\":\"bigbys-gigant-action-3\",\"name\":\"Scale Dust 5\",\"description\":\"The gigant releases magical dust from its wings in a 30-foot cube. Each creature in that area must make a 19 Constitution saving throw, taking 45 (10d8) poison damage on a failed save, or half as much damage on a successful one. On a success or failure, the creature has the poisoned condition for 1 hour. While poisoned this way, the creature can't regain hit points.\"}],\"bonusActions\":[{\"id\":\"bigbys-gigant-bonus-0\",\"name\":\"Drone\",\"description\":\"The gigant produces a horrid droning sound by rapidly beating its wings. Each creature within 10 feet of the gigant must succeed on a 19 Constitution saving throw or take 10 (3d6) thunder damage and have the incapacitated condition until the end of its next turn. The gigant can then fly up to half its flying speed.\"}],\"reactions\":[],\"legendaryActions\":[],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-goliath-giant-kin\",\"name\":\"Goliath Giant-Kin\",\"description\":\"Goliath Giant-Kin from Bigby Presents: Glory of the Giants.\",\"size\":\"Medium\",\"type\":\"humanoid\",\"alignment\":\"A\",\"ac\":18,\"hp\":{\"average\":67,\"formula\":\"9d8 + 27\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":18,\"dexterity\":13,\"constitution\":16,\"intelligence\":10,\"wisdom\":12,\"charisma\":12},\"challengeRating\":\"3\",\"skills\":[\"Athletics +6\",\"Perception +3\",\"Survival +3\"],\"damageResistances\":[\"cold\"],\"senses\":[\"passive Perception 13\"],\"traits\":[],\"actions\":[{\"id\":\"bigbys-goliath-giant-kin-action-0\",\"name\":\"Multiattack\",\"description\":\"The goliath makes two Spear attacks.\"},{\"id\":\"bigbys-goliath-giant-kin-action-1\",\"name\":\"Spear\",\"description\":\"mw,rw 6 to hit, reach 5 ft. or range 20/60 ft., one target. {@h}7 (1d6 + 4) piercing damage, or 8 (1d8 + 4) piercing damage if used with two hands to make a melee attack.\"}],\"bonusActions\":[{\"id\":\"bigbys-goliath-giant-kin-bonus-0\",\"name\":\"Giant's Strikes 5\",\"description\":\"Until the end of its turn, the goliath's melee attacks each deal an extra 7 (2d6) damage of a type determined by the goliath's giant community: cold (frost giant), fire (fire giant), force (stone giant), lightning (storm giant), piercing (hill giant), or thunder (cloud giant).\"}],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Common\",\"Giant\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-grinning-cat\",\"name\":\"Grinning Cat\",\"description\":\"Grinning Cat from Bigby Presents: Glory of the Giants.\",\"size\":\"Large\",\"type\":\"fey\",\"alignment\":\"C N\",\"ac\":12,\"hp\":{\"average\":45,\"formula\":\"7d10 + 7\"},\"speed\":\"40 ft., climb 40 ft.\",\"abilityScores\":{\"strength\":14,\"dexterity\":15,\"constitution\":13,\"intelligence\":15,\"wisdom\":14,\"charisma\":16},\"challengeRating\":\"1\",\"skills\":[\"Perception +4\",\"Stealth +6\"],\"senses\":[\"darkvision 60 ft., passive Perception 14\"],\"traits\":[{\"id\":\"bigbys-grinning-cat-trait-0\",\"name\":\"Magic Resistance\",\"description\":\"The grinning cat has advantage on saving throws against spells and other magical effects.\"}],\"actions\":[{\"id\":\"bigbys-grinning-cat-action-0\",\"name\":\"Bite\",\"description\":\"mw 4 to hit, reach 5 ft., one target. {@h}7 (1d10 + 2) piercing damage.\"},{\"id\":\"bigbys-grinning-cat-action-1\",\"name\":\"Claws\",\"description\":\"mw 4 to hit, reach 5 ft., one target. {@h}9 (2d6 + 2) slashing damage. If the grinning cat was invisible before it attacked, the target must succeed on a 12 Strength saving throw or have the prone condition. If the target has the prone condition, the cat can make a Bite attack against it as a bonus action.\"},{\"id\":\"bigbys-grinning-cat-action-2\",\"name\":\"Fade Away\",\"description\":\"The grinning cat magically becomes invisible for 1 hour or until it attacks, gradually fading away over the course of its turn. It can choose to leave part of its body visible, such as its tail, its head, or its grinning mouth. Any equipment the cat wears or carries is invisible with it.\"}],\"bonusActions\":[{\"id\":\"bigbys-grinning-cat-bonus-0\",\"name\":\"Fade Back\",\"description\":\"The grinning cat becomes visible or makes part of its body visible. Any equipment the cat wears or carries on a visible part of its body also becomes visible.\"},{\"id\":\"bigbys-grinning-cat-bonus-1\",\"name\":\"Grinning Step\",\"description\":\"The grinning cat teleports, along with any equipment it is wearing or carrying, up to 60 feet to an unoccupied space it can see.\"}],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Common\",\"Sylvan\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-hill-giant-avalancher\",\"name\":\"Hill Giant Avalancher\",\"description\":\"Hill Giant Avalancher from Bigby Presents: Glory of the Giants.\",\"size\":\"Huge\",\"type\":\"giant\",\"alignment\":\"A\",\"ac\":15,\"hp\":{\"average\":220,\"formula\":\"21d12 + 84\"},\"speed\":\"40 ft.\",\"abilityScores\":{\"strength\":21,\"dexterity\":8,\"constitution\":19,\"intelligence\":9,\"wisdom\":18,\"charisma\":10},\"challengeRating\":\"12\",\"savingThrows\":[\"Str +9\",\"Con +8\",\"Wis +8\"],\"skills\":[\"Nature +7\",\"Perception +8\"],\"senses\":[\"passive Perception 18\"],\"traits\":[{\"id\":\"bigbys-hill-giant-avalancher-trait-0\",\"name\":\"Hill Rune\",\"description\":\"The giant has a hill rune inscribed on a rock or some other object in its possession. While holding or wearing the object bearing the rune, the giant can use its Stone Avalanche action and Hill Rebuff reaction. The object bearing the rune has AC 15; 20 hit points; and immunity to necrotic, poison, and psychic damage. The object regains all its hit points at the end of every turn, but it turns to dust if reduced to 0 hit points or when the giant dies. If the rune is destroyed, the giant can inscribe a hill rune on an object in its possession when it finishes a short or long rest.\"},{\"id\":\"bigbys-hill-giant-avalancher-trait-1\",\"name\":\"Legendary Resistance (3/Day)\",\"description\":\"If the giant fails a saving throw, it can choose to succeed instead.\"}],\"actions\":[{\"id\":\"bigbys-hill-giant-avalancher-action-0\",\"name\":\"Multiattack\",\"description\":\"The giant makes one Greatclub attack and uses Stone Bolas.\"},{\"id\":\"bigbys-hill-giant-avalancher-action-1\",\"name\":\"Greatclub\",\"description\":\"mw 9 to hit, reach 10 ft., one target. {@h}18 (3d8 + 5) bludgeoning damage plus 9 (2d8) thunder damage.\"},{\"id\":\"bigbys-hill-giant-avalancher-action-2\",\"name\":\"Stone Bolas\",\"description\":\"The giant conjures three stone balls connected by lines of magical force and throws them at one creature it can see within 60 feet of itself. The target must make a 16 Dexterity saving throw. On a failed save, the target has the restrained condition until the start of the giant's next turn, and the stones erupt in a burst of thunderous energy that deals 14 (4d6) thunder damage to the target and each creature within 10 feet of the target. On a successful save, the stones vanish without erupting.\"},{\"id\":\"bigbys-hill-giant-avalancher-action-3\",\"name\":\"Stone Avalanche (Requires Hill Rune)\",\"description\":\"The giant conjures a hail of rocks in a 20-foot-radius, 40-foot-high cylinder centered on a point on the ground it can see within 120 feet of itself. Each creature in that area must make a 16 Dexterity saving throw. On a failed save, a creature takes 28 (8d6) bludgeoning damage and has the prone condition. On a successful save, a creature takes half as much damage only. The rocks turn the ground in that area into difficult terrain until the start of the giant's next turn, when the rocks vanish.\"}],\"bonusActions\":[],\"reactions\":[{\"id\":\"bigbys-hill-giant-avalancher-reaction-0\",\"name\":\"Hill Rebuff (Requires Hill Rune)\",\"description\":\"Immediately after the giant takes damage from a creature it can see within 10 feet of itself, that creature must succeed on a 16 Constitution saving throw or take 10 (3d6) force damage and be pushed horizontally 10 feet away from the giant.\"}],\"legendaryActions\":[],\"languages\":[\"Common\",\"Giant\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-lightning-hulk\",\"name\":\"Lightning Hulk\",\"description\":\"Lightning Hulk from Bigby Presents: Glory of the Giants.\",\"size\":\"Large\",\"type\":\"elemental\",\"alignment\":\"C N\",\"ac\":15,\"hp\":{\"average\":102,\"formula\":\"12d10 + 36\"},\"speed\":\"0 ft., fly 90 ft.\",\"abilityScores\":{\"strength\":18,\"dexterity\":21,\"constitution\":16,\"intelligence\":14,\"wisdom\":14,\"charisma\":15},\"challengeRating\":\"9\",\"savingThrows\":[\"Dex +9\",\"Con +7\",\"Wis +6\",\"Cha +6\"],\"skills\":[\"Perception +6\"],\"damageResistances\":[\"cold\",\"thunder\",\"bludgeoning\",\"piercing\",\"slashing\",\"from nonmagical attacks\"],\"damageImmunities\":[\"lightning\",\"poison\"],\"conditionImmunities\":[\"exhaustion\",\"grappled\",\"paralyzed\",\"petrified\",\"poisoned\",\"prone\",\"restrained\"],\"senses\":[\"passive Perception 16\"],\"traits\":[{\"id\":\"bigbys-lightning-hulk-trait-0\",\"name\":\"Illumination\",\"description\":\"The lightning hulk sheds bright light in a 20-foot radius and dim light for an additional 20 feet.\"},{\"id\":\"bigbys-lightning-hulk-trait-1\",\"name\":\"Lightning Form\",\"description\":\"The lightning hulk can enter a hostile creature's space and stop there. The first time the lightning hulk enters a creature's space on a turn, or if it begins its turn in a creature's space, that creature takes 7 (2d6) lightning damage. The hulk can also move through a space as narrow as 1 inch without squeezing. A creature that touches the lightning hulk or hits it with a melee attack while within 5 feet of it takes 7 (2d6) lightning damage.\"}],\"actions\":[{\"id\":\"bigbys-lightning-hulk-action-0\",\"name\":\"Arc Lightning\",\"description\":\"mw,rw 9 to hit, reach 10 ft. or range 60 ft., one target. {@h}18 (4d8) lightning damage. If the target is a creature, it can't take reactions until the start of its next turn, and lightning jumps from the target to another creature of the lightning hulk's choice that it can see within 30 feet of the target. The second creature must succeed on a 18 Dexterity saving throw or take 18 (4d8) lightning damage.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Auran\",\"Giant\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-maw-of-yeenoghu\",\"name\":\"Maw of Yeenoghu\",\"description\":\"Maw of Yeenoghu from Bigby Presents: Glory of the Giants.\",\"size\":\"Huge\",\"type\":\"fiend\",\"alignment\":\"C E\",\"ac\":15,\"hp\":{\"average\":161,\"formula\":\"14d12 + 70\"},\"speed\":\"40 ft.\",\"abilityScores\":{\"strength\":23,\"dexterity\":10,\"constitution\":21,\"intelligence\":8,\"wisdom\":14,\"charisma\":10},\"challengeRating\":\"10\",\"savingThrows\":[\"Con +9\",\"Cha +4\"],\"skills\":[\"Perception +6\"],\"senses\":[\"darkvision 60 ft., passive Perception 16\"],\"traits\":[{\"id\":\"bigbys-maw-of-yeenoghu-trait-0\",\"name\":\"Magic Resistance\",\"description\":\"The maw has advantage on saving throws against spells and other magical effects.\"}],\"actions\":[{\"id\":\"bigbys-maw-of-yeenoghu-action-0\",\"name\":\"Multiattack\",\"description\":\"The maw makes two Bite or Fang Fling attacks.\"},{\"id\":\"bigbys-maw-of-yeenoghu-action-1\",\"name\":\"Bite\",\"description\":\"mw 10 to hit, reach 10 ft., one target. {@h}19 (2d12 + 6) piercing damage.\"},{\"id\":\"bigbys-maw-of-yeenoghu-action-2\",\"name\":\"Fang Fling\",\"description\":\"rw 10 to hit, range 30/90 ft., one target. {@h}11 (1d10 + 6) piercing damage.\"},{\"id\":\"bigbys-maw-of-yeenoghu-action-3\",\"name\":\"Gorging Charge 5\",\"description\":\"The maw moves up to its speed without provoking opportunity attacks and can move through the spaces of Large or smaller creatures. Each time the maw enters a creature's space for the first time during this move, that creature must succeed on a 18 Strength saving throw or take 25 (3d12 + 6) piercing damage and have the grappled condition (escape 16); if a creature is already grappled this way, it has the prone condition. Until this grapple ends, the target has the restrained condition. The maw can have only one creature grappled in this way at a time.\"}],\"bonusActions\":[],\"reactions\":[{\"id\":\"bigbys-maw-of-yeenoghu-reaction-0\",\"name\":\"Fanged Rebuke\",\"description\":\"In response to taking damage, the maw makes one Bite attack against a random creature within 10 feet of itself. If no creature is within reach, the maw can make two Fang Fling attacks.\"}],\"legendaryActions\":[],\"languages\":[\"Abyssal\",\"Giant\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-mist-hulk\",\"name\":\"Mist Hulk\",\"description\":\"Mist Hulk from Bigby Presents: Glory of the Giants.\",\"size\":\"Large\",\"type\":\"elemental\",\"alignment\":\"C N\",\"ac\":15,\"hp\":{\"average\":94,\"formula\":\"9d10 + 45\"},\"speed\":\"0 ft., fly 40 ft.\",\"abilityScores\":{\"strength\":18,\"dexterity\":21,\"constitution\":20,\"intelligence\":11,\"wisdom\":13,\"charisma\":16},\"challengeRating\":\"6\",\"savingThrows\":[\"Con +8\",\"Wis +4\",\"Cha +6\"],\"skills\":[\"Perception +4\",\"Stealth +8\"],\"damageResistances\":[\"thunder\"],\"damageImmunities\":[\"poison\"],\"conditionImmunities\":[\"exhaustion\",\"paralyzed\",\"poisoned\",\"restrained\"],\"senses\":[\"passive Perception 14\"],\"traits\":[{\"id\":\"bigbys-mist-hulk-trait-0\",\"name\":\"Air Form\",\"description\":\"The mist hulk can enter another creature's space and stop there. It can move through a space as narrow as 1 inch without squeezing.\"},{\"id\":\"bigbys-mist-hulk-trait-1\",\"name\":\"Death Burst\",\"description\":\"When the mist hulk dies, it bursts in a wave of water. Each creature within 10 feet of it must make a 16 Dexterity saving throw. On a failed save, a creature takes 11 (2d10) bludgeoning damage and has the prone condition. On a successful save, a creature takes half as much damage only.\"}],\"actions\":[{\"id\":\"bigbys-mist-hulk-action-0\",\"name\":\"Multiattack\",\"description\":\"The mist hulk makes two Slam attacks.\"},{\"id\":\"bigbys-mist-hulk-action-1\",\"name\":\"Slam\",\"description\":\"mw 8 to hit, reach 10 ft., one target. {@h}16 (2d10 + 5) cold damage.\"},{\"id\":\"bigbys-mist-hulk-action-2\",\"name\":\"Hideous Wailing 5\",\"description\":\"The mist hulk releases a wail infused with magical anguish. Each creature within 30 feet of it must make a 14 Wisdom saving throw. A creature in the mist hulk's space has disadvantage on the saving throw. On a failed save, a creature takes 14 (4d6) psychic damage and has the incapacitated condition for 1 minute. The affected creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Auran\",\"Giant\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-mud-hulk\",\"name\":\"Mud Hulk\",\"description\":\"Mud Hulk from Bigby Presents: Glory of the Giants.\",\"size\":\"Large\",\"type\":\"elemental\",\"alignment\":\"C E\",\"ac\":13,\"hp\":{\"average\":68,\"formula\":\"8d10 + 24\"},\"speed\":\"40 ft.\",\"abilityScores\":{\"strength\":16,\"dexterity\":8,\"constitution\":16,\"intelligence\":5,\"wisdom\":9,\"charisma\":6},\"challengeRating\":\"3\",\"damageResistances\":[\"acid\"],\"conditionImmunities\":[\"exhaustion\",\"paralyzed\"],\"senses\":[\"passive Perception 9\"],\"traits\":[{\"id\":\"bigbys-mud-hulk-trait-0\",\"name\":\"Amorphous\",\"description\":\"The mud hulk can move through a space as narrow as 1 inch without squeezing.\"},{\"id\":\"bigbys-mud-hulk-trait-1\",\"name\":\"Sticky Mud\",\"description\":\"The ground within 15 feet of the mud hulk is difficult terrain for other creatures.\"}],\"actions\":[{\"id\":\"bigbys-mud-hulk-action-0\",\"name\":\"Enveloping Slam\",\"description\":\"mw 5 to hit, reach 10 ft., one target. {@h}9 (1d12 + 3) bludgeoning damage. If the target is a Large or smaller creature, it must succeed on a 13 Strength saving throw or be pulled into the mud hulk's space and be engulfed by the mud hulk. While engulfed, the target can't breathe, has the restrained condition, and takes 6 (1d12) acid damage at the start of each of its turns. When the mud hulk moves, the engulfed target moves with it. The mud hulk can have only one target engulfed at a time. While a creature is engulfed, the mud hulk can't use its Amorphous trait. An engulfed target can repeat the saving throw at the end of each of its turns. On a successful save, the target escapes and enters the nearest unoccupied space.\"},{\"id\":\"bigbys-mud-hulk-action-1\",\"name\":\"Mud Splash\",\"description\":\"The mud hulk lobs a mass of mud that splashes in a 10-foot-radius sphere centered on a point within 30 feet of the mud hulk. Each creature in that area must make a 13 Dexterity saving throw, taking 10 (2d6 + 3) bludgeoning damage on a failed save, or half as much damage on a successful one. The affected area is difficult terrain until the start of the mud hulk's next turn.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Giant\",\"Terran\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-regisaur\",\"name\":\"Regisaur\",\"description\":\"Regisaur from Bigby Presents: Glory of the Giants.\",\"size\":\"Gargantuan\",\"type\":\"monstrosity\",\"alignment\":\"U\",\"ac\":17,\"hp\":{\"average\":181,\"formula\":\"11d20 + 66\"},\"speed\":\"40 ft.\",\"abilityScores\":{\"strength\":27,\"dexterity\":8,\"constitution\":23,\"intelligence\":4,\"wisdom\":12,\"charisma\":6},\"challengeRating\":\"14\",\"senses\":[\"passive Perception 11\"],\"traits\":[{\"id\":\"bigbys-regisaur-trait-0\",\"name\":\"Magic Resistance\",\"description\":\"The regisaur has advantage on saving throws against spells and other magical effects.\"}],\"actions\":[{\"id\":\"bigbys-regisaur-action-0\",\"name\":\"Multiattack\",\"description\":\"The regisaur makes one Bite attack and one Tail attack. The regisaur can't target the same creature with both attacks.\"},{\"id\":\"bigbys-regisaur-action-1\",\"name\":\"Bite\",\"description\":\"mw 13 to hit, reach 10 ft., one target. {@h}47 (6d12 + 8) piercing damage, and the target has the grappled condition (escape 18). Until this grapple ends, the target has the restrained condition, and the regisaur can't Bite another target.\"},{\"id\":\"bigbys-regisaur-action-2\",\"name\":\"Tail\",\"description\":\"mw 13 to hit, reach 20 ft., one target. {@h}26 (4d8 + 8) bludgeoning damage.\"}],\"bonusActions\":[{\"id\":\"bigbys-regisaur-bonus-0\",\"name\":\"Swallow\",\"description\":\"mw 13 to hit, reach 5 ft., one Huge or smaller creature grappled by the regisaur. {@h}The regisaur swallows the target, and the grapple ends. A swallowed creature has the blinded and restrained conditions, it has 3 against attacks and other effects outside the regisaur, and it takes 7 (2d6) acid damage at the start of each of its turns. The regisaur can have up to two creatures swallowed at a time. If the regisaur takes 25 damage or more on a single turn from a swallowed creature, the regisaur must succeed on a 16 Constitution saving throw at the end of that turn or regurgitate the creature, which falls in a space within 5 feet of the regisaur and has the prone condition; the creature no longer has the blinded and restrained conditions.\"}],\"reactions\":[],\"legendaryActions\":[],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-rime-hulk\",\"name\":\"Rime Hulk\",\"description\":\"Rime Hulk from Bigby Presents: Glory of the Giants.\",\"size\":\"Large\",\"type\":\"elemental\",\"alignment\":\"N E\",\"ac\":15,\"hp\":{\"average\":85,\"formula\":\"9d10 + 36\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":18,\"dexterity\":10,\"constitution\":18,\"intelligence\":8,\"wisdom\":9,\"charisma\":6},\"challengeRating\":\"5\",\"damageImmunities\":[\"cold\",\"poison\"],\"conditionImmunities\":[\"exhaustion\",\"poisoned\"],\"senses\":[\"passive Perception 9\"],\"traits\":[{\"id\":\"bigbys-rime-hulk-trait-0\",\"name\":\"Death Burst\",\"description\":\"When the rime hulk dies, it explodes in a 10-foot-radius sphere of frigid air and frost centered on itself. Each creature in that area must succeed on a 15 Constitution saving throw or take 10 (3d6) cold damage.\"}],\"actions\":[{\"id\":\"bigbys-rime-hulk-action-0\",\"name\":\"Multiattack\",\"description\":\"The rime hulk makes two Slam attacks.\"},{\"id\":\"bigbys-rime-hulk-action-1\",\"name\":\"Slam\",\"description\":\"mw 7 to hit, reach 10 ft., one target. {@h}9 (1d10 + 4) bludgeoning damage plus 9 (2d8) cold damage.\"},{\"id\":\"bigbys-rime-hulk-action-2\",\"name\":\"Trail of Frost 5\",\"description\":\"The rime hulk moves up to its speed without provoking opportunity attacks and can move through the space of any Medium or smaller creature. Each time the rime hulk enters another creature's space for the first time during this move, that creature must make a 15 Constitution saving throw. On a failed save, the creature takes 22 (4d10) cold damage, and its speed is reduced by 10 feet until the start of the rime hulk's next turn. On a successful save, the creature takes half as much damage only.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Aquan\",\"Giant\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-runic-colossus\",\"name\":\"Runic Colossus\",\"description\":\"Runic Colossus from Bigby Presents: Glory of the Giants.\",\"size\":\"Gargantuan\",\"type\":\"construct\",\"alignment\":\"U\",\"ac\":20,\"hp\":{\"average\":315,\"formula\":\"18d20 + 126\"},\"speed\":\"60 ft.\",\"abilityScores\":{\"strength\":25,\"dexterity\":9,\"constitution\":24,\"intelligence\":3,\"wisdom\":11,\"charisma\":1},\"challengeRating\":\"21\",\"damageResistances\":[\"acid\",\"cold\",\"fire\",\"lightning\"],\"damageImmunities\":[\"poison\",\"psychic\",\"bludgeoning\",\"piercing\",\"slashing\",\"from nonmagical attacks\"],\"conditionImmunities\":[\"charmed\",\"exhaustion\",\"frightened\",\"paralyzed\",\"petrified\",\"poisoned\"],\"senses\":[\"darkvision 120 ft., passive Perception 10\"],\"traits\":[{\"id\":\"bigbys-runic-colossus-trait-0\",\"name\":\"Immutable Form\",\"description\":\"The colossus is immune to any spell or effect that would alter its form.\"},{\"id\":\"bigbys-runic-colossus-trait-1\",\"name\":\"Magic Resistance\",\"description\":\"The colossus has advantage on saving throws against spells and other magical effects.\"},{\"id\":\"bigbys-runic-colossus-trait-2\",\"name\":\"Siege Monster\",\"description\":\"The colossus deals double damage to objects and structures.\"}],\"actions\":[{\"id\":\"bigbys-runic-colossus-action-0\",\"name\":\"Multiattack\",\"description\":\"The colossus makes two Slam attacks and then uses Stomp.\"},{\"id\":\"bigbys-runic-colossus-action-1\",\"name\":\"Slam\",\"description\":\"mw 14 to hit, reach 20 ft., one target. {@h}26 (3d12 + 7) bludgeoning damage.\"},{\"id\":\"bigbys-runic-colossus-action-2\",\"name\":\"Stomp\",\"description\":\"mw 14 to hit, reach 20 ft., one target. {@h}29 (4d10 + 7) bludgeoning damage. If the target is a Huge or smaller creature, it must succeed on a 22 Dexterity saving throw or have the prone condition. Until the colossus uses its Stomp again or moves, the creature has the restrained condition. The restrained creature or another creature within 5 feet of it can use its action to make a 22 Strength check. On a successful check, the affected creature relocates to an unoccupied space of its choice within 5 feet of the colossus and is no longer restrained.\"},{\"id\":\"bigbys-runic-colossus-action-3\",\"name\":\"Arcane Beam 5\",\"description\":\"The colossus fires a beam of magical force from its chest, hands, or head in a 150-foot line that is 10 feet wide. Each creature in that area must make a 22 Dexterity saving throw, taking 58 (9d12) force damage on a failed save, or half as much damage on a successful one.\"}],\"bonusActions\":[],\"reactions\":[{\"id\":\"bigbys-runic-colossus-reaction-0\",\"name\":\"Spell Reflection (2/Day)\",\"description\":\"rs 14 to hit, range 120 ft., one creature casting a spell of 5th level or lower. {@h}26 (4d12) force damage, and the target must succeed on a 15 Intelligence saving throw or the spell fails and has no effect.\"}],\"legendaryActions\":[],\"languages\":[\"understands Giant but can't speak\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-scion-of-grolantor\",\"name\":\"Scion of Grolantor\",\"description\":\"Scion of Grolantor from Bigby Presents: Glory of the Giants.\",\"size\":\"Gargantuan\",\"type\":\"giant\",\"alignment\":\"C E\",\"ac\":18,\"hp\":{\"average\":402,\"formula\":\"23d20 + 161\"},\"speed\":\"60 ft.\",\"abilityScores\":{\"strength\":27,\"dexterity\":14,\"constitution\":25,\"intelligence\":15,\"wisdom\":21,\"charisma\":18},\"challengeRating\":\"22\",\"savingThrows\":[\"Wis +12\",\"Cha +11\"],\"skills\":[\"Perception +12\"],\"damageResistances\":[\"cold\",\"fire\",\"lightning\",\"bludgeoning\",\"piercing\",\"slashing\",\"from nonmagical attacks\"],\"damageImmunities\":[\"poison\"],\"conditionImmunities\":[\"exhaustion\",\"paralyzed\",\"poisoned\"],\"senses\":[\"passive Perception 22\"],\"traits\":[{\"id\":\"bigbys-scion-of-grolantor-trait-0\",\"name\":\"Legendary Resistance (6/Day)\",\"description\":\"If the scion fails a saving throw, it can choose to succeed instead.\"},{\"id\":\"bigbys-scion-of-grolantor-trait-1\",\"name\":\"Magic Resistance\",\"description\":\"The scion has advantage on saving throws against spells and other magical effects.\"},{\"id\":\"bigbys-scion-of-grolantor-trait-2\",\"name\":\"Siege Monster\",\"description\":\"The scion deals double damage to objects and structures.\"}],\"actions\":[{\"id\":\"bigbys-scion-of-grolantor-action-0\",\"name\":\"Multiattack\",\"description\":\"The scion makes one Great Tree Club attack and two Slam attacks, or it makes three Boulder attacks.\"},{\"id\":\"bigbys-scion-of-grolantor-action-1\",\"name\":\"Great Tree Club\",\"description\":\"mw 15 to hit, reach 30 ft., one target. {@h}30 (4d10 + 8) bludgeoning damage. If the target is a creature, it must succeed on a 23 Strength saving throw or be pushed horizontally up to 100 feet straight away from the scion and have the prone condition.\"},{\"id\":\"bigbys-scion-of-grolantor-action-2\",\"name\":\"Slam\",\"description\":\"mw 15 to hit, reach 20 ft., one target. {@h}26 (4d8 + 8) force damage.\"},{\"id\":\"bigbys-scion-of-grolantor-action-3\",\"name\":\"Boulder\",\"description\":\"rw 15 to hit, range 120/480 ft., one target. {@h}27 (3d12 + 8) bludgeoning damage.\"},{\"id\":\"bigbys-scion-of-grolantor-action-4\",\"name\":\"Inhale 5\",\"description\":\"The scion inhales a vortex of air in a 120-foot line that is 15 feet wide. Each creature in that area that is Huge or smaller must succeed on a 23 Strength saving throw or be pulled up to 120 feet straight toward the scion and be swallowed. A swallowed creature has the restrained condition, has 3 against attacks and other effects outside the scion, and takes 24 (7d6) force damage at the start of each of the scion's turns. The scion's stomach can hold up to two creatures at a time. If the scion takes 60 damage or more on a single turn from a creature inside it, the scion must succeed on a 17 Constitution saving throw at the end of that turn or regurgitate all swallowed creatures, each of which falls in a space within 10 feet of the scion and has the prone condition. If the scion dies, any swallowed creature no longer has the restrained condition and can escape from the corpse using 15 feet of movement, exiting with the prone condition.\"}],\"bonusActions\":[{\"id\":\"bigbys-scion-of-grolantor-bonus-0\",\"name\":\"Earth-Shaking Movement\",\"description\":\"The scion moves up to its speed and then sends a shock wave through the ground in a 60-foot-radius circle centered on itself. Each creature on the ground in that area that is concentrating must succeed on a 23 Constitution saving throw or lose concentration.\"}],\"reactions\":[{\"id\":\"bigbys-scion-of-grolantor-reaction-0\",\"name\":\"Feed\",\"description\":\"Immediately after taking damage, if it has at least one creature swallowed, the scion deals 10 (3d6) force damage to each swallowed creature and regains 10 hit points.\"}],\"legendaryActions\":[],\"languages\":[\"Giant\",\"Primordial\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-scion-of-memnor\",\"name\":\"Scion of Memnor\",\"description\":\"Scion of Memnor from Bigby Presents: Glory of the Giants.\",\"size\":\"Gargantuan\",\"type\":\"giant\",\"alignment\":\"C N\",\"ac\":20,\"hp\":{\"average\":656,\"formula\":\"32d20 + 320\"},\"speed\":\"60 ft., fly 80 ft.\",\"abilityScores\":{\"strength\":30,\"dexterity\":18,\"constitution\":30,\"intelligence\":24,\"wisdom\":22,\"charisma\":26},\"challengeRating\":\"26\",\"savingThrows\":[\"Dex +12\",\"Cha +16\"],\"skills\":[\"Arcana +15\",\"Perception +14\"],\"damageResistances\":[\"cold\",\"fire\",\"lightning\",\"bludgeoning\",\"piercing\",\"slashing\",\"from nonmagical attacks\"],\"damageImmunities\":[\"thunder\"],\"conditionImmunities\":[\"charmed\",\"frightened\",\"paralyzed\",\"petrified\"],\"senses\":[\"truesight 120 ft., passive Perception 24\"],\"traits\":[{\"id\":\"bigbys-scion-of-memnor-trait-0\",\"name\":\"Flyby\",\"description\":\"The scion doesn't provoke opportunity attacks when it flies out of an enemy's reach.\"},{\"id\":\"bigbys-scion-of-memnor-trait-1\",\"name\":\"Legendary Resistance (6/Day)\",\"description\":\"If the scion fails a saving throw, it can choose to succeed instead.\"},{\"id\":\"bigbys-scion-of-memnor-trait-2\",\"name\":\"Magic Resistance\",\"description\":\"The scion has advantage on saving throws against spells and other magical effects.\"},{\"id\":\"bigbys-scion-of-memnor-trait-3\",\"name\":\"Siege Monster\",\"description\":\"The scion deals double damage to objects and structures.\"}],\"actions\":[{\"id\":\"bigbys-scion-of-memnor-action-0\",\"name\":\"Multiattack\",\"description\":\"The scion makes one attack using Cloud Morningstar or Wind Javelin, as well as two Slam attacks.\"},{\"id\":\"bigbys-scion-of-memnor-action-1\",\"name\":\"Cloud Morningstar\",\"description\":\"mw 18 to hit, reach 30 ft., one target. {@h}32 (4d10 + 10) force damage plus 22 (4d10) thunder damage.\"},{\"id\":\"bigbys-scion-of-memnor-action-2\",\"name\":\"Wind Javelin\",\"description\":\"rw 18 to hit, range 120/480 ft., one target. {@h}42 (5d12 + 10) thunder damage, and the target must succeed on a 26 Strength saving throw or have the prone condition.\"},{\"id\":\"bigbys-scion-of-memnor-action-3\",\"name\":\"Slam\",\"description\":\"mw 18 to hit, reach 20 ft., one target. {@h}28 (4d8 + 10) force damage.\"},{\"id\":\"bigbys-scion-of-memnor-action-4\",\"name\":\"Thunderous Vortex 5\",\"description\":\"The scion magically creates a vortex of wind in a 60-foot-radius sphere centered on a point it can see within 120 feet of itself. Each creature in the sphere must succeed on a 24 Strength saving throw or be pulled straight toward the sphere's center, ending in an unoccupied space as close as possible to the center. Then a burst of thunder erupts in a 30-foot-radius sphere centered on the same point. Each creature in that area takes 52 (8d12) thunder damage and must succeed on a 24 Constitution saving throw or have the stunned condition until the end of its next turn.\"}],\"bonusActions\":[{\"id\":\"bigbys-scion-of-memnor-bonus-0\",\"name\":\"Fog of Deception\",\"description\":\"The scion conjures a magical cloud that fills a 30-foot-radius sphere centered on a point it can see within 90 feet of itself. Each creature in that area must make a 24 Wisdom saving throw. On a failed save, a creature has the charmed condition until the end of its next turn. While it has the charmed condition, the creature must use its action to make a melee attack against a creature other than itself of the scion's choice. If no creature is within its reach, the affected creature makes a ranged attack against a creature of the scion's choice, throwing its weapon if necessary. On a successful save, a creature is immune to the scion's Fog of Deception for the next 24 hours.\"}],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Giant\",\"Primordial\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-scion-of-skoraeus\",\"name\":\"Scion of Skoraeus\",\"description\":\"Scion of Skoraeus from Bigby Presents: Glory of the Giants.\",\"size\":\"Gargantuan\",\"type\":\"giant\",\"alignment\":\"N\",\"ac\":19,\"hp\":{\"average\":444,\"formula\":\"24d20 + 192\"},\"speed\":\"60 ft.\",\"abilityScores\":{\"strength\":29,\"dexterity\":20,\"constitution\":26,\"intelligence\":19,\"wisdom\":24,\"charisma\":14},\"challengeRating\":\"23\",\"savingThrows\":[\"Dex +12\",\"Wis +14\"],\"skills\":[\"Acrobatics +12\",\"Perception +14\"],\"damageResistances\":[\"cold\",\"fire\",\"lightning\",\"bludgeoning\",\"piercing\",\"slashing\",\"from nonmagical attacks\"],\"damageImmunities\":[\"acid\"],\"conditionImmunities\":[\"charmed\",\"frightened\",\"paralyzed\",\"petrified\"],\"senses\":[\"truesight 120 ft., passive Perception 24\"],\"traits\":[{\"id\":\"bigbys-scion-of-skoraeus-trait-0\",\"name\":\"Legendary Resistance (6/Day)\",\"description\":\"If the scion fails a saving throw, it can choose to succeed instead.\"},{\"id\":\"bigbys-scion-of-skoraeus-trait-1\",\"name\":\"Magic Resistance\",\"description\":\"The scion has advantage on saving throws against spells and other magical effects.\"},{\"id\":\"bigbys-scion-of-skoraeus-trait-2\",\"name\":\"Siege Monster\",\"description\":\"The scion deals double damage to objects and structures.\"}],\"actions\":[{\"id\":\"bigbys-scion-of-skoraeus-action-0\",\"name\":\"Multiattack\",\"description\":\"The scion makes one Crystal Club attack and two Slam attacks, then uses Entombing Grasp if available. Alternatively, the scion makes two Runic Boulder attacks.\"},{\"id\":\"bigbys-scion-of-skoraeus-action-1\",\"name\":\"Crystal Club\",\"description\":\"mw 16 to hit, reach 30 ft., one target. {@h}35 (4d12 + 9) bludgeoning damage. {@hom}The scion can cause the club to flare with bright light, and the target must succeed on a 22 Constitution saving throw or take 18 (4d8) radiant damage and have the blinded condition until the start of the scion's next turn.\"},{\"id\":\"bigbys-scion-of-skoraeus-action-2\",\"name\":\"Slam\",\"description\":\"mw 16 to hit, reach 20 ft., one target. {@h}31 (4d10 + 9) force damage.\"},{\"id\":\"bigbys-scion-of-skoraeus-action-3\",\"name\":\"Runic Boulder\",\"description\":\"rw 16 to hit, range 120/480 ft., one target. {@h}27 (4d8 + 9) bludgeoning damage. {@hom}The boulder explodes. The target and each creature within 30 feet of it must make a 22 Dexterity saving throw. On a failed save, a creature takes 19 (3d12) force damage and has the prone condition. On a successful save, a creature takes half as much damage only.\"},{\"id\":\"bigbys-scion-of-skoraeus-action-4\",\"name\":\"Entombing Grasp {@recharge}\",\"description\":\"The scion wreathes its hand in petrifying magic and touches one Huge or smaller creature it can see within 20 feet of itself. The target must succeed on a 24 Dexterity saving throw or take 28 (8d6) force damage and have the grappled condition (escape 19). At the start of the scion's next turn, if the target is still grappled, the target has the petrified condition.\"}],\"bonusActions\":[{\"id\":\"bigbys-scion-of-skoraeus-bonus-0\",\"name\":\"Earth-Shaking Movement\",\"description\":\"The scion moves up to its speed and then sends a shock wave through the ground in a 60-foot radius circle centered on itself. Each creature on the ground in that area that is concentrating must succeed on a 24 Constitution saving throw or lose concentration.\"}],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Giant\",\"Primordial\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-scion-of-stronmaus\",\"name\":\"Scion of Stronmaus\",\"description\":\"Scion of Stronmaus from Bigby Presents: Glory of the Giants.\",\"size\":\"Gargantuan\",\"type\":\"giant\",\"alignment\":\"C G\",\"ac\":20,\"hp\":{\"average\":656,\"formula\":\"32d20 + 320\"},\"speed\":\"60 ft., fly 80 ft., swim 80 ft.\",\"abilityScores\":{\"strength\":30,\"dexterity\":20,\"constitution\":30,\"intelligence\":26,\"wisdom\":28,\"charisma\":24},\"challengeRating\":\"27\",\"savingThrows\":[\"Dex +13\",\"Int +16\"],\"skills\":[\"Arcana +16\",\"History +16\",\"Perception +17\"],\"damageResistances\":[\"cold\",\"fire\",\"bludgeoning\",\"piercing\",\"slashing\",\"from nonmagical attacks\"],\"damageImmunities\":[\"lightning\",\"thunder\"],\"conditionImmunities\":[\"charmed\",\"exhaustion\",\"frightened\",\"paralyzed\",\"petrified\",\"prone\"],\"senses\":[\"truesight 120 ft., passive Perception 27\"],\"traits\":[{\"id\":\"bigbys-scion-of-stronmaus-trait-0\",\"name\":\"Flyby\",\"description\":\"The scion doesn't provoke opportunity attacks when it flies out of an enemy's reach.\"},{\"id\":\"bigbys-scion-of-stronmaus-trait-1\",\"name\":\"Legendary Resistance (6/Day)\",\"description\":\"If the scion fails a saving throw, it can choose to succeed instead.\"},{\"id\":\"bigbys-scion-of-stronmaus-trait-2\",\"name\":\"Magic Resistance\",\"description\":\"The scion has advantage on saving throws against spells and other magical effects.\"},{\"id\":\"bigbys-scion-of-stronmaus-trait-3\",\"name\":\"Siege Monster\",\"description\":\"The scion deals double damage to objects and structures.\"}],\"actions\":[{\"id\":\"bigbys-scion-of-stronmaus-action-0\",\"name\":\"Multiattack\",\"description\":\"The scion makes one attack using Lightning Sword or Hailstone, as well as two Slam attacks.\"},{\"id\":\"bigbys-scion-of-stronmaus-action-1\",\"name\":\"Lightning Sword\",\"description\":\"mw 18 to hit, reach 30 ft., one target. {@h}36 (4d12 + 10) force damage plus 22 (4d10) lightning damage.\"},{\"id\":\"bigbys-scion-of-stronmaus-action-2\",\"name\":\"Hailstone\",\"description\":\"rw 18 to hit, range 120/480 ft., one target. {@h}32 (4d10 + 10) bludgeoning damage plus 18 (4d8) cold damage, and the target must succeed on a 26 Strength saving throw or have the prone condition.\"},{\"id\":\"bigbys-scion-of-stronmaus-action-3\",\"name\":\"Slam\",\"description\":\"mw 18 to hit, reach 20 ft., one target. {@h}36 (4d12 + 10) force damage.\"}],\"bonusActions\":[{\"id\":\"bigbys-scion-of-stronmaus-bonus-0\",\"name\":\"Vengeful Storm {@recharge}\",\"description\":\"The scion conjures a churning storm cloud in a 30-foot-radius, 10-foot-tall cylinder centered on a point within 120 feet of itself. The cloud's area is 2. The cloud lasts for 1 minute, until the scion dies, or when the scion uses this bonus action again. When the cloud appears, and as a bonus action on later turns, the scion can move the cloud up to 30 feet and cause one of the following effects in a 30-foot-radius, 120-foot-high cylinder directly below it; the scion can't choose the same effect two rounds in a row:\"},{\"id\":\"bigbys-scion-of-stronmaus-bonus-1\",\"name\":\"Acid Rain\",\"description\":\"The cloud rains acid. Each creature in the cylinder must succeed on a 25 Constitution saving throw or be covered in acid for 1 minute or until a creature uses its action to remove the acid from itself or another creature. A creature covered in the acid takes 26 (4d12) acid damage at the start of each of its turns.\"},{\"id\":\"bigbys-scion-of-stronmaus-bonus-2\",\"name\":\"Freezing Storm\",\"description\":\"Shards of ice pelt down, and freezing wind fills the area. Each creature in the cylinder must succeed on a 25 Dexterity saving throw or take 28 (8d6) cold damage and be hindered by ice formations for 1 minute or until it or another creature within reach of it uses an action to break away the ice. A creature hindered by ice has its speed reduced to 0.\"},{\"id\":\"bigbys-scion-of-stronmaus-bonus-3\",\"name\":\"Lightning Bolts\",\"description\":\"Bolts of lightning strike down. Each creature in the cylinder must succeed on 25 Dexterity saving throw or take 18 (4d8) lightning damage and have the stunned condition until the end of its next turn.\"}],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Giant\",\"Primordial\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-scion-of-surtur\",\"name\":\"Scion of Surtur\",\"description\":\"Scion of Surtur from Bigby Presents: Glory of the Giants.\",\"size\":\"Gargantuan\",\"type\":\"giant\",\"alignment\":\"L E\",\"ac\":20,\"hp\":{\"average\":546,\"formula\":\"28d20 + 252\"},\"speed\":\"60 ft.\",\"abilityScores\":{\"strength\":30,\"dexterity\":17,\"constitution\":28,\"intelligence\":21,\"wisdom\":24,\"charisma\":20},\"challengeRating\":\"25\",\"savingThrows\":[\"Dex +11\",\"Cha +13\"],\"skills\":[\"Athletics +18\",\"Perception +15\"],\"damageResistances\":[\"cold\",\"lightning\",\"bludgeoning\",\"piercing\",\"slashing\",\"from nonmagical attacks\"],\"damageImmunities\":[\"fire\"],\"conditionImmunities\":[\"charmed\",\"exhaustion\",\"frightened\",\"paralyzed\",\"petrified\"],\"senses\":[\"truesight 120 ft., passive Perception 25\"],\"traits\":[{\"id\":\"bigbys-scion-of-surtur-trait-0\",\"name\":\"Legendary Resistance (6/Day)\",\"description\":\"If the scion fails a saving throw, it can choose to succeed instead.\"},{\"id\":\"bigbys-scion-of-surtur-trait-1\",\"name\":\"Magic Resistance\",\"description\":\"The scion has advantage on saving throws against spells and other magical effects.\"},{\"id\":\"bigbys-scion-of-surtur-trait-2\",\"name\":\"Siege Monster\",\"description\":\"The scion deals double damage to objects and structures.\"}],\"actions\":[{\"id\":\"bigbys-scion-of-surtur-action-0\",\"name\":\"Multiattack\",\"description\":\"The scion makes one attack using Lava Blade or Lava Ball, as well as two Slam attacks.\"},{\"id\":\"bigbys-scion-of-surtur-action-1\",\"name\":\"Lava Blade\",\"description\":\"mw 18 to hit, reach 30 ft., one target. {@h}32 (4d10 + 10) slashing damage plus 18 (4d8) fire damage.\"},{\"id\":\"bigbys-scion-of-surtur-action-2\",\"name\":\"Lava Ball\",\"description\":\"rw 18 to hit, range 120/480 ft., one target. {@h}29 (3d12 + 10) bludgeoning damage plus 10 (3d6) fire damage, and the target must succeed on a 26 Strength saving throw or have the prone condition.\"},{\"id\":\"bigbys-scion-of-surtur-action-3\",\"name\":\"Slam\",\"description\":\"mw 18 to hit, reach 20 ft., one target. {@h}28 (4d8 + 10) force damage.\"},{\"id\":\"bigbys-scion-of-surtur-action-4\",\"name\":\"Lava Wave 5\",\"description\":\"The scion emits a wave of lava from its blade, hands, or mouth in a 90-foot cone. Each creature in that area must make a 25 Dexterity saving throw. On a failed save, a creature takes 60 (11d10) fire damage and has the restrained condition from being embedded in hardening rock. A creature can make a 25 Strength (Athletics) check as an action, freeing itself or a creature within reach from the rock on a success. The rock has AC 17 and 40 hit points, and it is immune to fire, poison, and psychic damage. On a successful save, a creature takes half as much damage only.\"}],\"bonusActions\":[{\"id\":\"bigbys-scion-of-surtur-bonus-0\",\"name\":\"Earth-Shaking Movement\",\"description\":\"The scion moves up to its speed and then sends a shock wave through the ground in a 60-foot-radius circle centered on itself. Each creature on the ground in that area that is concentrating must succeed on a 26 Constitution saving throw or lose concentration.\"},{\"id\":\"bigbys-scion-of-surtur-bonus-1\",\"name\":\"Incendiary Smoke\",\"description\":\"The scion causes smoke and white-hot embers to billow from its skin, filling a 30-foot-radius sphere centered on itself that moves with it. While the scion's skin billows smoke, ranged attacks against the scion are made with disadvantage. A creature that moves into the smoke for the first time on a turn or starts its turn there must succeed on a 25 Constitution saving throw or take 14 (4d6) fire damage. The scion's skin stops billowing smoke after 1 minute, when the scion dies, or when the scion uses this bonus action to stop the smoke.\"}],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Giant\",\"Primordial\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-scion-of-thrym\",\"name\":\"Scion of Thrym\",\"description\":\"Scion of Thrym from Bigby Presents: Glory of the Giants.\",\"size\":\"Gargantuan\",\"type\":\"giant\",\"alignment\":\"N E\",\"ac\":19,\"hp\":{\"average\":499,\"formula\":\"27d20 + 216\"},\"speed\":\"60 ft.\",\"abilityScores\":{\"strength\":30,\"dexterity\":16,\"constitution\":27,\"intelligence\":17,\"wisdom\":20,\"charisma\":21},\"challengeRating\":\"24\",\"savingThrows\":[\"Wis +12\",\"Cha +12\"],\"skills\":[\"Athletics +17\",\"Perception +12\"],\"damageResistances\":[\"fire\",\"lightning\",\"bludgeoning\",\"piercing\",\"slashing\",\"from nonmagical attacks\"],\"damageImmunities\":[\"cold\"],\"conditionImmunities\":[\"charmed\",\"exhaustion\",\"frightened\",\"paralyzed\",\"petrified\"],\"senses\":[\"truesight 120 ft., passive Perception 22\"],\"traits\":[{\"id\":\"bigbys-scion-of-thrym-trait-0\",\"name\":\"Legendary Resistance (6/Day)\",\"description\":\"If the scion fails a saving throw, it can choose to succeed instead.\"},{\"id\":\"bigbys-scion-of-thrym-trait-1\",\"name\":\"Magic Resistance\",\"description\":\"The scion has advantage on saving throws against spells and other magical effects.\"},{\"id\":\"bigbys-scion-of-thrym-trait-2\",\"name\":\"Siege Monster\",\"description\":\"The scion deals double damage to objects and structures.\"}],\"actions\":[{\"id\":\"bigbys-scion-of-thrym-action-0\",\"name\":\"Multiattack\",\"description\":\"The scion makes one Ice Axe and two Slam attacks, or it makes two Glacier Throw attacks.\"},{\"id\":\"bigbys-scion-of-thrym-action-1\",\"name\":\"Ice Axe\",\"description\":\"mw 17 to hit, reach 30 ft., one target. {@h}36 (4d12 + 10) force damage plus 18 (4d8) cold damage.\"},{\"id\":\"bigbys-scion-of-thrym-action-2\",\"name\":\"Slam\",\"description\":\"mw 17 to hit, reach 20 ft., one target. {@h}32 (4d10 + 10) force damage.\"},{\"id\":\"bigbys-scion-of-thrym-action-3\",\"name\":\"Glacier Throw\",\"description\":\"rw 17 to hit, range 120/480 ft., one target. {@h}36 (4d12 + 10) bludgeoning damage plus 14 (4d6) cold damage, and the target must succeed on a 25 Strength saving throw or have the prone condition.\"},{\"id\":\"bigbys-scion-of-thrym-action-4\",\"name\":\"Glacial Upheaval 5\",\"description\":\"The scion digs its hands into the ground at a point it can see within 30 feet of itself and launches a magically conjured mass of ice into the air. Each creature other than the scion in a 30-foot-radius, 100-foot-high cylinder centered on that point must make a 25 Dexterity saving throw. On a failed save, a creature takes 36 (8d8) bludgeoning damage plus 19 (3d12) cold damage and is pushed vertically to the top of the cylinder, at which point the creature falls. On a successful save, a creature takes half as much damage and is pushed to the nearest unoccupied space outside the cylinder with no additional effects. At the start of the scion's next turn, a mass of ice plummets to the ground on a point the scion can see within 60 feet of the point the scion dug its hands into. Each creature in a 30-foot-radius, 100-foot-high cylinder centered on that point must succeed on a 25 Dexterity saving throw or take 18 (4d8) bludgeoning damage plus 18 (4d8) cold damage.\"}],\"bonusActions\":[{\"id\":\"bigbys-scion-of-thrym-bonus-0\",\"name\":\"Earth-Shaking Movement\",\"description\":\"The scion moves up to its speed and sends a shock wave through the ground in a 60-foot-radius circle centered on itself. Each creature on the ground in that area that is concentrating must succeed on a 25 Constitution saving throw or lose concentration.\"}],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Giant\",\"Primordial\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-spectral-cloud\",\"name\":\"Spectral Cloud\",\"description\":\"Spectral Cloud from Bigby Presents: Glory of the Giants.\",\"size\":\"Huge\",\"type\":\"undead\",\"alignment\":\"N\",\"ac\":11,\"hp\":{\"average\":189,\"formula\":\"18d12 + 72\"},\"speed\":\"0 ft., fly 40 ft.\",\"abilityScores\":{\"strength\":24,\"dexterity\":12,\"constitution\":18,\"intelligence\":12,\"wisdom\":17,\"charisma\":16},\"challengeRating\":\"13\",\"savingThrows\":[\"Dex +6\",\"Cha +8\"],\"skills\":[\"Perception +8\"],\"damageResistances\":[\"cold\",\"necrotic\",\"bludgeoning\",\"piercing\",\"slashing\",\"from nonmagical attacks\"],\"damageImmunities\":[\"poison\",\"thunder\"],\"conditionImmunities\":[\"charmed\",\"exhaustion\",\"frightened\",\"grappled\",\"paralyzed\",\"petrified\",\"poisoned\",\"prone\",\"restrained\"],\"senses\":[\"passive Perception 18\"],\"traits\":[{\"id\":\"bigbys-spectral-cloud-trait-0\",\"name\":\"Blurred Form\",\"description\":\"Attack rolls against the spectral cloud are made with disadvantage unless the attacker is within 15 feet of the spectral cloud or the spectral cloud is incapacitated.\"},{\"id\":\"bigbys-spectral-cloud-trait-1\",\"name\":\"Incorporeal Movement\",\"description\":\"The spectral cloud can move through other creatures and objects as if they were difficult terrain. It takes 5 (1d10) force damage if it ends its turn inside an object.\"}],\"actions\":[{\"id\":\"bigbys-spectral-cloud-action-0\",\"name\":\"Multiattack\",\"description\":\"The spectral cloud makes two Spectral Touch attacks.\"},{\"id\":\"bigbys-spectral-cloud-action-1\",\"name\":\"Spectral Touch\",\"description\":\"mw 12 to hit, reach 10 ft., one target. {@h}20 (3d8 + 7) force damage plus 10 (3d6) necrotic damage. If the target is a creature, it must succeed on a 20 Constitution saving throw, or its hit point maximum is reduced by an amount equal to the necrotic damage taken. This reduction lasts until the target finishes a long rest. The target dies if its hit point maximum is reduced to 0. A Humanoid slain by this attack immediately rises as a miniature spectral cloud (use the specter stat block in the Monster Manual). The miniature spectral cloud acts as an ally of its creator but isn't under its control.\"},{\"id\":\"bigbys-spectral-cloud-action-2\",\"name\":\"Chilling Winds 5\",\"description\":\"The spectral cloud emits intensely cold wind in a 60-foot line that is 10 feet wide. Each creature in that area must make a 20 Constitution saving throw. On a failed save, a creature takes 38 (7d10) cold damage and has the incapacitated condition for 1 minute. The affected creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. On a successful save, a creature takes half as much damage only. If a creature's saving throw is successful or the effect ends for it, that creature is immune to this spectral cloud's Chilling Winds for the next 24 hours.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Common\",\"Giant\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-spotted-lion\",\"name\":\"Spotted Lion\",\"description\":\"Spotted Lion from Bigby Presents: Glory of the Giants.\",\"size\":\"Huge\",\"type\":\"beast\",\"alignment\":\"U\",\"ac\":15,\"hp\":{\"average\":66,\"formula\":\"7d12 + 21\"},\"speed\":\"60 ft.\",\"abilityScores\":{\"strength\":23,\"dexterity\":14,\"constitution\":17,\"intelligence\":5,\"wisdom\":13,\"charisma\":10},\"challengeRating\":\"3\",\"skills\":[\"Perception +5\",\"Stealth +6\"],\"senses\":[\"darkvision 60 ft., passive Perception 15\"],\"traits\":[{\"id\":\"bigbys-spotted-lion-trait-0\",\"name\":\"Pack Tactics\",\"description\":\"The lion has advantage on an attack roll against a creature if at least one of the lion's allies is within 5 feet of the target and the ally doesn't have the incapacitated condition.\"}],\"actions\":[{\"id\":\"bigbys-spotted-lion-action-0\",\"name\":\"Rend\",\"description\":\"mw 8 to hit, reach 10 ft., one target. {@h}15 (2d8 + 6) piercing damage. If the lion moved at least 20 feet straight toward the target immediately before the hit, the target must succeed on a 16 Strength saving throw or have the prone condition. If the target has the prone condition, the lion can make another Rend attack against it as a bonus action.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-stalker-of-baphomet\",\"name\":\"Stalker of Baphomet\",\"description\":\"Stalker of Baphomet from Bigby Presents: Glory of the Giants.\",\"size\":\"Huge\",\"type\":\"fiend\",\"alignment\":\"C E\",\"ac\":17,\"hp\":{\"average\":200,\"formula\":\"16d12 + 96\"},\"speed\":\"40 ft.\",\"abilityScores\":{\"strength\":25,\"dexterity\":17,\"constitution\":22,\"intelligence\":13,\"wisdom\":16,\"charisma\":12},\"challengeRating\":\"12\",\"savingThrows\":[\"Dex +7\",\"Wis +7\"],\"skills\":[\"Athletics +15\",\"Perception +7\",\"Stealth +11\"],\"conditionImmunities\":[\"charmed\",\"frightened\"],\"senses\":[\"darkvision 120 ft., passive Perception 17\"],\"traits\":[{\"id\":\"bigbys-stalker-of-baphomet-trait-0\",\"name\":\"Labyrinthine Recall\",\"description\":\"The stalker can perfectly recall any path it has traveled.\"},{\"id\":\"bigbys-stalker-of-baphomet-trait-1\",\"name\":\"Magic Resistance\",\"description\":\"The stalker has advantage on saving throws against spells and other magical effects.\"}],\"actions\":[{\"id\":\"bigbys-stalker-of-baphomet-action-0\",\"name\":\"Multiattack\",\"description\":\"The stalker makes two Glaive attacks or two Rock attacks.\"},{\"id\":\"bigbys-stalker-of-baphomet-action-1\",\"name\":\"Glaive\",\"description\":\"mw 11 to hit, reach 15 ft., one target. {@h}18 (2d10 + 7) slashing damage plus 9 (2d8) force damage.\"},{\"id\":\"bigbys-stalker-of-baphomet-action-2\",\"name\":\"Rock\",\"description\":\"rw 11 to hit, range 60/240 ft., one target. {@h}23 (3d10 + 7) bludgeoning damage. If the target is a Large or smaller creature, it must succeed on a 19 Strength saving throw or have the prone condition. After the stalker throws the rock, roll a d6; on a roll of 3 or lower, the stalker has no more rocks to throw.\"},{\"id\":\"bigbys-stalker-of-baphomet-action-3\",\"name\":\"Erupting Horns 5\",\"description\":\"The stalker causes the earth to churn at a point on the ground it can see within 60 feet of itself. Six horn-shaped stones erupt in a 30-foot-radius, 30-foot-high cylinder centered on that point and then crumble to dust. Each creature in that area must make a 15 Dexterity saving throw. On a failed save, a creature takes 33 (6d10) piercing damage and is pushed up to 30 feet upward and then falls. On a successful save, a creature takes half as much damage only.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Abyssal\",\"Giant\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-stone-giant-of-evil-earth\",\"name\":\"Stone Giant of Evil Earth\",\"description\":\"Stone Giant of Evil Earth from Bigby Presents: Glory of the Giants.\",\"size\":\"Huge\",\"type\":\"giant\",\"alignment\":\"N E\",\"ac\":20,\"hp\":{\"average\":137,\"formula\":\"11d12 + 66\"},\"speed\":\"40 ft.\",\"abilityScores\":{\"strength\":23,\"dexterity\":13,\"constitution\":22,\"intelligence\":10,\"wisdom\":12,\"charisma\":9},\"challengeRating\":\"9\",\"savingThrows\":[\"Str +10\",\"Con +10\"],\"skills\":[\"Athletics +14\",\"Perception +5\"],\"senses\":[\"darkvision 60 ft., passive Perception 15\"],\"traits\":[],\"actions\":[{\"id\":\"bigbys-stone-giant-of-evil-earth-action-0\",\"name\":\"Multiattack\",\"description\":\"The giant makes two Thundering Stone Club or Boulder attacks in any combination.\"},{\"id\":\"bigbys-stone-giant-of-evil-earth-action-1\",\"name\":\"Thundering Stone Club\",\"description\":\"mw 10 to hit, reach 15 ft., one target. {@h}16 (3d6 + 6) bludgeoning damage. The giant can cause the club to emit a burst of thunderous energy that deals 10 (3d6) thunder damage to each creature, other than the giant, within 30 feet of the target. The club can emit a burst this way only once per turn.\"},{\"id\":\"bigbys-stone-giant-of-evil-earth-action-2\",\"name\":\"Boulder\",\"description\":\"rw 10 to hit, range 60/240 ft., one target. {@h}19 (3d8 + 6) bludgeoning damage, and the target must succeed on a 18 Strength saving throw or have the prone condition. After the giant throws the boulder, roll a d6; on a roll of 3 or lower, the giant has no more boulders to throw.\"}],\"bonusActions\":[],\"reactions\":[{\"id\":\"bigbys-stone-giant-of-evil-earth-reaction-0\",\"name\":\"Unyielding\",\"description\":\"In response to failing a saving throw to avoid being moved, having the prone condition, or both, the giant succeeds instead.\"}],\"legendaryActions\":[],\"languages\":[\"Common\",\"Giant\",\"Terran\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-stone-giant-rockspeaker\",\"name\":\"Stone Giant Rockspeaker\",\"description\":\"Stone Giant Rockspeaker from Bigby Presents: Glory of the Giants.\",\"size\":\"Huge\",\"type\":\"giant\",\"alignment\":\"A\",\"ac\":19,\"hp\":{\"average\":276,\"formula\":\"24d12 + 120\"},\"speed\":\"40 ft.\",\"abilityScores\":{\"strength\":23,\"dexterity\":15,\"constitution\":20,\"intelligence\":19,\"wisdom\":14,\"charisma\":10},\"challengeRating\":\"16\",\"savingThrows\":[\"Dex +7\",\"Con +10\",\"Int +9\",\"Wis +7\"],\"skills\":[\"Athletics +16\",\"History +9\",\"Perception +7\"],\"senses\":[\"darkvision 120 ft., passive Perception 17\"],\"traits\":[{\"id\":\"bigbys-stone-giant-rockspeaker-trait-0\",\"name\":\"Legendary Resistance (3/Day)\",\"description\":\"If the giant fails a saving throw, it can choose to succeed instead.\"},{\"id\":\"bigbys-stone-giant-rockspeaker-trait-1\",\"name\":\"Stone Rune\",\"description\":\"The giant has a stone rune inscribed on a mineral object in its possession. While holding or wearing the object bearing the rune, the giant can use its Prismatic Rays action. The object bearing the rune has AC 18; 30 hit points; and immunity to necrotic, poison, and psychic damage. The object regains all its hit points at the end of every turn, but it turns to dust if reduced to 0 hit points or when the giant dies. If the rune is destroyed, the giant can inscribe a stone rune on an object in its possession when it finishes a short or long rest.\"}],\"actions\":[{\"id\":\"bigbys-stone-giant-rockspeaker-action-0\",\"name\":\"Multiattack\",\"description\":\"The giant makes three Prism Staff attacks.\"},{\"id\":\"bigbys-stone-giant-rockspeaker-action-1\",\"name\":\"Prism Staff\",\"description\":\"mw 11 to hit, reach 10 ft., one target. {@h}16 (3d6 + 6) bludgeoning damage plus 13 (3d8) radiant damage.\"},{\"id\":\"bigbys-stone-giant-rockspeaker-action-2\",\"name\":\"Exploding Geode\",\"description\":\"The giant throws a geode at a point within 60 feet of itself, and the geode explodes in a dazzling flash. Each creature in a 20-foot-radius sphere centered on that point must make a 17 Dexterity saving throw. On a failed save, a creature takes 13 (3d8) piercing damage plus 13 (3d8) radiant damage and has the blinded condition until the end of its next turn. On a successful save, a creature takes half as much damage only. After the giant throws the geode, roll a d6; on a roll of 4 or lower, the giant has no more geodes to throw.\"},{\"id\":\"bigbys-stone-giant-rockspeaker-action-3\",\"name\":\"Prismatic Rays (Requires Stone Rune)\",\"description\":\"The giant's stone rune emits beams of light that form a 60-foot cone. Each creature in that area must make a 17 Dexterity saving throw. For each creature in that area, roll a d6 to determine what ray affects it:\"},{\"id\":\"bigbys-stone-giant-rockspeaker-action-4\",\"name\":\"1-2: Blazing Red\",\"description\":\"On a failed save, the creature takes 35 (10d6) radiant damage and has the blinded condition until the end of the giant's next turn. On a successful save, the creature takes half as much damage only.\"},{\"id\":\"bigbys-stone-giant-rockspeaker-action-5\",\"name\":\"3-4: Dreadful Blue\",\"description\":\"On a failed save, the creature takes 35 (10d6) necrotic damage and has the frightened condition until the end of the giant's next turn. On a successful save, the creature takes half as much damage only.\"},{\"id\":\"bigbys-stone-giant-rockspeaker-action-6\",\"name\":\"5-6: Sapping Green\",\"description\":\"On a failed save, the creature takes 35 (10d6) force damage and has the incapacitated condition until the end of the giant's next turn. On a successful save, the creature takes half as much damage only.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Common\",\"Giant\",\"Terran\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-storm-crab\",\"name\":\"Storm Crab\",\"description\":\"Storm Crab from Bigby Presents: Glory of the Giants.\",\"size\":\"Gargantuan\",\"type\":\"monstrosity\",\"alignment\":\"U\",\"ac\":18,\"hp\":{\"average\":155,\"formula\":\"10d20 + 50\"},\"speed\":\"40 ft., swim 60 ft.\",\"abilityScores\":{\"strength\":23,\"dexterity\":10,\"constitution\":21,\"intelligence\":5,\"wisdom\":14,\"charisma\":9},\"challengeRating\":\"11\",\"savingThrows\":[\"Str +10\",\"Con +9\"],\"skills\":[\"Perception +6\"],\"damageResistances\":[\"cold\",\"fire\",\"lightning\"],\"senses\":[\"blindsight 60 ft., passive Perception 16\"],\"traits\":[{\"id\":\"bigbys-storm-crab-trait-0\",\"name\":\"Amphibious\",\"description\":\"The crab can breathe air and water.\"}],\"actions\":[{\"id\":\"bigbys-storm-crab-action-0\",\"name\":\"Multiattack\",\"description\":\"The crab makes two Claw attacks and one Stinger attack.\"},{\"id\":\"bigbys-storm-crab-action-1\",\"name\":\"Claw\",\"description\":\"mw 10 to hit, reach 15 ft., one target. {@h}19 (3d8 + 6) bludgeoning damage. If the target is a Huge or smaller creature, it has the grappled condition (escape 16). The crab has four claws, each of which can grapple one target.\"},{\"id\":\"bigbys-storm-crab-action-2\",\"name\":\"Stinger\",\"description\":\"mw 10 to hit, reach 10 ft., one creature. {@h}22 (3d10 + 6) piercing damage, and the target must succeed on a 17 Constitution saving throw or have the poisoned and paralyzed conditions for 1 minute. The affected creature can repeat the saving throw at the end of each of its turns, ending both the poisoned and paralyzed conditions on itself on a success.\"},{\"id\":\"bigbys-storm-crab-action-3\",\"name\":\"Water Jet 5\",\"description\":\"The crab exhales water in a 150-foot line that is 10 feet wide. Each creature in that area must make a 17 Dexterity saving throw. On a failed save, a creature takes 27 (6d8) bludgeoning damage, is pushed up to 30 feet from the crab, and has the prone condition. On a successful save, a creature takes half as much damage only.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"understands Giant but can't speak\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-storm-giant-tempest-caller\",\"name\":\"Storm Giant Tempest Caller\",\"description\":\"Storm Giant Tempest Caller from Bigby Presents: Glory of the Giants.\",\"size\":\"Huge\",\"type\":\"giant\",\"alignment\":\"A\",\"ac\":17,\"hp\":{\"average\":310,\"formula\":\"27d12 + 135\"},\"speed\":\"50 ft., fly 50 ft., swim 50 ft.\",\"abilityScores\":{\"strength\":29,\"dexterity\":14,\"constitution\":20,\"intelligence\":21,\"wisdom\":18,\"charisma\":25},\"challengeRating\":\"20\",\"savingThrows\":[\"Str +15\",\"Con +11\",\"Wis +10\",\"Cha +13\"],\"skills\":[\"Arcana +17\",\"Athletics +15\",\"Perception +10\"],\"damageResistances\":[\"cold\"],\"damageImmunities\":[\"lightning\",\"thunder\"],\"senses\":[\"truesight 120 ft., passive Perception 20\"],\"traits\":[{\"id\":\"bigbys-storm-giant-tempest-caller-trait-0\",\"name\":\"Alert\",\"description\":\"The giant can't be surprised, and it has advantage on initiative rolls.\"},{\"id\":\"bigbys-storm-giant-tempest-caller-trait-1\",\"name\":\"Amphibious\",\"description\":\"The giant can breathe air and water.\"},{\"id\":\"bigbys-storm-giant-tempest-caller-trait-2\",\"name\":\"Legendary Resistance (3/Day)\",\"description\":\"If the giant fails a saving throw, it can choose to succeed instead.\"},{\"id\":\"bigbys-storm-giant-tempest-caller-trait-3\",\"name\":\"Scrying (Requires Storm Rune)\",\"description\":\"The giant can use its crystal ball to cast the scrying spell (save 17).\"},{\"id\":\"bigbys-storm-giant-tempest-caller-trait-4\",\"name\":\"Storm Rune\",\"description\":\"The giant has a storm rune inscribed on a crystal ball. While the object bearing the rune is embedded in its body, the giant can use its Tempest Call action and its Scrying trait. The object bearing the storm rune has AC 17; 50 hit points; and immunity to necrotic, poison, and psychic damage. The object regains all its hit points at the end of every turn, but it turns to dust if reduced to 0 hit points or when the giant dies. If the rune is destroyed, the giant can inscribe a storm rune on another crystal ball in its possession when it finishes a short or long rest.\"}],\"actions\":[{\"id\":\"bigbys-storm-giant-tempest-caller-action-0\",\"name\":\"Multiattack\",\"description\":\"The giant makes three Lightning Blade or Lightning Lance attacks.\"},{\"id\":\"bigbys-storm-giant-tempest-caller-action-1\",\"name\":\"Lightning Blade\",\"description\":\"mw 15 to hit, reach 10 ft., one target. {@h}22 (3d8 + 9) slashing damage plus 16 (3d10) lightning damage.\"},{\"id\":\"bigbys-storm-giant-tempest-caller-action-2\",\"name\":\"Lightning Lance\",\"description\":\"rs 13 to hit, range 500 ft., one target. {@h}39 (5d12 + 7) lightning damage.\"},{\"id\":\"bigbys-storm-giant-tempest-caller-action-3\",\"name\":\"Tempest Call (Requires Storm Rune)\",\"description\":\"The giant creates an elemental vortex that fills a 60-foot-radius sphere centered on itself. Each creature in that area other than the giant must make a 21 Dexterity saving throw. On a failed save, a creature takes 43 (8d8 + 7) damage of a type of the giant's choosing: cold, lightning, or thunder. On a successful save, a creature takes half as much damage.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Common\",\"Giant\",\"Primordial\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-storm-herald\",\"name\":\"Storm Herald\",\"description\":\"Storm Herald from Bigby Presents: Glory of the Giants.\",\"size\":\"Huge\",\"type\":\"aberration\",\"alignment\":\"L E\",\"ac\":16,\"hp\":{\"average\":287,\"formula\":\"23d12 + 138\"},\"speed\":\"50 ft., swim 100 ft.\",\"abilityScores\":{\"strength\":27,\"dexterity\":14,\"constitution\":22,\"intelligence\":24,\"wisdom\":18,\"charisma\":18},\"challengeRating\":\"17\",\"savingThrows\":[\"Wis +10\",\"Cha +10\"],\"skills\":[\"Arcana +13\",\"Deception +10\",\"Perception +10\"],\"damageResistances\":[\"cold\",\"psychic\"],\"damageImmunities\":[\"lightning\",\"thunder\"],\"conditionImmunities\":[\"charmed\",\"frightened\"],\"senses\":[\"darkvision 120 ft., passive Perception 20\"],\"traits\":[{\"id\":\"bigbys-storm-herald-trait-0\",\"name\":\"Amphibious\",\"description\":\"The herald can breathe air and water.\"},{\"id\":\"bigbys-storm-herald-trait-1\",\"name\":\"Magic Resistance\",\"description\":\"The herald has advantage on saving throws against spells and other magical effects.\"}],\"actions\":[{\"id\":\"bigbys-storm-herald-action-0\",\"name\":\"Multiattack\",\"description\":\"The herald makes one Claw attack, one Tentacles attack, and one Trident attack.\"},{\"id\":\"bigbys-storm-herald-action-1\",\"name\":\"Claw\",\"description\":\"mw 14 to hit, reach 10 ft., one target. {@h}18 (3d6 + 8) slashing damage.\"},{\"id\":\"bigbys-storm-herald-action-2\",\"name\":\"Tentacles\",\"description\":\"mw 14 to hit, reach 10 ft., one target. {@h}21 (3d8 + 8) bludgeoning damage. If the target is a Large or smaller creature, it has the grappled condition (escape 18). It also has the restrained condition and takes 16 (3d10) psychic damage at the start of each of its turns until this grapple ends. The herald can have only one creature grappled this way at a time.\"},{\"id\":\"bigbys-storm-herald-action-3\",\"name\":\"Trident\",\"description\":\"mw 14 to hit, reach 10 ft., one target. {@h}18 (3d6 + 8) piercing damage or 21 (3d8 + 8) piercing damage if used with two hands, plus 13 (3d8) lightning damage.\"},{\"id\":\"bigbys-storm-herald-action-4\",\"name\":\"Psychic Wave {@recharge}\",\"description\":\"The herald unleashes a blast of psionic energy into the minds of up to three creatures it can see within 90 feet of itself. Each target must make a 21 Intelligence saving throw. On a failed save, a target takes 23 (3d10 + 7) psychic damage and has the stunned condition for 1 minute. On a successful save, a target takes half as much damage only. An affected creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success. If a creature is reduced to 0 hit points by this psychic damage, it dies and its head explodes if it has one.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Common\",\"Giant\",\"telepathy 120 ft.\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-tempest-spirit\",\"name\":\"Tempest Spirit\",\"description\":\"Tempest Spirit from Bigby Presents: Glory of the Giants.\",\"size\":\"Huge\",\"type\":\"undead\",\"alignment\":\"C E\",\"ac\":12,\"hp\":{\"average\":195,\"formula\":\"17d12 + 85\"},\"speed\":\"0 ft., fly 60 ft.\",\"abilityScores\":{\"strength\":24,\"dexterity\":14,\"constitution\":20,\"intelligence\":16,\"wisdom\":18,\"charisma\":19},\"challengeRating\":\"15\",\"savingThrows\":[\"Con +10\",\"Int +8\",\"Wis +9\",\"Cha +9\"],\"skills\":[\"Arcana +8\",\"Perception +9\"],\"damageResistances\":[\"cold\",\"necrotic\",\"poison\",\"bludgeoning\",\"piercing\",\"slashing\",\"from nonmagical attacks\"],\"damageImmunities\":[\"lightning\",\"thunder\"],\"conditionImmunities\":[\"charmed\",\"exhaustion\",\"frightened\",\"grappled\",\"paralyzed\",\"petrified\",\"poisoned\",\"prone\",\"restrained\"],\"senses\":[\"passive Perception 19\"],\"traits\":[{\"id\":\"bigbys-tempest-spirit-trait-0\",\"name\":\"Incorporeal Movement\",\"description\":\"The spirit can move through other creatures and objects as if they were difficult terrain. The spirit takes 5 (1d10) force damage if it ends its turn inside an object.\"},{\"id\":\"bigbys-tempest-spirit-trait-1\",\"name\":\"Legendary Resistance (3/Day)\",\"description\":\"If the spirit fails a saving throw, it can choose to succeed instead.\"}],\"actions\":[{\"id\":\"bigbys-tempest-spirit-action-0\",\"name\":\"Multiattack\",\"description\":\"The spirit makes two Lightning Fist or Hailstone attacks in any combination.\"},{\"id\":\"bigbys-tempest-spirit-action-1\",\"name\":\"Lightning Fist\",\"description\":\"mw 12 to hit, reach 10 ft., one target. {@h}25 (4d8 + 7) lightning damage.\"},{\"id\":\"bigbys-tempest-spirit-action-2\",\"name\":\"Hailstone\",\"description\":\"rw 12 to hit, range 90/180 ft., one target. {@h}17 (3d6 + 7) bludgeoning damage plus 7 (2d6) cold damage.\"},{\"id\":\"bigbys-tempest-spirit-action-3\",\"name\":\"Death Bolt 5\",\"description\":\"The spirit hurls a magical lightning bolt in a 120-foot line that is 10 feet wide. Each creature in that area must make a 18 Dexterity saving throw, taking 27 (6d8) lightning damage plus 16 (3d10) necrotic damage on a failed save, or half as much damage on a successful one. On a success or failure, an affected creature's hit point maximum is reduced by an amount equal to the necrotic damage taken. This reduction lasts until the creature finishes a long rest. The creature dies if its hit point maximum is reduced to 0.\"}],\"bonusActions\":[{\"id\":\"bigbys-tempest-spirit-bonus-0\",\"name\":\"Hailstorm 4\",\"description\":\"The spirit conjures a hailstorm in a 20-foot-radius, 40-foot-high cylinder centered on a point it can see within 120 feet of itself. Each creature in that area must make a 17 Dexterity saving throw. On a failed save, a creature takes 10 (3d6) bludgeoning damage plus 10 (3d6) cold damage and has the prone condition. On a successful save, a creature takes half as much damage only.\"}],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Common\",\"Giant\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-titanothere\",\"name\":\"Titanothere\",\"description\":\"Titanothere from Bigby Presents: Glory of the Giants.\",\"size\":\"Huge\",\"type\":\"beast\",\"alignment\":\"U\",\"ac\":16,\"hp\":{\"average\":136,\"formula\":\"13d12 + 52\"},\"speed\":\"50 ft.\",\"abilityScores\":{\"strength\":25,\"dexterity\":10,\"constitution\":19,\"intelligence\":2,\"wisdom\":12,\"charisma\":6},\"challengeRating\":\"5\",\"senses\":[\"passive Perception 11\"],\"traits\":[{\"id\":\"bigbys-titanothere-trait-0\",\"name\":\"Beast of Burden\",\"description\":\"The titanothere is considered to be one size larger for the purpose of determining its carrying capacity.\"}],\"actions\":[{\"id\":\"bigbys-titanothere-action-0\",\"name\":\"Stomp\",\"description\":\"mw 10 to hit, reach 10 ft., one target. {@h}20 (3d8 + 7) bludgeoning damage. If the titanothere moved at least 20 feet straight toward the target immediately before the hit, the target takes an extra 13 (3d8) bludgeoning damage, and the target must succeed on a 18 Strength saving throw or have the prone condition if it is a creature.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-troll-amalgam\",\"name\":\"Troll Amalgam\",\"description\":\"Troll Amalgam from Bigby Presents: Glory of the Giants.\",\"size\":\"Gargantuan\",\"type\":\"giant\",\"alignment\":\"C E\",\"ac\":15,\"hp\":{\"average\":217,\"formula\":\"14d20 + 70\"},\"speed\":\"60 ft., climb 60 ft.\",\"abilityScores\":{\"strength\":25,\"dexterity\":14,\"constitution\":21,\"intelligence\":9,\"wisdom\":16,\"charisma\":5},\"challengeRating\":\"17\",\"savingThrows\":[\"Con +11\",\"Wis +9\"],\"skills\":[\"Perception +9\"],\"damageResistances\":[\"poison\",\"bludgeoning\",\"piercing\",\"slashing\",\"from nonmagical attacks\"],\"conditionImmunities\":[\"charmed\",\"frightened\",\"poisoned\"],\"senses\":[\"darkvision 120 ft., passive Perception 19\"],\"traits\":[{\"id\":\"bigbys-troll-amalgam-trait-0\",\"name\":\"Legendary Resistance (3/Day)\",\"description\":\"If the amalgam fails a saving throw, it can choose to succeed instead.\"},{\"id\":\"bigbys-troll-amalgam-trait-1\",\"name\":\"Magic Resistance\",\"description\":\"The amalgam has advantage on saving throws against spells and other magical effects.\"},{\"id\":\"bigbys-troll-amalgam-trait-2\",\"name\":\"Regeneration\",\"description\":\"The amalgam regains 15 hit points at the start of its turn. If the amalgam takes acid or fire damage, it regains only 5 hit points at the start of its next turn. The amalgam dies only if it takes 20 or more acid or fire damage while it has 0 hit points.\"}],\"actions\":[{\"id\":\"bigbys-troll-amalgam-action-0\",\"name\":\"Multiattack\",\"description\":\"The amalgam makes three Rend attacks.\"},{\"id\":\"bigbys-troll-amalgam-action-1\",\"name\":\"Rend\",\"description\":\"mw 13 to hit, reach 15 ft., one target. {@h}25 (4d8 + 7) slashing damage.\"}],\"bonusActions\":[{\"id\":\"bigbys-troll-amalgam-bonus-0\",\"name\":\"Fling Limb (3/Day)\",\"description\":\"rw 13 to hit, range 60/240 ft., one target. {@h}11 (1d8 + 7) bludgeoning damage. If the limb hits a Medium or smaller creature, that creature has the grappled condition (escape 17). The limb has the statistics of a troll amalgam, except for the following: it is Medium, it has 45 hit points, its speed is 30 ft., it doesn't have a challenge rating or Legendary Resistance, and the only action it can take is the Attack action, which it can use only to grapple. Until this grapple ends, the target has the restrained condition and takes 25 (4d8 + 7) slashing damage at the start of each of its turns. If the limb is not destroyed within 24 hours of being flung, roll a d12; on a roll of 12, the limb regenerates into a troll (see the Monster Manual). Otherwise, the limb withers away.\"}],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Giant\",\"Undercommon\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"},{\"id\":\"bigbys-troll-mutate\",\"name\":\"Troll Mutate\",\"description\":\"Troll Mutate from Bigby Presents: Glory of the Giants.\",\"size\":\"Large\",\"type\":\"giant\",\"alignment\":\"C E\",\"ac\":16,\"hp\":{\"average\":95,\"formula\":\"10d10 + 40\"},\"speed\":\"30 ft., fly 30 ft.\",\"abilityScores\":{\"strength\":19,\"dexterity\":13,\"constitution\":18,\"intelligence\":17,\"wisdom\":9,\"charisma\":12},\"challengeRating\":\"7\",\"savingThrows\":[\"Con +7\",\"Int +6\"],\"skills\":[\"Perception +5\",\"Stealth +4\"],\"senses\":[\"blindsight 60 ft., passive Perception 15\"],\"traits\":[{\"id\":\"bigbys-troll-mutate-trait-0\",\"name\":\"Mutation\",\"description\":\"When the troll mutate is created, it gains one of four possible body mutations at random: 1, Elastic Body; 2, Psionic Mirror; 3, Spell Scarred; or 4, Winged Form. This mutation determines certain traits in this stat block.\"},{\"id\":\"bigbys-troll-mutate-trait-1\",\"name\":\"Amorphous (Elastic Body Only)\",\"description\":\"The mutate can move through a space as narrow as 1 inch without squeezing.\"},{\"id\":\"bigbys-troll-mutate-trait-2\",\"name\":\"Magic Resistance (Spell Scarred Only)\",\"description\":\"The mutate has advantage on saving throws against spells and other magical effects.\"},{\"id\":\"bigbys-troll-mutate-trait-3\",\"name\":\"Psychic Rebuke (Psionic Mirror Only)\",\"description\":\"If the mutate takes psychic damage, each creature within 20 feet of it takes that damage as well.\"},{\"id\":\"bigbys-troll-mutate-trait-4\",\"name\":\"Regeneration\",\"description\":\"The mutate regains 10 hit points at the start of its turn. If the mutate takes acid or fire damage, this trait doesn't function at the start of the mutate's next turn. The mutate dies only if it starts its turn with 0 hit points and doesn't regenerate. If the mutate starts its turn with 0 hit points and regenerates, it randomly gains a mutation it doesn't already have (up to a maximum of four mutations).\"}],\"actions\":[{\"id\":\"bigbys-troll-mutate-action-0\",\"name\":\"Multiattack\",\"description\":\"The mutate makes two Rend attacks.\"},{\"id\":\"bigbys-troll-mutate-action-1\",\"name\":\"Rend\",\"description\":\"mw 7 to hit, reach 5 ft. (or 15 ft. if the mutate has the Elastic Body mutation), one target. {@h}15 (2d10 + 4) slashing damage plus 9 (2d8) force damage.\"},{\"id\":\"bigbys-troll-mutate-action-2\",\"name\":\"Psychic Burst 5\",\"description\":\"The mutate unleashes a wave of psychic energy. Each creature within 30 feet of the mutate must make a 14 Intelligence saving throw, taking 28 (8d6) psychic damage on a failed save, or half as much damage on a successful one.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Giant\",\"telepathy 60 ft.\"],\"source\":\"Bigby Presents: Glory of the Giants\",\"sourceId\":\"bigbys\"}],\"ua\":[]},\"note\":\"Converted from 5etools JSON filtered to source \\\"BGG\\\" downloaded from https://5e.tools/book.html#BGG.\",\"notes\":[\"Converted from 5etools JSON filtered to source \\\"BGG\\\" downloaded from https://5e.tools/book.html#BGG.\"],\"documents\":[],\"sections\":[],\"meta\":{\"origin\":\"imported-json\",\"importedAt\":\"2026-10-14T04:14:04.395Z\",\"parser\":\"5etools-adapter\",\"visibility\":\"private\"}}");

